(window.GIM_TP=window.GIM_TP||{})["Z.SifraDiTzniuta.0"]={"from":0,"a":[[["\u0003ספרא דצניעותא\u0004 מַאן צְנִיעוּתָא דְּסִפְרָא. אָמַר רִבִּי שִׁמְעוֹן, חֲמִשָׁה פִּרְקִין אִינּוּן דְּכְלִילָן בְּהֵיכָל רַב, וּמַלְיָין כָּל אַרְעָא. אָמַר רִבִּי יְהוּדָה, אִי כְּלִילָן הָנֵי, מִכֻּלְּהוּ עֲדִיפֵי. אָמַר רִבִּי שִׁמְעוֹן, הָכִי הוּא, לְמַאן דְּעָאל וְנָפַק, וּלְמָאן דְּלָא עָאל ונָפַק לָאו הָכִי."],[[0,"מאן צניעותא דספרא:","שואל, מהו צניעותא דספרא. אמר רבי שמעון חמשה פרקים הם הכלולים בהיכל רב וממלאים כל הארץ. א\"ר יהודה אם אלו כלולים מכל החכמה, הרי אלו טובים יותר מכולם, ולא צריכים ללמוד יותר. אמר ר' שמעון כך הוא למי שנכנס בחכמה ויצא ממנה בשלום, הוא רואה כאן התכללות כל החכמה. אבל מי שלא נכנס בחכמה ויצא ממנה בשלום, אינו כן."],[0,"","והביאור הוא. כי הנכנס להיכל החכמה ויוצא משם מחמת פגם, אינו נחשב, לעאל ונפיק, כי לא יצא מרצונו, אלא שגרשוהו משם מחמת פגם. אלא מי שאין לו שום פגם ויוצא מן ההיכל מדעתו ורצונו, כאדם הנכנס ויוצא בביתו, הוא כבן בית שמה, והשכינה מגלית לו כל מחמדיה וסתריה, ולא מעלימה ממנו דבר, הוא נחשב לעאל ונפיק."]],[]],[["מַתְלָא, לְבַר נָשׁ דְּהֲוָה דִּיוּרֵיהּ בֵּינֵי טוּרִין, וְלָא יָדַע בְּדִּיוּרֵי מָתָא. זָרַע חִטִּין. וְאָכִיל חִטֵּי בְּגוּפַיְיהוּ. יוֹמָא חַד עָאל לְמָתָא, אַקְרִיבוּ לֵיהּ נַהֲמָא טָבָא. אֲמַר הַהוּא בַּר נָשׁ, דְּנָא לָמָּה. אֲמַרוּ נַהֲמָא הוּא לְמֵיכַל. אָכַל וְטָעַם לְחָדָא לְחִכֵּיהּ. אֲמַר וּמִמָּה אִתְעָבִיד דָּא. אֲמַרוּ מֵחִטִין. לְבָתַר אַקְרִיבוּ לֵיהּ גְּרִיצִין דְּלִישִׁין בְּמִשְׁחָא. טָעַם מִנַּיְיהוּ, אֲמַר וְאִלֵּין מִמַּה אִתְעֲבִידוּ. אֲמַרוּ מֵחִטִין. לְבָתַר אַקְרִיבוּ לֵיהּ טְרִיקֵי מַלְכִין, דְּלִישִׁין בְּדּוּבְשָׁא וּמִשְׁחָא. אֲמַר וְאִלֵּין מִמַּה אִתְעָבִידוּ. אֲמַרוּ מֵחִטִין. אֲמַר וַדַּאי אֲנָא מָארֵי דְּכָל אִלֵּין, דַּאֲנָא אָכִיל עִקָּרָא דְּכָל אִלֵּין דְּאִיהוּ חִטָּה. בְּגִין הַהוּא דַּעְתָּא מֵעִדוּנֵי עָלְמָא לָא יָדַע וְאִתְאֲבִידוּ מִנֵּיהּ. כַּךְ, מַאן דְּנָקִיט כְּלָלָא, וְלָא יָדַע בְּכֻלְּהוּ עִדוּנִין דִּמְהַנְיָין, דְּנַפְקִין מֵהַהוּא כְּלָלָא.","\u0003ספרא דצניעותא פרקא קדמאה\u0004 תָּאנָא. סִפְרָא דְּצְנִיעוּתָא, סִפְרָא, דְּשָׁקִיל (רל\"ה ע\"א) בְּמַתְקְלָא. (תאנא) דְּעַד דְּלָא הֲוָה מַתְקְלָא, לָא הֲווֹ מַשְׁגִּיחִין אַפִּין בְּאַפִּין, וּמַלְכִין קַדְמָאִין מִיתוּ, וְזִיוּנֵיהוֹן לָא אִשְׁתַּכְּחוּ, וְאַרְעָא אִתְבַּטְּלָת.","עַד דְּרֵישָׁא דְּכִסּוּפָא דְּכָל כִּסוּפִין, לְבוּשֵׁי דִּיקָר אַתְקִין, וְאַחֲסִין.","הַאי מַתְקְלָא תָּלֵי בַּאֲתַר דְּלָא הֲוָה, אִתְּקָלוּ בֵּיהּ אִינּוּן דְּלָא אִשְׁתַּכְּחוּ. מַתְקְלָא קָאִים בְּגוּפֵיהּ. לָא אִתְאֲחָד, וְלָא אִתְחָזֵי. בֵּיהּ סְלִיקוּ, וּבֵיהּ סָלְקִין דְּלָא הֲווֹ, וַהֲווּ, וְיְהוְיָּין.","סִתְרָא גּוֹ סִתְרָא, אִתְתְּקָּן ואִזְדְּמַן, (אד\"ר קכ\"ח ע\"ב, באד\"ז רפ\"ז, רפ\"ח ע\"א) בְּחַד גּוּלְגַלְתָּא, מַלְיָיא טַלָּא דִּבְדוֹלְחָא. (שם אד\"ר קכ\"ט) קְרוּמָא דְּאַוִּירָא אִזְדָּכָךְ וְסָתִים, אִינּוּן עֲמָר נְקֵי תַּלְיָין בְּשִּׁקוּלָא. רַעֲוָא (אד\"ז שם) דְּרַעֲוִין אִתְגַּלְיָא בִּצְלוֹתָא דְּתַתָּאֵי. אַשְׁגָּחָא פְּקִיחָא דְּלָא נָאִים, וְנָטִיר תְּדִירָא. אַשְׁגָּחוּתָא דְּתַתָּא בְּאַשְׁגָּחוּתָא דִּנְהִירוּ דְּעִלָּאָה. (דביה) תְּרִין נוּקְבִין דְּפַרְדַּשְׂקָא, דְּאִתְּעַר רוּחָא לְכֹלָּא.","בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, שִׁיתָא בְּרֵאשִׁית (ברא שית) עָלַיְיהוּ, כּוּלְהוּ לְתַתָּא, וְתַלְיָין מִשִּׁבְעָה דְּגּוּלְגְלָתָא עַד יְקִירוּ דְּיַקִירוּתָא, וְהָאָרֶץ תִּנְיָינָא לָאו בְּחוּשְׁבָּן וְהָא אִתְּמַר. וּמֵהַהִיא דְּאִתְלַטְּיָיא נָפְקָא, דְּכְתִּיב (בראשית ה׳:כ״ט) מִן הָאֲדָמָה אֲשֶׁר אֵרַרָה יְיָ'. הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ עַל פְּנֵי תְּהוֹם וְרוּחַ אֱלהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם. תְּלֵיסַר, תַּלְיָין בִּתְלֵיסָר יְקִירוּ דְּיַקִירוּתָא.","שִׁיתָא אַלְפֵי שְׁנִין, תַּלְיָין בְּשִׁיתָא קַדְמָאֵי, שְׁבִיעָאָה עָלַיְיהוּ, דְּאִתְתָּקַּף בִּלְחוֹדוֹי. וְאִתְחָרִיב כֹּלָּא בִּתְרֵיסַר שַׁעְתֵּי, דְּכְתִּיב הָיְתָה תֹהוּ וָבֹהוּ וְגוֹ'. תְּלֵיסַר יְקִים לוֹן בְּרַחֲמֵי, וּמִתְחַדְּשָׁן בְּקַדְמִיתָא, וְקָמוּ (ס\"י קמו) כָּל אִינּוּן שִׁיתָא. בְּגִין דְּכְתִּיב בָּרָא, וּלְבָתַר כְּתִיב הָיְתָה, דְּהָא הֲוַת וַדַּאי, וּלְבַסּוֹף תֹהוּ וָבֹהוּ וְחֹשֶׁךְ, (ישעיהו ב׳:י״א) וְנִשְׂגַּב יְיָ' לְבַדּוֹ בְּיוֹם הַהוּא.","גִּלוּפֵי דִּגְלִיפִין כְּחֵיזוּ דְּחִוְיָא אָרִיךְ, וּמִתְפָּשַּׁט לְכָאן וּלְכָאן, זַנְבָא בְּרֵישָׁא. רֵישָׁא (אחורא) אָחִיד אַכַתְפִין, אַעְבַּר וְזָעִים, נְטַר וְגָנִיז. חַד לְאֶלֶף יוֹמִין זְעִירִין אִתְגָּלְיָיא, (נ\"א אתמלייא) קוּלְטְרָא בְּקִטְרוֹי, סְנַפִּירָא בְּעַדְבוֹי, אִתְבַּר רֵישֵׁיהּ בְּמַיִין דְיַמָּא רַבָּא, דְּכְתִּיב (תהילים ע״ד:י״ג) שִׁבַּרְתָּ רָאשֵׁי תַּנִּינִים עַל הַמָּיִם. תְּרֵין הֲווֹ, חַד אִתְחֲזָרֵי, (ל\"ד ע\"ב) תַּנִּינָם כְּתִיב חָסֵר. רָאשֵׁי, כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ.","וַיֹּאמֶר אֱלהִים יְהִי אוֹר וַיְהִי אוֹר, הַיְינוּ דְּכְתִּיב (תהלים לג) כִּי הוּא אָמַר וַיֶּהִי, הוּא בִּלְחוֹדוֹי. לְבָתַר אִתְחַזְרוּ חַד יהו\"י יה\"ו ו\"י ו' בַּתְרָאָה שְׁכִינְתָּא לְתַתָּא. כְּמָה דְּה' שְׁכִינְתָּא אִשְׁתְּכַח וּבְחַד מַתְקְלָא אִתְּקָלוּ.","וְהַחַיּוֹת רָצוֹא וָשׁוֹב, דְּכְתִּיב וַיַּרְא אֱלהִים אֶת הָאוֹר כִּי טוֹב. (ישעיהו ג׳:י׳) אִמְרוּ צַדִּיק כִּי טוֹב. הַאי, בְּמַתְקְלֵּיה סַלְּקָא. קַדְמָאָה בִּלְחוֹדוֹי. וְכֹלָּא לְחָד אִתְחֲזְרֵי. אֲחַתָא וּמוֹדַעְתָּא כְּלִילָן דָּא בְּדָא בְּיו\"ד הֵ\"א, כִּתְרֵין רְחִימִין דְּמִתְחַבְּקָן.","שִׁיתָא נָפְקִין מֵעַנְפָא דְּשָׁרְשָׁא דְּגוּפָא, לִישָׁן מְמַלֵּל רַבְרְבָן. לִישָׁן דָּא, סָתִים בֵּין יוֹ\"ד וְהֵ\"א, דְּכְתִּיב (ישעיהו מ״ד:ה׳) זֶה יֹאמַר לַה' אָנִי וְזֶה יִקְרָא בְּשֵׁם יַעֲקֹב וְזֶה יִכְתּוֹב יָדוֹ לַיְיָ' וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה (יכנה) מַמָּשׁ. זֶה יֹאמַר לַה' אָנִי: אֲחַתָא. וְכֹלָּא אִתְּמַר בְּיה\"ו. כֹּלָּא כְּלִילָן בְּלִישָׁן סָתִים לְאִימָא. דְּהָא אִתְפַּתְּחַת לֵיהּ דְּנָפִיק מִינָּהּ. אַבָּא יָתִיב בְּרֵישָׁא, אִימָא בְּאֶמְצָעִיתָא, וּמִתְכַּסְיָּיא מִכָּאן וּמִכָּאן וַוי לְמַאן דְּגַלֵּי עֲרָיַיתְהוֹן.","וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, שַׁלִּיט דְּכַר בְּנוּקְבָא. (ס\"י שלימו דכר ונוקבא) דְּכְתִּיב (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם, נָהִיר יוֹ\"ד בִּתְרֵין, וְנָהִיר וּמְעָבַּר לְנוּקְבָא. אִתְיְיחָד יוֹ\"ד בִּלְחוֹדוֹי, (ובתר כן) סָלִיק בְּדַרְגּוֹי לְעֵילָּא לְעֵילָּא. אִתְחַשְׁכָא נוּקְבָּא, וְאִתְנְהִירַת אִימָא וּמִתְפַּתְּחָא בְּתַרְעוֹי. אָתָא מַפְתְּחָא דְּכָלִיל בְּשִׁית, וּמְכַסְיָא פִּתְחָהָא, וְאָחִיד לְתַתָּא לְהַאי וּלְהַאי, ווי לְמַאן דְּגַלֵּי פִּתְחָהָא."],[[0,"מתלא לבר נש","וכו': משל לאדם, שדירתו היתה בין ההרים, ולא ידע יושבי עיר. זרע חטים, ואכל החטים כמות שהם. יום אחד בא לעיר. הגישו לו לחם טוב. אמר אותו האדם, זה למה. אמרו לו זה הוא לחם לאכול. אכל, והיה מוטעם מאד לחכו. אמר, וממה נעשה זה. אמרו לו מחטים. אחר כך הגישו לו עוגות בלולות בשמן. טעם מהם, אמר, ואלו ממה נעשו. אמרו לו, מחטים. אחר כך הגישו לו מאכל מלכים הנלשים בשמן ודבש. אמר ואלו ממה נעשו. אמרו לו מחטים. אמר, ודאי אני בעל כל אלו, כי אני אוכל העיקר של כל אלו, שהוא חטה. ומשום דעה זו, לא למד איך לעשות כל אלו מטעמים, ולא ידע ממעדני העולם ונאבדו ממנו. כך מי שאוחז כלל החכמה, ואינו יודע בכל העדונים המענגים היוצאים מכלל ההוא."],[1,"תאנא ספרא דצניעותא","וכו': למדנו. ספר הצניעות הוא ספר השוקל במאזנים. כלומר, ספר המדבר ממשקל האורות במאזנים, נקרא ספר הצניעות, מטעם שהחכמה שבמאזנים מאירה כך ממטה למעלה, שהוא דרך צניעות. שזה סוד, ואת צנועים חכמה. כי מטרם שהיה משקל לא היו, הימין והשמאל שה\"ס זכר ונקבה, משגיחים זה אל זה פנים בפנים, ומלכים הראשונים מתו וזיון שלהם לא נמצא, והארץ שה\"ס מלכות, נתבטלה."],[1,"","ביאור הדברים. נודע שהעולם לא היה יכול להתקיים עד ששיתף מדת הרחמים בדין, שפירושו, שהעלה המלכות שהיא מדת הדין, לבינה שהיא מדת הרחמים, ונשתתפו שתיהן יחד, ואז נתקיים העולם. וע\"י עליה זו של המלכות בבינה נבקעה כל מדרגה לב' חצאים, לכתר וחכמה, שנשארו במדרגה להיותם ממעל המלכות, ולבינה ותו\"מ, שהם נפגמו ע\"י המלכות שעלתה, ויצאו מן המדרגה. וכן נעשה בכל המדרגות. (כמ\"ש באורך לעיל בראשית א' דף ד' ד\"ה וביאור. עש\"ה) ובזה נתתקן הקטנות בכל המדרגות. ולעת גדלות נעשה זווג ע\"ב ס\"ג דא\"ק המוריד בחזרה את המלכות מבינה למקומה למטה, ונטהרו ג' הספירות בינה ותו\"מ מפגם הדין שבמלכות, והן חוזרות ועולות למדרגתן. ונעשו שם בחי' שמאל של המדרגה, וכו\"ח לימין המדרגה ואז נעשו ב' כפות המאזנים, שכתר וחכמה שהם ימין המדרגה נעשו כף זכות, ובינה ותו\"מ שנעשו לשמאל המדרגה נעשו כף חובה. והטעם שנקראו כף חובה, הוא משום שהמשכת אור השמאל ממעלה למטה הוא שורש כל החובות והנה נתבאר ב' כפות המאזנים, שהם קו ימין המכונה כף זכות, וקו שמאל המכונה כף חובה. וסוד המשקל במאזנים, נעשה ע\"י המסך דחירק שבקו אמצעי, הממעט את קו השמאל לבחינת ו\"ק דחכמה, דהיינו שלא יאיר אלא ממטה למעלה, (כמ\"ש באורך לעיל פרשת לך דף י\"ג ד\"ה ונתבאר ובד\"ה ולפיכך ע\"ש). וע\"כ נבחן המסך דחירק לבחינת לשון המאזנים, כי בכחו נשתוו ב' הכפות. כי מטרם שמיעט הארת החכמה שבשמאל לו\"ק, היה הארת השמאל גדול מהימין, וע\"כ היה עמו במחלוקת שרצה לבטלו, וע\"י המסך דחירק שמיעטו לו\"ק דחכמה, נעשו משקל שניהם שוה זה לזה, ואז נתיחדו ונכללו שניהם זה בזה."],[1,"","וז\"ש (להלן פקודי אות תרפ\"ג) \u0003דשקלי במתקלא דכורין ונוקבין דא עם דא ואלין אקרון מאזנים,\u0004 כי הדכר הוא בחינת קו ימין, והנוקבא הוא בחינת קו שמאל, \u0003ע\"ד כתיב במאזנים לעלות,\u0004 כי ע\"י מסך דחירק מאיר הקו שמאל רק בבחינת ו\"ק דחכמה, המאירה רק ממטה למעלה, \u0003כל אינון דשקילין דא עם דא ולא שקיל דא יתיר מן דא, סלקין ואתחברן כחדא,\u0004 דהיינו כנ\"ל, שהמסך דחירק משוה ב' הכפות שתהיינה במשקל שוה ולא יהיה השמאל גדול מימין, ואז מתחברים שניהם. וז\"ש בספר יצירה, \u0003שלש אמות אמ\"ש,\u0004 שהן ג' קוין מים אש רוח. \u0003יסודן כף זכות, וכף חובה, ולשון חק מכריע בינתים.\u0004 דהיינו כנ\"ל שמים שה\"ס כו\"ח דימין, ה\"ס כף זכות, ואש שה\"ס בינה ותו\"מ שבשמאל, ה\"ס כף חובה. והמסך דחירק שבקו האמצעי, ה\"ס לשון המאזנים. המשוה משקל שניהם שלא יהיה זה גדול מזה, ואז מתחברים זה בזה. ומשגיחים זה אל זה פנים בפנים. \u0003פנים,\u0004 פירושו השפעה, שמשפיעים זה אל זה, שהימין משפיע חסדים לשמאל, והשמאל משפיע חכמה אל הימין."],[1,"","וזה אמרו, \u0003דעד דלא הוה מתקלא,\u0004 שמטרם שהיה המסך דחירק דקו האמצעי, השוקל את הימין והשמאל במאזנים שלא יהיה זה גדול מזה, \u0003לא הוו משגיחין אפין באפין,\u0004 שלא היו משפיעים זה אל זה, כי השמאל היה גדול מן הימין, משום שהיה מתפשט ממעלה למטה, וע\"כ היו אחור באחור זה עם זה, דהיינו שהיו במחלוקת, וכל אחד החזיר אחוריו כלפי חברו. ומשום זה, \u0003ומלכין קדמאין מיתו,\u0004 שהם ז' ספירות תחתונות שבעולם הנקודים, שלעת גדלות שנעשה הזווג דע\"ב ס\"ג דא\"ק והוריד מהם בחזרה את המלכות מבינה, למקומה למטה. ועלו בינה ותו\"מ בחזרה להמדרגה, ונעשו קו שמאל, ויצא בהם אור החכמה, הנה אז, האירה החכמה ממעלה למטה, דהיינו מאצילות לבי\"ע ונשברו הכלים ומתו. (כמ\"ש לעיל בפתיחה לחכמת הקבלה דף כ\"א אות צ' ע\"ש, ובתלמוד ע\"ס שיעור ז' דף תכ\"ט ד\"ה הסיגים) והיה זה מטעם, \u0003וזיוניהון לא אשתכחו, וארעא אתבטלת,\u0004 כי הזיון שלהם, לא נמצא כי המלכות הנקראת ארעא שעלתה לבינה, שממנה הזיון שלהם, נתבטלה לגמרי ע\"י הארת הע\"ב ס\"ג, כי ירדה למקומה למטה, ונטהרו הכלים דבינה ותו\"מ לגמרי, ויכלו להשפיע החכמה ממעלה למטה, שלא היה מי שיזיין אותם שישפיעו רק ממטה למעלה, וע\"כ נשברו ז' המלכים ומתו. כמ\"ש שם."],[2,"עד דרישא דכסופא","וכו': עד שהראש, חמדת כל החמודות, שהוא ראש דנוקבא דעתיק, הנקרא רישא דלא אתיידע, התקין לבושי יקר, והנחיל אותם לכל פרצופי אצילות."],[2,"","פירוש. כי כדי שיוכל קו האמצעי לעורר את המסך דחירק שבו, שישוה את הארת ב' הקוין ימין ושמאל זה בזה, ויאירו זה בזה, היה צריך לעזר מלמעלה. כי מאחר שכבר ירדה המלכות מבינה, ונטהרו ג' הכלים בינה ותו\"מ שהם קו השמאל, מכל בחינת פגם, א\"כ איך יכול קו האמצעי למעט שוב את הקו שמאל בכח המסך דחירק שלו, שהיא בחינת החזרת המלכות לבינה, (כנ\"ל פרשת לך דף י\"ג ד\"ה ונתבאר ע\"ש). ולפיכך התקין רדל\"א את עצמו, שהמלכות לא תרד מבינה שלו לעולם, ואין בו בחינת הטהרה של קו שמאל כלל. וע\"כ הוא נקרא רישא דלא אתיידע, כי לא נודע בו הארת החכמה וכולו ימין, שהוא חסדים. ובזה נחלש גם כח השמאל של מטה וקו אמצעי יכול למעטו. והחסדים שברדל\"א נמשכים לקו אמצעי, היוצאים ע\"י מסך דחירק שבו, והם מכונים לבושי יקר, שע\"י קו האמצעי הממשיכם, מתלבש בהם הארת החכמה שבשמאל, ואז יכולה להאיר. (כמ\"ש לעיל בהקדמת ספר הזהר דף י\"ז, ד\"ה אתלבש בלבוש יקר ע\"ש). וז\"ש, \u0003עד דרישא דכסופא דכל כסופין לבושי דיקר אתקין,\u0004 שהתקין את עצמו, שלא תרד המלכות מבינה שלו לעולם, שעי\"ז ממשיך ממנו קו האמצעי את לבושי יקר בשביל החכמה שבקו שמאל. \u0003ואחסין\u0004 שהנחיל כח זה להפרצופין שמתחתיו, אשר המלכות לא תצא מן הבינה בבחינת ג\"ר של כל מדרגה, (כמ\"ש בהקדמת ספר הזהר דף מ\"ד ד\"ה וטעם) וכיון שקו האמצעי יש לו עזר זה מרישא דלא אתיידע, אז הוא יכול למעט קו השמאל במסך דחירק שלו, שלא יאיר אלא ממטה למעלה, דהיינו בבחינת ו\"ק דחכמה, שאז משקל ימין ושמאל שוים זה לזה ומתחברים שניהם, ומשגיחים זא\"ז פנים בפנים כנ\"ל."],[3,"האי מתקלא תלי","וכו': מאזנים אלו תלוים במקום שלא היו, דהיינו בראש דעתיק שנתתקן שהמלכות לא תרד מבינה שלו לעולם, שזהו שורש המתקלא וכן נתתקן בראש כל מדרגה, כנ\"ל בדבור הסמוך. ונבחן שתלוים שם. נשקלו בו אלו שזיוניהם לא נמצאו, דהיינו ז' מלכים שמתו מחמת שזיוניהון לא נמצאו נתתקנו בכח זה ששורש המתקלא נתלה בראש דכל מדרגה. ועצם המאזנים עומדים בגוף, דהיינו בקו אמצעי, שהוא ת\"ת, שבו מציאות הדין של המסך דחירק. והדין הזה אינו מתאחד ואינו נראה במאזנים, כי אלו היה נראה היה מתבטל אפילו הו\"ק דחכמה, אלא שפועל למעט השמאל אע\"פ שאינו נראה בו. במאזנים האלו, עולים האורות דשמאל ממטה למעלה. ובו עולים, שלא היו, והיו, ויהיו."],[3,"","פירוש המתקלא התלויה בראש כל מדרגה, נבחן שתלויה במקום \u0003שלא היו,\u0004 כי אין שם מקום המלכות והדין שלה, אלא שנתתקנה שם כדי לתקן התחתונים, דהיינו לתת כח אל קו האמצעי שבגוף, כנ\"ל. והמתקלא העומד בגוף כל המדרגה נבחן \u0003דהוו,\u0004 כי בת\"ת היא מציאת המסך דחירק בחזה שלו. והמתקלא העומד בסיום המדרגה, דהיינו בעטרת יסוד, שהוא קו האמצעי דנה\"י, נבחן, \u0003דיהויין,\u0004 כי הדין דמסך דחירק, אינו מתגלה בעטרת יסוד אלא אחר כריתת הערלה, וע\"כ אומר בו לשון עתיד. דהיינו שמתגלים בו ע\"י תקון."],[4,"סתרא גו סתרא","וכו': סתר בתוך סתר נתתקן ונזדמן בגלגולת אחת שהיא כתר של א\"א המלאה טל הבדולח, שהוא חכמה סתימאה דא\"א. ונמצא שחכמה דא\"א שהוא סתר אחד יצאה ונתקנה בתוך הכתר דא\"א, שהוא סתר ב'. ובדרך זה נזדמן הארת ראש הא' שנקרא רדל\"א, להאיר לתחתונים הקרום של האויר, שבין גלגלתא לחכמה סתימאה, נזדכך וסותם. אלו שערות הראש דא\"א הנקראות צמר נקי, תלויות במשקל. רצון הרצונות מתגלה, במצח דא\"א, ע\"י תפלות התחתונים. השגחה מעין פקוחה, שלא ינום, ושומר תמיד, נתקנה בעינים דא\"א והשגחה של הפרצופין שלמטה תלויה בהשגחה זו העליונה דא\"א. וב' נקבים של ממלא מקום השלטון, שה\"ס החוטם, המעורר רוח חיים לכל. \u0003פרדשקא\u0004 פירושו ממלא מקום השר, כמו \u0003פרדכש\u0004 (מגילה י\"ב ע\"ב)."],[4,"","פירוש. אחר שביאר, שהמתקלא תלוי בראש עתיק הנקרא רדל\"א, ששם הוא השורש, ועיקר עמידת המתקלא היא בגוף דעתיק, כמ\"ש \u0003מתקלא קאים בגופיה,\u0004 ממשיך לבאר כאן איך המתקלא עומד בגוף דעתיק, שהוא חג\"ת נהי\"מ שלו. אמנם גם חג\"ת נהי\"מ דעתיק נעלמים מבחינת עצמם, אבל הם מתגלים ע\"י התלבשותם בא\"א, ועושים בו ז' תקונים המכונים ז' תקוני גלגלתא גם צריך שתדע שאע\"פ שאמרנו שהמתקלא עומד בת\"ת דגוף, ושם מתלבשת החכמה בחסדים במשקל השוה והחכמה מאירה בשלמות הראויה, הנה זה רק לבחינת יציאת החכמה בלבדה, אבל עוד אין החכמה מתגלית להאיר שם, אלא רק בנה\"י של הגוף באופן שמקום יציאת החכמה הוא בחג\"ת, ושם עודה מכוסה, ומקום גילוי הארת החכמה היא בנה\"י, והיינו במלכות בעיקר, שהיא כוללת נה\"י. ומשום זה נחלקת כל מדרגה לג' חלקים, המרומזים בג' אותיות \u0003ם' ל' צ' דצלם.\u0004 שמקום תלית המתקלא נק' \u0003ם'\u0004 דצלם. שה\"ס הראש. ומקום יציאת החכמה נקרא \u0003ל'\u0004 דצלם, שה\"ס חג\"ת. ומקום גילוי הארת החכמה נקרא \u0003צ'\u0004 דצלם. שה\"ס נהי\"מ, והם נכללים זה בזה, ויש \u0003מל\"צ\u0004 ד \u0003מ'\u0004 ויש \u0003מל\"צ דל'\u0004 ויש \u0003מל\"צ\u0004 ד \u0003צ'.\u0004 באפן שיש מל\"צ בחג\"ת דעתיק, ומל\"צ בנה\"י שלו."],[4,"","וז\"ס ז' תקוני גלגלתא שנתקנו ע\"י חג\"ת נה\"י דעתיק. שמחג\"ת שלו מאירים פנימית הראש דא\"א, שהם ג' תקונים, גלגלתא, וחכמה סתימאה וקרומא דאוירא. ומנה\"י דעתיק מאירים ד' תקונים שבחיצוניות הראש דא\"א, שהם עמר נקי, ומצחא, פקיחו דעיינין, וב' נוקבי דפרדשקא, שה\"ס החוטם."],[4,"","וזה אמרו. \u0003בחד גלגלתא,\u0004 שהוא כתר דא\"א, ששם מאיר חסד דעתיק. הוא תקון הא' ובחינת \u0003ם\u0004 דצל\"ם שבחג\"ת דעתיק. \u0003מלייא טלא דבדולחא,\u0004 שהוא חכמה דא\"א, ששם מאיר גבורה דעתיק, הוא תקון הב', ובחינת \u0003צ'\u0004 דצלם דחג\"ת דעתיק. \u0003קרומא דאוירא אזדכך וסתים,\u0004 שהוא הקרום הסותם את חכמה דא\"א שלא תתגלה לחוץ ממנו, ושם מאיר ת\"ת דעתיק שהוא קו האמצעי, וזהו תקון ג', ובחינת \u0003ל'\u0004 דצלם שבחג\"ת דעתיק, שבו עומד המתקלא כנ\"ל. וז\"ש, \u0003אזדכך וסתים\u0004 כי להיותו בחינת קו אמצעי ו \u0003ל\u0004 דצלם, הרי הוא מיחד ב' הקוין זה בזה והחכמה מתתקנת בלבוש יקר דחסדים ויכולה להאיר בשלמות. וז\"ש \u0003אזדכך\u0004, שהי' יוצאת \u0003מאויר\u0004 שלה וחזרה להיות \u0003אור,\u0004 (כנ\"ל ב\"א מ\"ה ד\"ה כד) כי ע\"י המתקלא שבה נשלמה אור החכמה. ועכ\"ז, \u0003וסתים\u0004, שלא נפתחה סתימתה הסותמת את החכמה דא\"א, והוא מטעם הנ\"ל שאע\"פ שהמתקלא עומד בחג\"ת מכל מקום אין שם רק מקום יציאת החכמה, ולא מקום גילוי לחכמה, וגילוי החכמה אינה אלא רק בנה\"י. ע\"כ נשארה שם החכמה סתומה ע\"י הקרום, אע\"פ שנזדכך והשלים אור החכמה. ומסבה הזו היה הכרח, שנהי\"מ דעתיק ששם מקום גילוי החכמה יאיר עוד ד' תקונים בא\"א, ואז מתגלה החכמה בתקון האחרון המכונה חוטמא, שהוא המלכות. וכבר ידעת שגם בנהי\"מ יש מל\"צ. וע\"כ יש ב' בחינות נו\"ה, א) מכונים נצח והוד הנסתרים להיותם בחינת \u0003ם'\u0004 דצלם שבצ', והם ב' התקונים עמר נקי, שה\"ס ב' אודנין, ורעוא דרעוין, שהוא המצח, והמצח ה\"ס קו אמצעי בב' אודנין. ב) הם נצח והוד הנגלים, שהם בחינת \u0003ל\u0004 דצלם דצ', ששם מתחיל הגילוי, הנקרא, אשגחא פקיחו דלא נאים. ותקון הד' ה\"ס ב' נוקבי דפרדשקא, ששם מאירים יסוד ומלכות דעתיק, והם צ' דצלם שבצ', וע\"כ שם מקום גילוי החכמה. וזכור שהכרח התחלקות של \u0003מל\"צ,\u0004 הוא מכח \u0003המתקלא,\u0004 שמקום תליתה הוא ב \u0003ם'\u0004, ומקום עמידתה הוא ב \u0003ל',\u0004 ושם עודה מכוסה, ומקום גילויה הוא ב \u0003צ'\u0004."],[4,"","וזה אמרו. \u0003אינון עמר נקי תליין בשקולא,\u0004 שהם שערות דא\"א העולים וצומחים מב' אודנין דא\"א, שבהם מאירים נו\"ה דעתיק הנסתרים, להיותם \u0003ם\u0004 דצלם ד \u0003צ'\u0004, שבהם אין ה \u0003י'\u0004 יוצאת מאויר. ואויר הזה שב \u0003ם'\u0004 נקרא אוירא דכיא, וע\"כ מכונים השערות \u0003עמר נקי\u0004. ומשום שאין החכמה מתגלה שם, נמצאים הנצח והוד, שהם ימין ושמאל, שהם שקולים שוה בשוה. כי במקום שמתגלה החכמה, הוא מתארכת ומתגדלת על קו ימין עד שקו האמצעי צריך לשקול אותם בכח המסך דחירק שיהיו שוה בשוה. משא\"כ כאן בנו\"ה הנסתרים גם בבחינת השמאל מאירים רק חסדים, וע\"כ הם שקולים. וז\"ש \u0003תליין בשקולא\u0004, שבחינת הוד שבהם אינה ארוכה יותר מבחינת הנצח שבהם. והוא כמ\"ש (באדרת נשא קכ\"ח ע\"ב) \u0003דלא נפיק נימא מנימא ושערא משערא\u0004. וזה הוא תקון הד'."],[4,"","וז\"ש, \u0003רעוא דרעוין אתגליא בצלותא דתתאי,\u0004 שהוא מצח דא\"א, ששם מאיר יסוד דעתיק, שהוא קו האמצעי של נו\"ה הנסתרים שלו. שבסבת הארת יסוד דעתיק שם נפנה המצח משערות, שהם כחות דין, ונתגלה בו רצון הרצונות. והוא תקון ה'. וז\"ש, \u0003אשגחא פקיחא דלא נאים ונטיר תדירא\u0004 שהוא עינים דא\"א, שבהם מאירים נצח והוד הנגלים דעתיק, והוא \u0003ל\u0004 דצלם ד \u0003צ',\u0004 ששם מקום עמידת המתקלא ויציאת החכמה, אבל עוד לא מקום גילוי, וז\"ש, \u0003אשגחותא דלתתא באשגחותא דנהירו דעלאה,\u0004 השגחה, רומז על אור החכמה, הנקראת ראיה, ואומר, שהחכמה המתגלה למטה בחוטם דא\"א, מקובלת מכאן, מעינים דא\"א, שבהם מקום יציאת החכמה, להיותה בחי' \u0003ל\u0004 דצלם ד \u0003צ'.\u0004 כמבואר. והואתקון הששי דא\"א. וזה אמרו, \u0003תרין נוקבין דפרדשקא דאתער רוחא לכלא,\u0004 שהוא חוטם דא\"א, שבו מאירים יסוד ומלכות דעתיק, שהם בחינת \u0003צ'\u0004 דצלם שב \u0003צ'\u0004. וע\"כ יש בחוטם ב' נקבים, כנגד הארת יסוד ומלכות דעתיק, ושם הוא מקום גילוי החכמה. וע\"כ נקרא החוטם בשם \u0003פרדשקא,\u0004 שפירושו ממלא מקום של השליט, משום שעיקר השולט על יציאת החכמה, הוא בעינים דא\"א, שה\"ס \u0003ל\u0004 דצלם, אלא משום ששם אין מקום לגילוי, ששם בחינת ג\"ר, ואין החכמה מתגלית אלא בכלים דו\"ק, וע\"כ נתגלתה בחוטם, שהוא ו\"ק, ובחינת \u0003צ'\u0004 דצלם ד \u0003צ'.\u0004 נמצא, שהחוטם הוא פרדשקא, וממלא מקום של העינים. וזה הוא תקון השביעי."],[4,"","והנך מוצא שמשום שעתיק רצה לגלות החכמה ע\"י א\"א הוכרחו ז' ספירות תחתונות חג\"ת נהי\"מ, לעשות ולתקן ז' תקוני גלגלתא הללו בא\"א. שהם הארות ג' בחינות מל\"צ שבחג\"ת דעתיק, בפנימיות ראש דא\"א, שהם גלגלתא וחכמה סתימאה ואוירא. וג' בחינות מל\"צ שבנה\"י דעתיק, והמלכות שלו, העושים ד' תקונים בחצוניות הראש, שהם עמר נקי, ורעוא דרעוין, ואשגחא פקיחא, וב' נוקבי דפרדשקא. שאין החכמה יכולה להתגלות אלא בתקון האחרון הזה. וז\"ש \u0003דאתער רוחא לכלא,\u0004 שממנו יוצא רוח החכמה לכל פרצופין התחתונים. (ועי' בתלמוד עשר ספירות שיעור י\"ג מאות נ' עד אות צ\"ב, ששם נתבארו ז' תיקוני גלגלתא האלו באריכות.)"],[5,"בראשית ברא","וגו': בראשית ברא אלקים את השמים ואת הארץ הם שש תיבות, כנגד חג\"ת נה\"י, ובראשית עליהן, שהיא בינה. כולם הן למטה בבינה ובז\"א, והן תלויות ונמשכות מז' תיקוני גלגלתא, ומתפשטים עד היקר מכל יקר, שהוא י\"ג תיקוני דיקנא דא\"א, שמהם נמשך הכתוב הב' היתה תהו ובהו וגו' שבו י\"ג תיבות, כמ\"ש לפנינו. והמלה \u0003והארץ\u0004 השניה, דהיינו \u0003והארץ\u0004 שבה מתחיל הכתוב הב', אינה בחשבון י\"ג תיבות אלו כמו שלמדנו, משום שיצאה מן אותה הארץ שנתקלקלה, בחטא של עצה\"ד, שנתערב בה המלכות דמדת הדין הקשה, שכתוב מן האדמה אשר אררה ה'. וע\"כ אינה בחשבון י\"ג, והם מתחילים מן \u0003היתה,\u0004 דהיינו היתה, תהו, ובהו, וחשך, על, פני, תהום, ורוח, אלקים, מרחפת, על, פני, המים, שהם י\"ג תיבות, ואלו י\"ג תיבות תלויות מן י\"ג תקונים שביקר מכל יקר, שהוא הדיקנא דא\"א. ומתבארים לפנינו להלן (מאות י\"ד עד אות י\"ח.)"],[6,"שיתא אלפי שנין","וכו': ששת אלפים שנה שהעולם עומד תלויות ונמשכות בשש תבות הראשונות שהם, \u0003ברא אלקים את השמים ואת הארץ\u0004 השביעי שהוא בינה, הוא עליהם, שמתגבר בלבדו, דהיינו המלה \u0003בראשית\u0004 המוקדמת להם. ונחרב הכל בי\"ב שעות, שכתוב, היתה תהו ובהו וגו'. השלשה עשר, יקים אותם הי\"ב שעות ברחמים. ומתחדשים כבתחילה, וקמים שוב כל אלו הששה. משום שכתב \u0003ברא,\u0004 ואח\"כ כתוב, \u0003היתה,\u0004 שמשמע שעתה כבר איננה, והוא כי \u0003היתה\u0004 ודאי בששה אלפי שני, ולבסוף, באלף הז' היא תהו ובהו וחשך וגו', כי נחרבה. וז\"ש ונשגב ה' לבדו ביום ההוא, דהיינו באלף הז'."],[6,"","פירוש. נודע שלתקון העולם, שתף מדת הדין במדת הרחמים, דהיינו שהעלה המלכות לבינה, שעי\"ז השיגו זו\"ן מוחין וכלים מן הבינה ונתקיים העולם, ולולא זה לא היה העולם מתקיים (כנ\"ל ב\"א דף ז' ד\"ה וכבר) וז\"ש \u0003שיתא אלפי שנין תליין בשיתא קדמאי,\u0004 שה\"ס חג\"ת נה\"י של ז\"א שנמתקו בכלים דבינה, שע\"כ המה חסרי המלכות, ועטרת יסוד שה\"ס מפתחא, דהיינו מלכות מבחינת בינה, היא עומדת במקום מלכות האמיתית דמדת הדין. ז\"ש \u0003שביעאה עלייהו דאתתקף בלחודוי,\u0004 שבחינת המלכות, שהיא ספירה השביעית, הוא מבחינת בינה שהוא ממעל חג\"ת נה\"י, כי הבינה לבדה מתחזקת במלכות לקיים העולם בשתא אלפי שני ע\"י כלים ואורות שלה. ועליה רומזת המלה, \u0003בראשית.\u0004 ונודע, ששורש תקון זה דעלית המלכות בבינה, הקטנות והגדלות וכל מיני מוחין, יוצאים מי\"ב תקונים שבדיקנא דא\"א, עד ונקה, שהיא בחינת המלכות, שבחינתה עצמה גנוזה, אלא שמקבלת מן י\"ב תקונים של הדיקנא, כמ\"ש להלאה, וע\"כ נאמר עליה ונקה לא ינקה, כי כל אלו האורות של י\"ב התקונים הם מכלים ואורות דבינה ומבחינה זו נקראת \u0003ונקה,\u0004 ולא מכלים של עצמה, שהם עוד בסוד \u0003לא ינקה.\u0004 ובאלף הז' יחרבו כל אלו המוחין הנמשכים מן י\"ב תקוני דיקנא. שז\"ס חורבן העולם שיהיה באלף הז'. וז\"ש \u0003ואתחריב כלא בתריסר שעתי,\u0004 שכל מה שבתריסר שעתי, שהם י\"ב תקונים דדיקנא הכוללים כל האורות והכלים דבי\"ע יחרבו (כמ\"ש בהקדמת ספר הזהר דף ע\"ט ד\"ה בן איש חי. ודף פ\"א ד\"ה והענין ע\"ש כל ההמשך) \u0003תליסר יקים לון ברחמי,\u0004 שמזל י\"ג, שנאמר עליה בשתא אלפי שני \u0003לא ינקה,\u0004 כנ\"ל הנה אז תקבל תקונה המוחלט (כנ\"ל בהקסה\"ז דף פ\"א ד\"ה והענין) כי הב\"ן ישוב להיות ס\"ג ע\"ש בההמשך, ואז \u0003וקמו כל אינון שיתא,\u0004 שכל המוחין דשתא אלפי שני יחזרו ויקומו. כמ\"ש שם."],[7,"גלופי דגליפין כחיזו","וכו': חקיקות החקיקות הוא כמראה נחש ארוך ומתפשט לכאן ולכאן, הזנב הוא בראש, הראש מתאחד בכתפים, עובר וזועם שומר וגונז. אחד לאלף ימים קטנים מתגלה ההשגחה בתקונו. הסנפיר שהעולם עומד עליו הוא בחלקו. ראשו נשבר במים של ים הגדול, שכתוב, שברת ראשי תנינים על המים. שנים היו, והוחזרו אחד, שכתוב, תנינם, חסר ה \u0003י'\u0004 דלשון רבים, ואע\"פ שכתוב \u0003ראשי\u0004 הוא לשון יחיד, כמו שאתה אומר, ודמות על ראשי החיה רקיע. הרי שנאמר ראשי עם י' אע\"פ שהיא ראש חיה יחידה, אף כאן בתנין, אע\"פ שנאמר ראשי, הוא ראש של תנין אחד. \u0003קולטרא,\u0004 פירושו השגחה, מלשון דעביד קומיס \u0003קליטר\u0004 (וי\"ר כ\"ח) שפירושו ראש המשגיחים. \u0003בקטרוי,\u0004 פירושו עשיה ותקון, מלשון, קטורי בירי (מועד קטן יוד ע\"ב)."],[7,"","פירוש. המדובר הוא כאן, בסוד קו שמאל מבחינתו עצמו, שממנו נמשכים כל הדינים. ומדמהו לצורת תנין בים, ולצורת נחש ארוך להיותו נמשך מקו שמאל דבינה עד המלכות הנקראת ים. וע\"כ הוא ארוך. ועוד, כיון שהחכמה מתגלית בקו שמאל, והחכמה נקראת ארוך, ע\"כ קורא אותו, חויא אריך."],[7,"","וזה אמרו. \u0003גלופי דגליפין,\u0004 דהיינו קו שמאל שממנו כל החקיקות שהם הדינים. \u0003כחיזו דחויא אריך ומתפשט לכאן ולכאן,\u0004 שהוא מתפשט לבינה ולמלכות, כנ\"ל, וע\"כ הוא ארוך מבינה עד מלכות. \u0003זנבא ברישא.\u0004 הזנב שלו הוא בראש. כי בקו שמאל נהפכו המדרגות, כי הסדר הוא ג\"ר בראש ו\"ק לאחר כך בגוף, וגזרא דדינא בסיום, המכונה זנב, וכדי למחות הרשעים שהיו ממשיכים מג\"ר דחכמה ממעלה למטה נעשה תקון בקו שמאל של הפיכת המדרגות שגזרא דדינא עלה למעלה באפן שהסיום והזנב נעשה לבחינת ראש, ואחר כך הו\"ק ואח\"כ לבסוף הג\"ר, (כמ\"ש לעיל פרשת וירא דף פ\"ג ד\"ה פנימיות ע\"ש) הרי שזנבא ברישא. וז\"ש, \u0003רישא אחיד אכתפין,\u0004 שהראש שלו הוא בחינת כתפין, כלומר שנסתלקו ממנו הג\"ר שהוא ראש, ולא נשאר ממנו רק בחינת ו\"ק דחכמה שהוא נבחן לכתפין. \u0003אעבר וזעים.\u0004 בשעה שעובר להשפיע חכמה הוא זועם בדינים, משום שאינו נגלה אלא על גזרא דדינא (כנ\"ל וירא ס\"ה ד\"ה מה) בסו\"ה בערב היא באה. \u0003נטיר וגניז.\u0004 שעל ידי הזעם שלו שומר, שהרשעים לא יקרבו להמשיך ממנו, וגונז הג\"ר דחכמה."],[7,"","ונודע שהחכמה מכונה אלף ימים, ובחינת ו\"ק דחכמה מכונה אלף ימים קטנים. והמלכות ה\"ס אחד לאלף ימים אלו, ואין החכמה מתגלית בשום מדרגה אחרת זולתה. וז\"ש, \u0003חד לאלף יומין זעירין, אתגליא קולטרא בקטרוי,\u0004 שבמלכות, שה\"ס אחד לאלף ימים קטנים, מתגלה ההשגחה, שה\"ס חכמה, על ידי תקוניו ומשמיענו שחוץ ממנה אין החכמה מתגלה כלל, (כנ\"ל בראשית א' דף רע\"ו ד\"ה ועוד כמה). ומלכות זו בשעה שהיא מגלית חכמה נקראת סנפיר, שהעולם עומד עליו. שאין קיום לעולם זולת על ידי חכמה זו שהיא מגלית, וז\"ש, \u0003סנפירא בעדבוי\u0004 שהסנפיר שהעולם עומד עליו הוא בחלקו של מלכות זו שה\"ס חד לאלף וכו' כמ\"ש לעיל (ב\"א י\"ד ד\"ה פירוש. ע\"ש)."],[7,"","ונודע שבביאת קו האמצעי להכריע וליחד ב' הקוין ימין ושמאל זה בזה, הוא עושה ב' פעולות שמתחילה פועל במסך דמלכות דמדת הדין, ואח\"כ פועל במלכות הממותקת במדת הרחמים, כנ\"ל (פרשת לך דף י\"ג ד\"ה ונתבאר ע\"ש, ואין להכפיל הדברים). שבמסך דמדת הדין שמצמצום א' הרג את הנוקבא, ובמסך הממותק דמדת הרחמים מצמצום ב' מחץ ראשו של הזכר, דהיינו שמיעטו מג\"ר דג\"ר והעמידו על ו\"ק דג\"ר, כמ\"ש לעיל (פרשת בא דף ט\"ו ד\"ה ביאור, ע\"ש)."],[7,"","וזה אמרו. \u0003תרין הוו, חד אתחזרו,\u0004 שמבחינת קו שמאל הנ\"ל נמשכו ב' תנינים, שהם לויתן ובת זוגו, אבל בסבת המסך דחירק שהמשיך קו האמצעי סוד המלכות דמדת הדין נהרגה הנקבה, ונשאר תנין אחד, הזכר. \u0003אתבר רישיה במיין דימא רבא,\u0004 דהיינו שנתמעט לבחינת ו\"ק דג\"ר, ע\"י המסך דחירק שבקו אמצעי דצמצום ב' שהוא מלכות הממותקת שזה נבחן כמו שנשבר ראשו, דהיינו הג\"ר שלו, ונעשה בו נקב, (כנ\"ל פרשת בא דף י\"ג ד\"ה פירוש) שזסו\"ה, שברת ראשי תנינים על המים. שהכונה על תנין הזכר הנ\"ל. ואין לשאול שכתוב תנינים לשון רבים. שהרי \u0003תנינם חסר כתיב.\u0004 שיורה על תנין אחד. וכן \u0003ראשי\u0004 הוא כמו \u0003ראשי החיה,\u0004 שהוא ג\"כ לשון יחיד."],[8,"ויאמר אלקים יהי אור ויהי אור:","היינו שכתוב, כי הוא אמר ויהי, שכתוב אמירה בויהי, להראות, אשר \u0003ויהי,\u0004 הוא בפני עצמו, והמלה יהי אור הוא בפני עצמו, כי יהי אור הוא אבא וקו ימין, ויהי אור הוא אמא וקו שמאל. ואח\"כ חזרו ימין ושמאל להיות אחד, על ידי קו האמצעי, שה\"ס ז\"א שהכריע ביניהם בכח המסך דחירק, כנ\"ל. ונתיחדו יהי עם ויהי ונעשה מהם צירוף \u0003יהו\"י,\u0004 כי האותיות השוות אינם נכפלות, \u0003יה\"ו,\u0004 ה\"ס אבא ואמא וז\"א המכריע ומיחדם. ו \u0003י'\u0004 האחרונה שביהו\"י, היא השכינה למטה, כמו ה' היא השכינה ובמשקל אחד נשקלו, כי \u0003י'\u0004 ה\"ס ה \u0003י'\u0004 שנכנסה לאור י\"ה ונעשה לאויר, דהיינו המלכות שעלתה לבינה (כמ\"ש לעיל ב\"א מ\"ג ד\"ה יהי) וע\"כ היא השכינה כמו \u0003ה',\u0004 ויהו\"י הוא אחד כמו י\"ה ו\"ה. שפירושו, אבא ואמא וז\"א והמלכות."],[9,"והחיות רצוא ושוב:","דכתיב וירא אלקים את האור כי טוב. פירוש, כשהחיות, שה\"ס הארות החכמה שבשמאל, הן \u0003ברצוא,\u0004 להמשך ממעלה למטה הם פוגעים בדינים של קו אמצעי אז הם \u0003ושוב,\u0004 שמחזירים הארתם ממטה למעלה, כדי להתיחד בחסדים. וז\"ש וירא אלקים את האור כי טוב, שע\"י קו האמצעי, נעשה האור טוב כי הוא שב ומתיחד עם הימין, וז\"ש \u0003אמרו צדיק כי טוב,\u0004 כי הצדיק הוא קו אמצעי שבנו\"ה שהם ימין ושמאל ועושה אותה בבחינת טוב כנ\"ל. פסוק זה וירא אלקים כי טוב, עולה במאזנים, שהוא קו האמצעי השוקל ומשוה ב' האורות ימין ושמאל שיהיו שוים ויתיחדו זה בזה, (כנ\"ל אות ג' בסולם) אבל פסוק הראשון יהי אור ויהי אור היו הימין והשמאל בפני עצמם, שעוד לא נתיחדו במאזנים. וכולם חזרו לאחד אח\"כ, ע\"י קו האמצעי, שהאחות שה\"ס חכמה, ומודע שה\"ס בינה, הנרמזים ביהי אור ויהי אור כנ\"ל, נכללו על ידו זה בזה, בסוד י\"ה, שהוא חכמה ובינה, שהם כתרים האהובים המתחבקים. ומה שמכנה חו\"ב אחתא ומודעתא, הוא בסו\"ה, אמור לחכמה \u0003אחותי\u0004 את \u0003ומודע\u0004 לבינה תקרא. שהחכמה נקראת אחות משום שאסורה עליו כאחותו, כמ\"ש חז\"ל, וכל החכמה המתגלה באצילות, הוא ע\"י הדעת שבבינה שחזרה להיות חכמה, וע\"כ נקראת הבינה מודע, ע\"ש הדעת."],[10,"שיתא נפקין מענפא","וכו': שש ספירות חג\"ת נה\"י יוצאות מן הענף של שורש הגוף, שהוא לשון מדברת גדולות, כי הלשון היא ענף יוצא מפנימיות הגוף ממטה למעלה אל הפה דראש, והוא ספירת הדעת דהיינו קו האמצעי המכריע ומיחד חכמה ובינה, כנ\"ל (משפטים אות תקכ\"ט) ואומר שם שהוא פשיטותא דתפארת וכו' ע\"ש בסלס). לשון הזה סתום בין \u0003יו\"ד וה\"א,\u0004 שהם חכמה ובינה. שכתוב, זה יאמר להוי\"ה אני, וזה יקרא בשם יעקב, וזה יכתוב ידו להוי\"ה ובשם ישראל יכנה. יכנה ממש. \u0003זה יאמר לה' אני,\u0004 הוא האחות, דהיינו חכמה בסוד שאסורה כאחותו, שאין בה השגה. \u0003וזה יקרא בשם יעקב,\u0004 היינו מודע, שהיא בינה, שבה מתחיל הארת החכמה, וע\"כ נאמר \u0003בשם\u0004 יעקב, כי בשם, פירושו השגה. \u0003וזה יכתוב לה',\u0004 הוא דעת, \u0003ובשם ישראל יכנה,\u0004 היא התפשטות הדעת לז\"א, שאז נקרא ז\"א ישראל. דהיינו יכנה ממש כנ\"ל. והכל נאמר ביה\"ו. דהיינו בחכמה בינה דעת כמבואר. הכל כל ג' אלו, חכמה בינה דעת, כלול בלשון הסתום באמא, שהדעת המכריע בין ב' קוין חכמה בינה שבאמא, כולל בעצמו חב\"ד, כי נפתחה ממנו, ויוצא ממנה. אבא ישב בראש אמא באמצע, ומתכסה מכאן ומכאן, אוי למי שמגלה ערותם."],[10,"","פירוש. כיון שב' קוין דאמא היו במחלוקת והיתה משום זה בסוד \u0003ם\u0004 סתומה ולא נפתחה מסתימתה אלא על ידי הלשון שה\"ס קו האמצעי, שעל ידו האירו בה ג' קוין חב\"ד, ונודע שכל האורות שהתחתון גורם לעליון זוכה בהם התחתון. כמ\"ש לעיל, דכיון \u0003דתלת דאמא מחד נפקי\u0004, שיוצאים מדעת שה\"ס ז\"א שעלה בסוד קו האמצעי לאמא לבחינת קו אמצעי ע\"כ \u0003חד בתלת קיימא\u0004, זוכה הדעת בג' מוחין חב\"ד אלו, ויוצאים ומתפשטים לז\"א למטה. (כנ\"ל בראשית א' דף רפ\"ז ד\"ה תלת) וז\"ש, \u0003דהא אתפתחת ליה,\u0004 שאמא נפתחה מן הדעת שהוא הלשון וע\"כ \u0003כלא כלילן בלישן סתים לאמא,\u0004 שהוא דעת. \u0003דנפיק מינה,\u0004 שהוא יוצא עם חב\"ד אלו למקומו בז\"א עצמו. ומה שמכנהו \u0003לישן סתים,\u0004 הוא משום שהוא סותם הג\"ר דקו שמאל דבינה, שממעט ממנו הג\"ר דג\"ר כנודע. ומה שמכנה את הדעת \u0003ענפא דשרשא דגופא,\u0004 הוא משום שהדעת הוא באמת ז\"א שנקרא גוף, שעלה למ\"ן לאמא, וז\"א מכונה גוף, וע\"כ נבחן לענף יוצא בראש מן שורש הגוף, שהוא ז\"א."],[10,"","וזה אמרו, \u0003אבא יתיב ברישא,\u0004 שהוא נקרא או\"א עלאין, והוא \u0003י'\u0004 דהויה. \u0003אמא באמצעיתא,\u0004 שהיא נקראת ישסו\"ת, והיא \u0003ה'\u0004 דהויה, וז\"א שה\"ס \u0003ו'\u0004 דהויה הוא למטה, \u0003ומתכסיא מכאן ומכאן,\u0004 שהחכמה שבאמא מתכסה מצד מעלה מאו\"א עלאין, שהם חסדים מכוסים לגמרי מהארת חכמה, ומצד מטה מז\"א, שגם הוא סוד חסדים מכוסים. וע\"כ \u0003ווי למאן דגלי ערייתהון,\u0004 דהיינו מי שרוצה לגלות ולהמשיך החכמה שבקו שמאל דאמא ממעלה למטה, שגורם בזה להפריד או\"א עלאין מישסו\"ת דהיינו פירוד בין י\"ה, ופירוד בין י\"ה אל הו', וענשו מרובה."],[11,"ויאמר אלקים יהי מארת ברקיע השמים:","רומז שהזכר שהוא ז\"א, ישלוט על על הנקבה, שהיא המלכות, שע\"כ נקרא הזכר, מאור הגדול, והנוקבא מאור הקטן, שכתוב, וצדיק יסוד עולם, שהצדיק שהוא יסוד דז\"א הוא היסוד של המלכות שנקראת עולם שמשמע, שלולא הצדיק לא היה קיום לעולם, וע\"כ שולט עליה. ומפרש למה הוא כך. ואומר, הי' שהוא חכמה ואו\"א עלאין, האירה בשתי ההין, והאירה ועיברה את ה \u0003ה'\u0004 ראשונה עם הנוקבא. ואח\"כ נתיחדה ה \u0003י'\u0004 בפני עצמה, שנבדלה מן ה \u0003ה'\u0004 ועלתה במדרגותיה למעלה למעלה, ונתחשכה הנוקבא. ואמא האירה ונתפתחה בשעריה. ובא המפתח הכולל שש ספירות, שהוא ז\"א, ומכסה הפתח דאמא. ונתאחד למטה, עם זו ועם זו, דהיינו עם הנוקבא ועם אמא. אוי למי שמגלה הפתח."],[11,"","פירוש. נודע שמכח עלית המלכות לבינה בכל מדרגה, נבקעו כל המדרגות לב' חצאים, שכו\"ח נשארו במדרגה ובינה ותו\"מ נפלו מכל מדרגה למדרגה שמתחתיה. (כנ\"ל ב\"א דף ד' ד\"ה ביאור) ואח\"כ לעת גדלות, יורדת המלכות מבינה בכל מדרגה, וג' ספירות בינה ותו\"מ, שנפלו לתחתונה חוזרים ועולים למדרגתם (כנ\"ל ב\"א דף ר\"צ ד\"ה בגין) ולוקחים עמהם גם את התחתונה שהיו מלובשים בהם בשעת הנפילה, שעי\"ז עולה כל תחתון לעליון, ומקבל האור דעליון, שזה הוא סוד העיבור (כנ\"ל ב\"א דף מ\"ב ד\"ה פירוש)."],[11,"","וכבר ידעת, שה \u0003י'\u0004 ה\"ס חכמה, וכן היא או\"א עלאין. וה \u0003ה'\u0004 ה\"ס בינה, וכן ה\"ס ישסו\"ת. ונמצא שבעת ירידת הפרסאות, דהיינו המלכות, מכל מדרגה, הבינה ותו\"מ דכל מדרגה חוזרות למקומם ומעלים עמהם גם המדרגה התחתונה, אל העליונה, נמצא שבינה, ותו\"מ של ה \u0003י'\u0004 חזרו אליה, והעלו עמהם גם מדרגת \u0003ה'\u0004 אל מדרגת ה \u0003י',\u0004 ונעשו אחד. וכן על דרך זה חזרו בינה ותו\"מ של ה \u0003ה',\u0004 והעלו עמהם גם מדרגת \u0003ו\"ה\u0004, שהם זו\"ן אל ה \u0003ה',\u0004 ונעשו אחד עם ה \u0003ה',\u0004 אשר ה \u0003י'\u0004 כבר מחוברת עמה. ונמצא בזה, שה \u0003י'\u0004 מאירה לב', \u0003ההין,\u0004 ביחד, כי ה' תחתונה שהיא מלכות כבר נתדבקה באמא, שהיא \u0003ה'\u0004 ראשונה, והארה זו נבחנת לעבור. וז\"ש, \u0003נהיר י' בתרין ונהיר ומעבר לנוקבא.\u0004 שה \u0003י'\u0004 מאירה ומעברה את הנוקבא. אמנם גם ה \u0003ו',\u0004 שהיא ז\"א דבוקה באמא, כנ\"ל, ונבחן, אשר ה \u0003ו'\u0004 דבוקה בקו ימין דאמא, וה \u0003ה'\u0004 דבוקה בקו שמאל דאמא."],[11,"","ונודע, שעם עלית בינה ותו\"מ דכל מדרגה, שנעשו השמאל של המדרגה, נתעוררה מחלוקת בין ימין לשמאל, ונעשה פירוד ביניהם. (כנ\"ל ב\"א דף נ\"ז ד\"ה וזה) ואז נעשה פרוד בין י\"ה, שה \u0003י'\u0004 שכולה ימין, נבדלה לעצמה ועלתה למעלה, וז\"ש \u0003אתייחד י' בלחודוי, סליק בדרגוי לעילא לעילא.\u0004 והנוקבא הדבוקה בקו שמאל דאמא, נחשכה לגמרי, כי אין החכמה שבשמאל יכולה להאיר בלי התלבשות בחסדים שבימין, (כנ\"ל ב\"א דף רמ\"ז ד\"ה ימא דקאפו) וז\"ש \u0003אתחשכא נוקבא,\u0004 שלהיותה בחינת שמאל בלי ימין. היא נקבעה להיות תמיד בסוד החושך. כי ע\"כ ה\"ס לילה. ואח\"כ הכריע ז\"א אשר שם, באמא, את ב' קוין ימין ושמאל שבאמא, ונעשה בה סוד הדעת, ואז חזרה והאירה. וז\"ש \u0003ואתנהירת אמא ומתפתחא בתרעוי אתא מפתחא דכליל בשית,\u0004 שהוא ז\"א, \u0003ומכסיא פתחהא,\u0004 דהיינו אחר הכרעת ז\"א, שהוא \u0003מפתחא דכליל שית,\u0004 את ב' הקוין שלה שאז חזרה ה \u0003י'\u0004 להאיר ב \u0003ה',\u0004 וה' ספירות כח\"ב תו\"מ שלה שכל אחת כוללת עשר, נעשו לנ' שערי בינה. ונודע ששער האחרון מבחינת הכלים דאמא, הוא גנוז במלכות דאמא, וה\"ס מנעולא, ושער הנ' הבלתי מושג, (כנ\"ל בהקדמת ספר הזהר דף מ\"ו ד\"ה חד.) וע\"כ הוא צריך כיסוי וגניזא. (כנ\"ל בהקסה\"ז דף קכ\"ג אות קכ\"ב ד\"ה ב'). וע\"כ נה\"י דאמא מתלבשת בז\"א, וז\"א מכסה אותם. \u0003ואחיד לתתא.\u0004 במלכות \u0003להאי ולהאי,\u0004 בבינה ומלכות, שנתאחד בבינה להיותו מכריע בין ב' קוין שלה, והוא מלביש נה\"י שלה, ונתאחד במלכות שמזדווג עמה ומאיר אליה מג' קוין שלו. \u0003ווי למאן דגלי פתחהא,\u0004 כי כשהמנעולא שהיא המלכות דמדת הדין שבשער האחרון דאמא, מתגלה, הוא אובד כל הארותיו (כנ\"ל ויצא י\"ג ד\"ה סתרא) ועונשו גדול מאד. והנה נתבאר בזה, שהמלכות נחשכה, וצריכה לז\"א שיאיר אליה, ומטעם זה \u0003שליט דכר בנוקבא,\u0004 וזהו שרצה להשמיענו."]],[]],[["\u0003פִרְקָא תִּנְיָינָא\u0004 דִּיקְנָא (אד\"ר מן דף קל\"א עד קל\"ה) מְהֵימָנוּתָא. (דיקנא) לָא אַדְכַּר בְּגִין דְּהִיא יַקִירוּתָא דְּכֹלָּא מֵאֻדְנִין נַפְקַת, בְּסָחֲרָנָהָא דְּבֹּסִיטָא, סָלִיק וְנָחִית חוּטָא חִוְורָא. בִּתְלֵיסָר מִתְפְּרַשׁ.","בְּיָקִירָא דִּבְיָקִירוּתָא הַהִיא, כְּתִיב (ירמיהו ב׳:ו׳) לא עָבַר בָּהּ אִישׁ וְלָא יָשַׁב אָדָם שָׁם. אָדָם (ויקרא מ\"ח ע\"א) לְבַר הוּא. אָדָם לָא כָּלִיל הָכָא. כָּל שֶׁכֵּן אִישׁ. בִּתְלֵיסָר נְבִיעִין מַבּוּעִין מִתְפָּרְשָׁן, אַרְבַּע בִּלְחוֹדוֹי אִסְתָּמָרוּ. תִּשְׁעָה אַשְׁקְיוּן לְגוּפָא. (נ\"א לגנתא).","(תיקונא קדמאה) מִקָּמֵי פְּתִחָא דְּאֻדְנִין, שָׁאֲרִי יָקִירוּ לְאִתְתָּקָן, (תניינא) נָחִית בִּשְׁפִּירִי בְּרֵישָׁא דְּשִׂפְוָון. מֵהַאי רֵישָׁא לְהַאי רִישָׁא קָאִים. (תליתאה) אָרְחָא דְּנָפִיק תְּחוֹת תְּרֵין נוּקְבִין דְּפַרְדַּשְׂקָא, לְאַעְבְרָא חוֹבָה, דְּכְתִּיב (משלי י״ט:י״א) וְתִפְאַרְתּוֹ עֲבוֹר עַל פָּשַׁע. (רביעאה) תְּחוֹת שִׂפְוָון אַסְחַר שַׂעֲרָא לְרִישָׁא אַחֲרָא. (חמישאה) אָרְחָא אַחֲרָא נָפִיק תְּחוֹתוֹי. (שתיתאה) חָפֵי תַּקְרוּבְתָּא דְּבוּסְמָא, לְרֵישָׁא דִּלְעֵילָּא. (שביעאה) תְּרֵין תַּפּוּחִין אִתְחָזוּן לְאַנְהָרָא בּוּצִינִין. (תמינאה) מַזָּלָא דְּכֹלָּא, תַּלְיָיא עַד לִבָּא, בֵּיהּ תַּלְיָין עִלָּאִין וְתַתָּאִין.","(תשיעאה) אִינּוּן דְּתַלְיָין לָא נָפְקִין דָּא מִן דָּא. (עשיראה) חַפְיָין זְעִירִין עַל גְּרוֹנָא (חד סר) דְּיָקִירוּ. רַבְרְבִין, מִתְשַׁעֲרִין בְשִׁיעוּרָא שְׁלִים. (תריסר) (וכד) שִׂפְוָון אִתְפְּנוּן מִכָּל סִטְרִין, זַכָּאָה לְמַאן דְּנָשִׁיק מֵאִינּוּן נְשִׁיקִין. (תליסר) בְּהַהִיא מַזָּלָא דְּכֹלָּא נַגְדִּין תְּלֵיסַר מְשִׁיחִין דְּאֲפַרְסְמוֹנָא דַּכְיָא. כֹּלָּא בְּהַאי מַזָּלָא שְׁכִיחַ, וְסָתִים.","בְּזִמְנָא דְּמָטָא תִּשְׁרֵי, יַרְחָא שְׁבִיעָאָה, מִשְׁתַּכְחֵי (ירחי) אִלֵּין תְּרֵיסַר (ס\"א תליסר) בְּעַלְמָא עִלָּאָה וּמִתְפַּתְּחֵי תְּרֵיסַר (ס\"א תליסר) תַּרְעֵי דְּרַחֲמֵי, בְּהַהוּא זִמְנָא (ישעיה נה) דִּרְשׁוּ יְיָ' בְּהִמָּצְאוֹ כְּתִּיב.","(בראשית א׳:י״א) וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְּרִי וְגוֹ', הַיְינוּ דְּכְתִּיב (ויקרא ט״ז:ל״א) וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם בְּתִשְׁעָה לַחֹדֶשׁ בָּעֶרֶב. (בהאי זמנא) (דברים ג׳:כ״ד) אֲדֹנָי ידו\"ד אַתָּה הַחִלּוֹתָ לְהַרְאוֹת אֶת עַבְדְךָ אֶת גָּדְלְךָ. יהו\"ה שְׁלִים בְּסִטְרוֹי. וְהָכָא בִּרְחִישׁוּתָא דָּא דְּאַרְעָא, לָא שְׁלִים.","יְהִ\"י לָא כְּתִיב, קָרֵינָן יוֹ\"ד עִלָּאָה יוֹ\"ד תַּתָּאָה, וַיִּיצֶר י' עִלָּאָה י' תַּתָּאָה, (יהי) י' עִלָּאָה, י' תַּתָּאָה. ה' בְגַוַויְיהוּ. כְּלָלָא דִּשְׁלִימוּ. שְׁלִים, וְלָא לְכָל סְטָר. אִתְּעֲקָר מֵהַאי אֲתָר שְׁמָא דָּא, וְאַשְׁתִּיל בְּאַחֲרָא, כְּתִיב וַיִּטַּע יְיָ' אֱלהִים.","ה ' בֵּין יוֹ\"ד לְיוֹ\"ד דִּיְהִ\"י, נָשְׁבָא דְּפַרְדַּשְׂקָא דְעַתִּיקָא, לִזְעִירָא דְּאַנְפִּין בְּלָא רוּחָא לָא אִתְקְיָּים. בְּהֵ\"א, אִשְׁתָּכְלַל הֵ\"א עִלָּאָה הֵ\"א תַּתָּאָה, דְּכְתִּיב (ירמיהו א׳:ו׳) אֲהָהּ אֲדֹנָי אֱלהִים.","בְּקִיטְפוֹי דְּקַטְפִין, (צרירא) בְּרוּחָא דְּמַתְקְלִין, יה\"ו. י' עִלָּאָה דְּאִתְעַטָּר בְּקִטְרָא (ס\"א בעטרא) דְעַתִּיקָא, הוּא קְרוּמָא עִלָּאָה דְּאִזְדְּכַךְ וְסָתִים. הֵ\"א עִלָּאָה, דְּאִתְעַטָּר בְּרוּחָא דְּנוּקְבִין דְּפַרְדַּשְׂקָא, דְּנָפִיק לְאַחֲיָיא. ו' עִלָּאָה, בּוֹצִינָא דְּקַרְדִּינוּתָא דְּאִתְעַטָּר בְּסִטְרוֹי, (ס\"א בעטרוי) מִתְפַּשְּׁטָן אַתְוָון לְבָתַר, וְאִתְכְּלָלוּ בִּזְעֵירָא דְּאַפִּין. כְּמָה דְּשַׁרְיָא בְּגוּלְגֹלְתָא, אִשְׁתַּכְּחוּ מִתְפַּשְּׁטָן בְּכָל גּוּפָא, לְשַׁכְלְלָא כֹּלָּא. בַּעֲמָר נְקֵא. כַּד תָּלֵי תַּלְיָין אִלֵּין אַתְוָון. כַּד אִתְגְּלֵי לִזְעֵירָא מִתְיַישְּׁבָן בֵּיהּ אִלֵּין אַתְוָון, וְאִתְקְרֵי בְּהוֹן.","יוֹ\"ד דְּעַתִּיקָא סָתִים בְּעִטְרוֹי, בְּגִין שְׂמָאלָא אִשְׁתְּכַח ה\"ה אִתְפְּתַח בְּאַחֲרָא וְאִינְקִיב בִּתְרֵין נוּקְבִין, וְאִשְׁתְּכַח בְּתִקוּנִין. וָ\"ו אִתְפְּתַח בְּאַחֲרָא, דִּכְתִּיב, (שיר השירים ז׳:י׳) הוֹלֵךְ לְדוֹדִי לְמֵישָׁרִים. בְּבוּצִינָא דְּקַרְדִּינוּתָא לִמְכַסְיָא פִּתְחָא.","ו' לְעֵילָּא ו' לְתַתָּא, ה' לְעֵילָּא ה' לְתַתָּא. י' לְעֵילָּא וּבָהּ לָא אִשְׁתָּתַּף אַחֲרָא, וְלָא סָלִיק בַּהֲדָהּ, בַּר רְמִיזָא דְּרָמִיז כַּד אִתְגַּלְּיָין תְּרֵין (באורייתא) וּמִתְחַבְּרָן בְּחַד דַּרְגָּא, חַד רִגְּשָׁא בְּגִין לְאִתְפָּרְשָׁא, ו\"ד כְּלִילָן בְּיוֹ\"ד וַוי כַּד אִסְתַּלָּק הַאי, וְאִתְגַּלְיָין.","אִינּוּן בּוּסְמִין דְּטִיפְסָא שְׁרִיקִין, דְּעַבְרֵי (ס\"א עבד) לָא מִתְעַכְּבָא בְּדוּכְתָּא, וְהַחַיּוֹת רָצוֹא וָשׁוֹב. בְּרַח לְךָ אֶל מְקוֹמֶךָ. אִם תַּגְבִּיהַ כַּנֶּשֶׁר וְאִם בֵּין כּוֹכָבִים שִׂים קִנֶּךָ מִשָּׁם אוֹרִידְךָ."],[[0,"פרקא תניינא דיקנא מהימנותא","וכו': פרק השני. בו מתבאר זקן האמונה. כלומר שהמלכות הנקראת אמונה מקבלת ממנו כל תקוניה עד גמר התקון. הזקן אינו נזכר בתורה ובנביאים וכתובים, שכתוב עיני ה' אזני ה' וכן לחייו כערוגת הבושם, אבל זקן אינו נזכר. משום שהוא היקר מכל. והוא יוצא מן האזנים, שמשם הזקן מתחיל, ומקפת מסביב צורת הפנים, שעולה ויורד חוט לבן מסביב פניו. כלומר שהזקן בכללו, נראה כמו חוט לבן עם שערות לבנות, שמסבבות הפנים שמהן, עולות, שמאירות ממטה למעלה, ומהן, יורדות, שמאירות ממעלה למטה. והוא מתבאר בשלשה עשר תקונים. כמ\"ש לפנינו. \u0003בוסיטא דאנפוי,\u0004 פירושו צורת הפנים, כמ\"ש באדרת נשא קכ\"ח."],[1,"ביקירא דביקירותא ההיא","וכו': ביקר מכל יקר ההוא, דהיינו הזקן, כתוב, לא עבר בה איש ולא ישב אדם שם. ז\"א מכונה אדם ויסוד ז\"א מכונה איש. אדם לחוץ מא\"א הוא, שז\"א הנקרא אדם מלביש את א\"א מבחוץ מטבורו ולמטה, ומכ\"ש איש, שהוא יסוד דז\"א, שהוא אפילו מחוץ לז\"א. כי נה\"י הם לבר מגופא כל שכן שהוא מחוץ לא\"א, ולפיכך אין להם התכללות בדיקנא זו דא\"א. בשלשה עשר עינות מבועים מתבאר הזקן, ורק ארבעה תקונים מהם נשתמרו, שלא ישפיעו למטה לז\"א, ותשעה תקונים מהם משקים את הגוף, שהוא ז\"א."],[2,"מקמי פתחא דאודנין","וכו': תקון ראשון הוא, שמלפני הפתח של האזנים התחיל היקר, שהוא הזקן, להתתקן, דהיינו מכנגד נקבי האזנים, ויורד ביופי למטה, עד תחילת השפתים. ב) השערות שבראש השפתים, מראש הזה שבשפה הימנית, לראש הזה, שבשפה השמאלית. ג) נמצא דרך הפנוי משערות, היוצא תחת ב' נקבי החוטם להעביר הפשעים, שכתוב ותפארתו עבור על פשע. ד) השערות שמתחת השפתים שהשערות חוזרים להיות ראש אחר. ה) דרך אחר פנוי משערות יוצא תחתיו, דהיינו באמצע השערות שבשפה התחתונה. ו) מנחת בשמים, דהיינו שערות, חופה, על הפנים, מלמטה עד ראש שפה עלאה. ז) ב' תפוחים, דהיינו לחיים הפנוים משערות, נראים, להאיר הנרות. ח) מזל הכל, היינו השערות הנמשכות התלויות עד הלב. בו תלוים העליונים והתחתונים. והיינו השטח העליון של הדיקנא, שנקרא מזל עליון."],[2,"","ביאור הדברים. תחלה צריכים לדעת סוד השערות מה הם. והענין הוא, כי נודע שאעפ\"י שפרצופי אצילות הם בבחינת ו\"ק דחכמה, עכ\"ז אי אפשר שתצא ו\"ק דחכמה בלי הג\"ר. אלא תחילה יוצא בהם גם הג\"ר דחכמה, ואח\"כ מסתלקות הג\"ר מהם ונשארים בו\"ק דחכמה. (כנ\"ל בראשית א' דף פ' ד\"ה אמנם) והנה האו\"ח שהיה מלביש לג\"ר אלו לא נסתלק עמהם אלא נשאר בראש, ומחמת עוביותו, מכה שנשאר ריק מן האור שלו, לא היה יכול להשאר בפנימיות הכלים, ויצא לחוץ בבחינת מותרי מוחא, ונחלק כמו הסדר דצמצום ב', אשר כתר וחכמה שבהם עלו ונאחזו בגלגלתא. שהיא בחינת \u0003ם'\u0004 דצלם, וע\"כ מכנה אותם הספרא דצניעותא לעיל (באות ו') \u0003עמר נקי,\u0004 שהמסך נמצא ממטה להם בסיום הגלגלתא, ואין כח במסך להעלות דינים למעלה ממקום מציאותו. וג' בחינות בינה ותו\"מ שלו מתתקנים מחכמה סתימאה דא\"א, והם נאחזים אחר סיום הגלגלתא, דהיינו בלחי התחתון, שהוא בחינת זו\"ן דראש. אמנם לפי שב' רישין דא\"א, גלגלתא וחכמה סתימאה כלולים זה מזה, יש בכל אחד מהם ב' הבחינות נמצא שגם חכמה סתימאה כלולה מגלגלתא, וע\"כ מאיר בדיקנא גם הגלגלתא שבחכמה סתימאה. וח' תקונים הראשונים, הם מהארות חכמה סתימאה וה' האחרונים הם מגלגלתא."],[2,"","ומתוך שחכמה סתימאה דא\"א נעלמה ונסתמה, נמצאת הדיקנא דא\"א, שמקבל ממנה שהוא המשפיע כל מדרגות המוחין לפרצופי אצילות. והם מקבלים ממנו אותם הסדרים שנסדרו בי\"ג תקונים של הדיקנא. ונבאר תחילה ח' תקוני דיקנא הנמשכים מחכמה סתימאה. ותדע, שהם סדר ג' בחינות נרנח\"י של נפש רוח נשמה, והכללות שלהם."],[2,"","מקום התחלת הדיקנא הוא בתחילת לחי התחתון, אחר שנסתיימו שערות רישא בפאתי הראש בסיום עצם הגלגלתא, שמקום זה מכוון נגד נקבי האזן. וזהו תקון הא' של הדיקנא. וז\"ש \u0003מקמי פתחא דאודנין שארי יקירו לאתתקן,\u0004 ששם שורש הדיקנא שנתתקנה להיות בלחי התחתון כנ\"ל. ותקון הב' הוא לעלות לבינה בבחינת עבור. וז\"ש \u0003נחית בשפירו ברישא דשפוון מהאי רישא להאי רישא,\u0004 כי השערות נמשכות מלחי התחתון, שמקמי פתחא דאודנין, שהם זו\"ן, ועולות על השפה העליונה, שהוא מקום לחי העליון, ובחינת גלגלתא, שהוא בינה, ונבחן זה לבחינת עיבור שערות דיקנא שהם זו\"ן, בבחינת שפה עלאה, שהיא בינה. והם מקבלים שם בזה, בחינת ו\"ק דעיבור, הנקרא נ\"ר דנפש. ואחר זה, נמשך רוח החכמה מב' נקבי החוטם, ששם מקום גילוי החכמה (כנ\"ל אות ו). להשערות דשפה העליונה, ועושה שם דרך באמצע שערות השפה, שהוא פנוי משערות, כי החכמה מסלקת כל הדינים. וז\"ש, \u0003ארחא דנפיק תחות תרין נוקבין דפרדשקא,\u0004 שהרוח של החוטם, שהוא חכמה, מטהר את הדרך מן השערות. \u0003לאעברא חובה,\u0004 כי סליחת עונות נמשכות מהארת החכמה. (כנ\"ל פרשת נח דף מ\"ב ד\"ה ות\"ח) והארת חכמה זו, היא בחי' ג\"ר דעיבור, דהיינו נשמה חיה יחידה דנפש. והוא תקון ג'."],[2,"","אחר זה מגיע זמן הלידה שבשערות דבחינת זו\"ן שנתעברו בבינה, שהיא שערות שפה העליונה, יוצאות ויורדות למקומם, שהוא לחי התחתון, דהיינו תחת שפה התחתונה. וז\"ש, \u0003תחות שפוון אסחר שערא לרישא אחרא,\u0004 שהשערות שהיו בשפה עלאה נמשכו ובאו למקומם בלחי התחתון ונעשה שם שערות שפה אחרת, שהוא בחינת שערות זו\"ן עצמם, ובהתפשטות הזו שמתחת השפה תתאה, קנו בחינת ו\"ק דרוח, דהיינו נפש רוח דרוח. והוא תקון הד'. ואחר זה נמשך רוח החכמה מב' נקבי החוטם, דרך ארחא דשפה עלאה ועבר על השערות שמתחת שפה תתאה, ועשה שם דרך פנוי משערות כמו בשפה עלאה, וז\"ש \u0003ארחא אחרא נפיק תחותוי,\u0004 והארת חכמה שבדרך הזה, ה\"ס ג\"ר דרוח, דהיינו יחידה חיה נשמה של הרוח. והוא תקון החמשי."],[2,"","אחר זה נעשה שוב עבור לבחינת נשמה, ועלו שוב השערות שבלחי התחתון אל השפה העליונה, שהיא מקום סיום. גלגלתא ובחינת בינה. וקבלה שם תחילה ו\"ק דנשמה, דהיינו נפש רוח דנשמה. וז\"ש \u0003חפי תקרובתא דבוסמא\u0004, שכן נקראת הדיקנא, על שם הכתוב, ולחייו כערוגות הבשם, \u0003לרישא דלעילא\u0004, דהיינו לשפה עלאה, וקבלה שם בחינת ו\"ק דנשמה, והוא תקון הששי. אחר זה נתגלה רוח החכמה בבחינת פנים, בסוד ב' תפוחי הפנים שזו היא בחינת ג\"ר דנשמה, דהיינו יחידה חיה נשמה של הנשמה. וז\"ש, \u0003תרין תפוחין אתחזן לאנהרא בוצינין\u0004, כדי להאיר הספירות, המכונות בוצינין בבחי' ג\"ר. שז\"ס חכמת אדם תאיר פניו. וזהו תקון השביעי. ואחר זה, נמשכים הו\"ק דנשמה והארות הג\"ר דנשמה, למטה למקומם בלחי התחתון, וז\"ש \u0003מזלא דכלא תליא עד לבא\u0004, שהוא הכולל של כל התקונים הקודמים. \u0003ביה תלין עלאין ותתאין\u0004 כי כל המוחין דאצילות נמשכים ממנו. והוא תקון השמיני. ונתבארו ח' תקוני דיקנא המאירים מח\"ס."],[3,"אינון דתליין לא","וכו': תקון התשיעי הוא, אלו השערות הקצרות התלויות בין השערות דשטח העליון דדיקנא אינן יוצאות זו מזו. שכולן שוות. תקון העשירי הוא שערות קצרות המכסות על הגרון סמוך אל הדיקנא היקר. תקון אחד עשר הוא, שערות גדולות משוערים בשיעור שלם. התלויות על הגרון. תקון שנים עשר הוא, שהשפתים, נפנו משערות מכל צד. אשרי למי שנושק מאלו הנשיקות. תקון שלשה עשר הוא, שבמזל ההוא של הכל, נמשכים י\"ג נהרות שמן של אפרסמון הטהור. הכל נמצא במזל הזה, והוא סתום. והיינו שטח התחתון של הדיקנא, שנקרא מזל תחתון."],[3,"","פירוש. אחר שביאר ח' תקוני דיקנא הנמשכים מהארות חכמה סתימתה, מבאר כאן ה' תקוני דיקנא הנמשכים מגלגלתא. וההפרש ביניהם רב הוא, כי החכמה סתימאה אע\"פ שנסתמה, נסתמה רק מבחינת חכמה שבה, אבל בינה ותו\"מ שבה מאירים לח' תקוני דיקנא. וע\"כ יש בהם ג\"ר, כי בינה זו חזרה להיות חכמה כנודע. מה שאין כן הגלגלתא, שהיא נתקנה בבחינת \u0003ם'\u0004 דצלם, ואין בה חכמה, אלא חסדים מכוסים, שהם בחינת אוירא דכיא, דהיינו קומת רוח, והיא חסירה ג\"ר, ונמצא שגם ה' תקוני דיקנא הנמשכים ממנה הם ג\"כ חסרי ג\"ר. ומסבה זו, נתלו הח' תקוני דיקנא על הלחי התחתון, שאע\"פ שנפסק מראש, הוא רק מבחינת העצמות, שהוא חכמה, אבל מבחינת גידין ובשר ועור, הרומזים לבינה ותו\"מ הוא מחובר עם הראש. מה שאין כן ה' תקונים תחתונים הנמשכים מגלגלתא, הם תלוים בגרון, שאפילו מבחינת גידין בשר ועצמות הוא נבדל לבחינת גוף, דהיינו לנפש רוח, וחסר ג\"ר."],[3,"","וכשנצמחו שערות מכח הגלגלתא הנה תקון הראשון שבהם, היא העיבור בבחינת בינה, וז\"ש, \u0003אינון דתליין לא נפקין דא מן דא,\u0004 שאלו שערות הקצרות התלויות בין שערות הארוכות דשטח העליון דדיקנא, אינם יוצאות זה מזה, כלומר שאינם יוצאות ונמשכות משערות הארוכות דדיקנא, כי הן נמשכות מחכמה סתימאה ואלו שערות הקצרות נמשכות מגלגלתא, כנ\"ל. והמה שם רק לתקון העיבור בבחינת בינה. ומקבלים שם בחינת נפש. וזה הוא תקון התשיעי."],[3,"","ואחר זה יורדות משם למקומם, דהיינו לגרון, ויוצאים תחילה בבחינת נפש דרוח, וז\"ש \u0003חפיין זעירין על גרונא דיקירו.\u0004 ששערות קטנות צומחות ומכסות על הגרון. וזה הוא תקון העשירי. ואחר זה יוצאים בבחינת רוח דרוח. וז\"ש, \u0003רברבין מתשערין בשיעורא שלים,\u0004 ואלו שערות הגדולות תלויות ג\"כ בגרון. וזהו תקון האחד עשרה. ואח\"ז נמשך מגלגלתא בחינת אוירא דכיא, שאע\"פ שהם חסדים הם חשובים יותר מחכמה, להיותם למעלה מחכמה, וע\"כ הם מפנים השערות מן השפתים במקום שנושקים. וז\"ש \u0003שפוון אתפנון מכל סטרין,\u0004 וזהו תקון הי\"ב."],[3,"","ואחר זה יוצא הכללות של כל י\"ב תקוני דיקנא, כלומר, שהיא בחינת מלכות המקבלת מכולם. וז\"ש, \u0003בההיא מזלא דכלא נגדין י\"ג משיחין דאפרסמונא דכיא,\u0004 והיינו שטח התחתון של הדיקנא הדבוק בגרון. שהתחתונים ממנו מקבלים כל המוחין ממזל הזה, וז\"ש \u0003כלא בהאי מזלא שכיח וסתים.\u0004 שמזל התחתון כולל ב' נקודות שהם מפתחא ומנעולא, ומצד המפתחא הוא שכיח, ומצד המנעולא הוא סתים. שזה סוד שנקרא, ונקה לא ינקה. (ובתלמוד עשר ספירות שיעור י\"ג מאות ר\"ד עד אות ר\"כ נתבאר י\"ג ת\"ד דא\"א באורך ובלוח התשובות שם באות קנ\"ב ובאות קנ\"ז עש\"ה)."],[4,"בזמנא דמטא תשרי","וכו': בזמן שהגיע תשרי, שהוא חדש הז', נמצאים אלו י\"ג תיקונים בעולם העליון, שהוא בינה, ונפתחים שם י\"ג שערי הרחמים. בעת ההוא, כתוב, דרשו את ה' בהמצאו."],[5,"ויאמר אלקים תדשא","וגו': היינו שכתוב, ועניתם את נפשותיכם בתשעה לחדש בערב. כתוב, אדני הוי\"ה אתה החלות להראות את עבדך את גדלך. כאן השם הוי\"ה שלם בצדדיו, דהיינו שמאיר בצד ימין ובצד שמאל יחד, שע\"כ כתוב אדנ\"י הויה, וכן את גדלך וכאן בהתעוררות הזה של הארץ, אינו שלם. שמאיר רק צד שמאל, בלי צד הימין."],[5,"","פירוש. כשהנוקבא היא בבחינת מחזה ולמעלה דז\"א, שמלבשת קו שמאל דאמא לבד, אז היא בבחינת \u0003ד'\u0004 דאחד, והיא יבשה, שאינה עושה פירות. אלא אחר כך שירדה לבחינת מחזה ולמטה דז\"א ומקבלת מז\"א שהוא קו אמצעי, אז \u0003מה דהות יבשה,\u0004 כשהיתה בבחינת מחזה ולמעלה דז\"א, \u0003אתעבידת ארץ למעבד פירין ואיבין.\u0004 (כנ\"ל בהקדמת ספר הזהר אות ר\"ו, וע\"ש בהסולם) כי קו האמצעי מתקן אותה להאיר מב' הצדדים. אבל כל עוד שקבלה מאמא, מקו שמאל לבד, היתה יבשה ובחינת חורבן, כי החכמה שבשמאל אינה מאירה בלי חסדים שבימין, ונמשך ממנה אז, דינים ועונשים. ובעת ההיא שהיתה הנוקבא מחזה ולמעלה בבחינת הדינים דשמאל, אמר הקב\"ה תדשא הארץ דשא, וגו' דהיינו שתרד למחזה ולמטה, ותהיה ארץ מוציאה פירות."],[5,"","וזה אמרו, \u0003ויאמר אלקים תדשא הארץ\u0004 וגו' \u0003היינו שכתוב ועניתם את נפשותיכם\u0004 וגו'. כלומר, שתדשא הארץ דשא הוא אותו הענין כמו ועניתם את נפשותיכם וגו'. כי ביום הכפורים עולה הנוקבא לקו שמאל דאמא ומקבלת שם חכמה בלי חסדים, הגורם עינוי נפש להנוקבא, כי חכמה בלי חסדים אינה מאירה וגורמת דינים. אמנם אח\"כ כשיורדת למטה מחזה ומתתקנת ממנו, אז מתלבשת חכמה זו, שקבלה מקודם לכן מאמא, בחסדים דז\"א, ומאירה בכל השלמות. ואם לא היתה מקבלת החכמה מאמא מקו שמאל לבד הגורמת לעינוי נפש, אז לא היה לה ג\"ר לעולם כי בהיותה למטה מחזה, אינה ראויה לקבל חכמה. וזסו\"ה, ועניתם את נפשותיכם וגו'. כי ע\"י קבלתינו את עינוי נפש הזה עלינו, שיש לנוקבא בסבת עליתה לקו שמאל דאמא, יש לנו חלק בג\"ר שהנוקבא מקבלת אח\"כ מז\"א אחר ירידתה למטה מחזה, שהחכמה שקבלה מקודם לכן מאמא, מתלבשת עתה בחסדים דז\"א, ונעשים לג\"ר. וזסו\"ה כי כל הנפש אשר לא תענה בעצם היום הזה, ונכרתה מעמיה, כי אין לה חלק במוחין דג\"ר שהנוקבא ממשיכה אח\"כ. הרי שענין ההתעוררות של תדשא הארץ דשא וגו', וענין ועניתם את נפשותיכם וגו' הם ענין אחד, ששניהם נוהגים בזמן שהנוקבא מקבלת מקו שמאל דאמא."],[5,"","וזה אמרו, \u0003אדני הויה אתה החלות\u0004 וגו' \u0003הויה שלים בסטרוי,\u0004 דהיינו ששלם בב' הצדדים ימין ושמאל, שזהו שלמות. \u0003והכא ברחישותא דא דארעא לא שלים,\u0004 כי ההתעוררות להוציא פירות היתה בעת שקבלה רק מצד שמאל דאמא, שהיתה יבשה וחרבה, והיתה \u0003לא שלים. רחישותא,\u0004 פירושו התעוררות, מלשון רחש לבי דבר טוב. (תהלים מ\"ה)."],[6,"יהי לא כתיב","וכו': יהי דשא ועשב, לא כתוב כאן, שאנו קורים בו \u0003י'\u0004 עליונה ו \u0003י'\u0004 תחתונה, בסו\"ה וייצר, עם ב' יודין ש \u0003י'\u0004 עליונה הוא חכמה עלאה, ו \u0003י'\u0004 תחתונה הוא חכמה תתאה, דהיינו הנוקבא, (כנ\"ל בראשית א' דף ר\"ז ד\"ה פירוש). שה\"ס ב' יודין דראש וסוף של הצירוף \u0003יאהדונה\"י\u0004 ע\"ש \u0003יה\"י\u0004 יש בו \u0003י'\u0004 עליונה, ו \u0003י'\u0004 תחתונה, \u0003ה'\u0004 ביניהם, שה \u0003ה'\u0004 ה\"ס בינה, אשר \u0003י'\u0004 תחתונה מקבלת ממנה חכמה. וזהו כלל של שלימות, כי אז מקבלת חכמה, שהיא שלמה, ולא לכל צד, אלא רק משמאל לבד. וע\"כ נעקר שם הזה, דהיינו הנוקבא המכונה שם, ונשתל באחר. דהיינו שנעקרה מלמעלה מחזה דז\"א מן המקום שמקבלת רק משמאל דאמא, אל למטה מחה דז\"א, לקבל ממנו חסדים. שכתוב, ויטע ה' אלקים גן וגו', דהיינו שנטעו במקום למטה מחזה דז\"א."],[7,"ה' בין יוד ליוד","וכו': דרך אחר ה \u0003ה'\u0004 הכתובה בין \u0003י' לי' דיה\"י,\u0004 רומזת על נשיבת רוח חכמה מחוטם דא\"א, לז\"א. ואע\"פ שז\"א הוא תמיד בחסדים מכוסים מחכמה, עכ\"ז, בלא רוח חכמה אינו מתקיים. כי כל עוד שאין בו חכמה הוא ו\"ק בלי ראש. ב \u0003ה'\u0004 זו הרומזת לחוטם דא\"א, נשתכללו ה' עליונה דשם הויה וה' תחתונה דשם הויה, דהיינו שה' עליונה שהיא בינה מקבלת חכמה בקו שמאל שלה, מחוטם דא\"א ומשפעת לה' תחתונה, שהיא הנוקבא. ואז ב' ההין הן ביחד, שכתוב, \u0003אהה\u0004 אדני אלקים שרומז, שבכל מקום שב' ההין הם יחדיו, דהיינו שה' תחתונה מקבלת חכמה מקו שמאל ד \u0003ה'\u0004 עליונה, נאמר עליה \u0003אהה,\u0004 שהוא רומז לעת צרה, כי הנוקבא היא אז, בצרה שהיא חרבה ויבשה כנ\"ל."],[8,"בקטפוי דקטפין ברוחא","וכו': באשכול האשכולות, ברוח של המאזנים, שהוא ז\"א, שבו המתקלא כנ\"ל, ונקרא אשכול, כמ\"ש, אשכול הכופר דודי לי, יש \u0003יה\"ו,\u0004 ומפרש. \u0003י'\u0004 העליונה, שהיא או\"א שנקרא אבא, נתעטרה בקשר עתיק, שהוא קרום העליון דאזדכך וסתים, דהיינו תקון ג' דז' תקוני גלגלתא דא\"א. \u0003ה'\u0004 עליונה, שהיא ישסו\"ת, שנקראו אמא שנתעטרה ברוח של ב' נוקבי דפרדשקא שיצא להחיות. דהיינו להשפיע חכמה הנקרא חיים שהוא תקון ז' דז' תקוני גלגלתא דא\"א. \u0003ו'\u0004 עליונה, שהוא קו אמצעי ודעת, שבו ניצוץ הקשה, דהיינו המסך דחירק (כנ\"ל לך י\"ג ד\"ה נתבאר) שנתעטר בצדדיו, דהיינו שמכריע בין ב' צדדים, ימין ושמאל שבאמא, ומקבל משם ג\"ר המכונים עטרה. מתפשטים האותיות יה\"ו אחר כך ונכללים בז\"א. בסוד תלת נפקי מחד, חד בתלת קיימא, (כנ\"ל ב\"א אות שס\"ג) כמו שיה\"ו שורים בגלגלתא דא\"א, כנ\"ל, נמצאים מתפשטים בכל גוף דא\"א, דהיינו ז\"ת חג\"ת נהי\"מ שלו לשכלל הכל, כי עליהם מלביש או\"א וישסו\"ת וזו\"ן. כאשר אלו האותיות יה\"ו, תלויות, דהיינו שהמ סתומות, הם בעמר נקי, שהוא תקון ה' דז' תקוני גלגלתא. וכשהן מתגלות לז\"א, מתישבים בו אלו האותיות יה\"ו ונקרא בהן. \u0003קטפוי,\u0004 פירושו אשכולות, מלשון (חזינהו להני קטופי כתובות קי\"ב ע\"א)."],[9,"יוד דעתיקא סתים","וכו': היוד דהוי\"ה שבעתיק, סתום בעטרותיו, שהמלכות אינה יוצאת מבינה שלו וסותמת אותו, משום שהשמאל נמצא, שאין לו תקון אלא במתקלא, והמתקלא מחויב לתלות בראש עתיק, (כנ\"ל אות ה') שהיא המלכות שסותמת אותו. וכן הוא בכל הראשים, וה \u0003י'\u0004 היא תמיד בחינת ראש. \u0003ה\"ה\u0004 נתפתחה ב \u0003ה'\u0004 האחרת, דהיינו ב \u0003ה'\u0004 של ז\"א, שבו מקום הגילוי כנ\"ל בדבור הסמוך. וע\"כ אות המילוי של \u0003ה',\u0004 הוא ג\"כ \u0003ה,\u0004 דהיינו \u0003ה\"ה\u0004. והיא מנוקבת בב' נקבות, כי גם \u0003ה'\u0004 אחרונה, שהיא המלכות נכללה בה, ונמצאת בתקונים, שלעת גדלות יורדת ממנה המלכות, והיא מתגלית בחכמה, ולא בה עצמה אלא בז\"א. \u0003ו\"ו\u0004 נתפתחה ב \u0003ו'\u0004 אחרת שבז\"א שכתוב, הולך לדודי למישרים, שהתקונים שלמעלה הולכים לדודי, שהוא ז\"א. שבו ניצוץ הקשה, שהוא מסך דחירק כנ\"ל, כדי לכסות הפתח של אמא, (כנ\"ל אות י\"ג) וע\"כ אות המילוי של ה \u0003ו'\u0004 הוא ב \u0003ו'\u0004 אחרת. כזה, \u0003וו.\u0004"],[10,"ו' לעילא ו' לתתא","וכו': נמצא שיש \u0003ו'\u0004 למעלה בראש, ויש \u0003ו'\u0004 למטה בז\"א, יש \u0003ה'\u0004 למעלה בראש, ויש \u0003ה'\u0004 למטה בז\"א. שמשום זה הן נכפלות במילוי, כנ\"ל בסמוך, כי למעלה הן נסתרות ולמטה מתגלות \u0003י'\u0004 למעלה, ובה לא נשתתף \u0003י'\u0004 אחרת, כמו באותיות \u0003ה\"ה ו\"ו\u0004, ואינה עולה עמה במבטא, חוץ מרמז שנרמז, כי המילוי ו\"ד שביוד, היא בגימטריא \u0003י',\u0004 שהיא רמז שיש בכללה גם \u0003י'\u0004 שניה למטה. היינו כשנתגלו ב \u0003י'\u0004 שנים, שהם אבא ואמא עלאין, ומתחברים במדרגה אחת, דהיינו בשביל דאבא, ששם דעת הנעלם, (כנ\"ל משפטים אות תקכ\"ח) בהתרגשות אחת כדי להפרד מן השמאל, כנ\"ל בדבור הסמוך. וזהו \u0003ו\"ד\u0004 הכלולות ביוד. שה \u0003י'\u0004 הוא אבא עלאה וה \u0003ו\"ד\u0004 הן אמא עלאה. אוי כשנסתלק אבא, שהוא \u0003י'\u0004 וה \u0003ו\"ד\u0004 מתגלית."],[11,"אינון בוסמין דטיפסא","וכו': אלו הבשמים, דהיינו הארות החכמה שנקראת בשמים וריח, של החקיקות האדומות, שהם כל הבחינות של קו שמאל, שהם אדומות, שעוברים, להאיר, אינן מתערבות במקום אלא שתיכף חוזרים למקומם, ככתוב, והחיות רצוא ושוב. שתיכף שבים למקומם. וכן, ברח לך אל מקומך, דהיינו שממהר לשוב בחזרה למקומו, וזסו\"ה אם תגביה כנשר ואם בין כוכבים תשים קנך, דהיינו שתרצה להמשיך החכמה ולעכבה, אומר הכתוב, משם אורידך. אלא שהמשכת החכמה צריכה להיות, בדרך הכתוב, והחיות רצוא ושוב, שיחזירה תיכף ומיד למקומה, דהיינו ממטה למעלה. ועי' באדרא (נשא דף קל\"ג ע\"א), שעל ארחא דתחות חוטמא, שמשם מאיר החכמה, אומר שהוא \u0003אורחא לאעברא ביה.\u0004 דהיינו ג\"כ שלא לעכב ההארה אלא להחזירו תיכף למקומו. \u0003טיפסא,\u0004 פירושו דפוס וחקיקה, כי על ויצר אותו בחרט, מתרגם בטופסא. \u0003שריקין\u0004 פירושו אדומים, מלשון לא תעבור שרק על פניה (שבת צ\"ה:)."]],[]],[["וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא. אֵימָתַי, כַּד שְׁמָא אִתְנְטַע. וּכְדֵין אֲוִירָא נָפִיק, וְנִצוֹצָא אִזְדָּמָן. (תיקונא קדמאה דרישא) חַד גּוּלְגַלְתָּא אִתְפָּשָּׁט בְּסִטְרוֹי, טַלָּא מָלֵּי עָלָהּ, דִּתְרֵי גְּוָונֵי.","תְּלַת חַלָלִּין דְּאַתְוָון רְשִׁימִין, אִתְגַּלְּיָין בֵּיהּ. (תליתאה) אוּכָמִין (ס\"א כעורבא) כְּעַרְבָאָה תַּלְיָין עַל נוּקְבִין עֲמִיקִין, דְּלָא יָכִיל לְמִשְׁמַע יְמִינָא וּשְׂמָאלָא. הָכָא חַד אָרְחָא לְעֵילָּא דָּקִיק.","(רביעאה) מִצְחָא דְּלָא נָהִיר, קְטָטוּתָא דְּעָלְמָא. בַּר כַּד רַעֲוָא אַשְׁגַּח בֵּיהּ. (חמישאה) עַיְינִין דִּתְלַת גְּוָונֵי, לְמִרְתַּת קָמַיְיהוּ אִתְסְחָן בְּחֲלָבָא דְּנָהִיר. כְּתִיב (ישעיהו ל״ג:כ׳) עֵינֶיךָ תִרְאֶינָה יְרוּשָׁלַיִם נָוְה שַׁאֲנָן, וּכְתִיב (ישעיהו א׳:כ״א) צֶדֶק יָלִין בָּה. נָוֶה שַׁאֲנָן, עַתִּיקָא דְּסָתִים, עֵינְךָ כְּתִיב.","(שתיתאה) חוֹטָמָא פַּרְצוּפָא דִּזְעֵירָא, לְאִשְׁתְּמוֹדְעָא. תְּלַת שַׁלְהוֹבִין מִתּוֹקָדִין בְּנוּקְבוֹי. (שביעאה) דַּרְגָּא עֲקִימָא, לְמִשְׁמַע טָב וּבִישׁ.","כְּתִיב (ישעיהו מ״ב:ח׳) אֲנִי יְיָ' הוּא שְׁמִי. וּכְתִיב (דברים לכ) אֲנִי אֲמִית וַאֲחֲיֶּה. וּכְתִיב (ישעיהו מ״ו:ד׳) וַאֲנִי אֶשָּׂא וַאֲנִי אֶסְבּוֹל. (קל\"ד ע\"ב) (תהלים ק) הוּא עָשָׂנוּ וְלוֹ אֲנַחְנוּ. (איוב כ״ג:י״ג) וְהוּא בְּאֶחָד וּמִי יְשִׁיבֶנּוּ. הוּא אִקְרֵי מַאן דְּסָתִים וְלָא שְׁכִיחַ, הוּא מַאן דְּלָא אִזְדָּמָן לְעֵינָא. הוּא מַאן דְּלָא אִקְרֵי בִּשְׁמָא.","(ה\"א ה\"י) א' כָּלִיל (הוא') ו'. ו' כָּלִיל א' וְלָא כָּלִיל ה\"ו. (ס\"א ה\"י) א' אָזִיל לְאָלֶף. אל\"ף אָזִיל ליו\"ד, יו\"ד אָזִיל ליו\"ד, דְּסָתִים מִכָּל סְתִימִין, דְּלָא מִתְּחַבְּרָן בֵּיהּ ו\"ד. וַוי כַּד לָא נָהִיר י' בו\"ד.","כַּד אִסְתַּלָּק י' מִן ו\"ד בְּחוֹבֵי עָלְמָא, עֶרְיָיתָא דְּכֹלָּא אִשְׁתְּכַח, עַל דָּא כְּתִיב (ויקרא י״ח:ח׳) עֶרְוַת אָבִיךָ לא תְגַלֵּה. וְכַד אִסְתָּלִיק יוֹ\"ד מִן הֵ\"א, עַל דָּא כְּתִיב וְעֶרְוַת אִמְּךָ לא תְגַלֶּה אִמְּךָ הִיא לֹא תְגַלֵּה עֶרְוָתָהּ. אִמְּךָ הִיא וַדַּאי, (משלי ב׳:ג׳) כִּי אִם לַבִּינָה תִקְרָא וְגוֹ'.","\u0003פִּרְקָא תְּלִיתָאָה\u0004 תִּשְׁעָה תִּקּוּנִין יַקִּירִין אִתְמְסָרוּ לְדִיקְנָא כָּל מָה דְּאִתְטְמַּר וְלָא אִתְגַּלְיָיא עִלָּאָה וְיַקִּירָא אִשְׁתְּכַח. (והוא) והָא (ס\"א דיקנא) גַּנְזֵיהּ (ס\"א יקירא) קְרָא.","תִּיקוּנָא קַדְמָאָה דְּדִיקְנָא, נִימִין עַל נִימִין מִקָּמֵי פִּתְחָא דְּאֻדְנִין עַד רֵישָׁא דְּפוּמָא. (תניינא) מֵרֵישָׁא הַאי, עַד רֵישָׁא אַחֲרָא אִשְׁתְּכַח. (תליתאה) מִתְּחוֹת תְּרֵין נוּקְבִין אָרְחָא מַלְיָיא דְּלָא אִתְחַזְיָיא. (רביעאה) עַלְעִין אִתְחַפְיָּין מֵהַאי גִּיסָא וּמֵהַאי גִּיסָא. (חמישאה) בְּהוּ אִתְחַזְּיָין תַּפּוּחִין סוּמָקִין כְּוורְדָא. (שתיתאה) בְּחַד חוּטָא תַּלְיָין אוּכָמִין תַּקִּיפִין עַד חַדּוֹי. (שביעאה) שִׂפְוָון סוּמָקִין כְּוורְדָא אִתְפְּנוּן.","(תמינאה) זְעִירִין נַחְתִּין בִּגְרוֹנָא, וּמְחַפְיָין קְדָלָא. (תשיעאה) רַבְרְבִין וּזְעִירִין כְּגִידִין (ס\"א נגדין) (ס\"א נחתין) בְּשִׁקּוּלָא. בְּאִלֵּין אִשְׁתְּכַח גִּיבָּר וְתַקִּיף מַאן דְּאִשְׁתְּכַח.","כְּתִיב (תהילים קי״ח:ה׳) מִן הַמֵּצַר קָרָאתִי יָהּ. תִּשְׁעָה אָמַר דָּוִד עַד כָּל גּוֹיִם סְבָבוּנִי, לְאַסְחֲרָא וּלְאַגָּנָא עֲלוֹי. וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע לְמִינֵהוּ וְעֵץ עוֹשֶׂה פְּרִי אֲשֶׁר זַרְעוֹ בוֹ לְמִינֵהוּ. (נשא קל\"ט ע\"ב) תִּשְׁעָה אִלֵּין אִתְעֲקָרוּ מִשְּׁמָא שְׁלִים, וְאַשְׁתִּילוּ לְבָתַר בִּשְׁמָא שְׁלִים, דִּכְתִּיב וַיִּטַּע יְיָ' אֱלהִים. תִּקּוּנִין דְּדִיקְנָא בִּתְלֵיסָר אִשְׁתַּכְּחָן אִיהִי, דְּהִיא עִלָּאָה. תַּתָּאָה, בְּתִשְׁעָה אִתְחָזוּן. כ\"ב אַתְוָון אִתְגְּלִיפוּ בְּגווַֹנֵיהוֹן (ס\"א בגינהון.)","עַל הַאי, (ס\"א על האי מאן דחזי בחלמיה דיקנא) חֶלְמָא דְּאָחִיד דִּיקְנָא דְּבַּר נָשׁ עִלָּאָה בִּידֵיהּ, (נ\"א או דאושיט ידיה ליה אנדע דשלים במאריה) שְׁלִים בְּמָארֵיהּ. שַׂנְאִין תְּחוֹתוֹי יִכְנְעוּן. כָּל שֶׁכֵּן דִּיקְנָא עִלָּאָה דִּנְהִירָא (ס\"א לתתאה) בְּתַתָּאָה, דְּעִלָּאָה רַב חֶסֶד אִקְרֵיהּ, בִּזְעֵירָא חֶסֶ\"ד סְתָם, כַּד אִצְטְרִיךְ נְהִירוּ אַנְהַר וְאִקְרֵי רַב חֶסֶד. (ס\"א בידיה הא מתרחיץ דהא בשלם עם מאריה ושנאוי יכנעון תחותוי ודין הוא בדיל דחזא בחלמיה כל שכן אם זכה לאודעא מה היא דיקנא עלאה דהוא נהיר לתתאה ארים עלאה רב בחסד אקרי בזעירא חסד סתם)","כְּתִיב וַיֹּאמֶר אֱלהִים יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה, כְּלוֹמַר, (נ\"א ח\"י י\"ה) י\"ה אִתְפָּשַׁט נְהִירוּ דְּדָא בְּדָא, כֹּלָּא אִתְרַחֲשׁוּן בְּזִמְנָא חֲדָא, מַיִם טָבָאן מַיִם בִּישָׁן. בְּגִין דְּאָמַר יִשְׁרְצוּ, אִתְכְּלָלוּ דָּא בְּדָא. חַיָּה עִלָּאָה, חַיָּה תַּתָּאָה. חַיָּה טָבָא. חַיָּה בִּישָׁא."],[[0,"ותוצא הארץ דשא:","מתי נעשה זה, הוא, כאשר השם, שהוא הנוקבא, ניטעה. דהיינו אחר שנבנה הנוקבא מבחינת מחזה ולמטה, שאז \u0003מה דהוית יבשה,\u0004 וכו', כנ\"ל (אות י\"ט בהסולם) וכה יצא מאבא ואמא, אויר, שהוא אור חסדים מאבא וניצוץ, שהוא אור הגבורות מאמא וכשנתחברו האויר והניצוץ יחדיו נתפשט מהם גלגלתא אחת, שהוא כתר דז\"א בצדדיו, דהיינו ד' צדדים חו\"ב, וחו\"ג דדעת, והם בחינת או\"א עלאין שבראש ז\"א, והם סוד \u0003ם\u0004 דצלם. עליה על הגלגלתא, היא נמלאה טל מב' גוונים דהיינו לבן ואדום, בסו\"ה טל אורות טלך, שהם אור חסד ואור גבורה. וזהו תקון הראשון מז' תקוני גלגלתא דז\"א."],[1,"תלת חללין דאתוון","וכו': תקון ב', ג' חללים של אותיות הרשומות, דהיינו \u0003יה\"ו,\u0004 שהם חכמה בינה דעת, נתגלו בו. וה\"ס \u0003ל\u0004 דצלם שבראש ז\"א. תקון השלישי, שערות שחורות כעורב תלויות על נקבי האזנים העמוקות, ואינו יכול לשמוע ימין ושמאל. כי השערות שהם הדינים סותמים אותם. ובגדלות מסתלקים השערות מעל האזנים כמ\"ש בתקון הז'. כאן בשערות שעל הגלגלתא דז\"א, יש למעלה ארח אחד דק. דהיינו הארח שבאמצע הראש ששם מתחלקים השערות לימין ושמאל."],[1,"","פירוש. גם ז' תיקוני גלגלתא דז\"א מתחלקים על ג' בחינות מל\"צ דצלם, כמו ז' תקוני גלגלתא דא\"א שנתבארו לעיל (אות ו') אלא בדרך אחר, כי חסר כאן התקון דקרומא דאוירא, ונתוסף כאן תקון באזנים, אשר בקטנות השערות סותמות האזנים, שזהו תקון ג'. ובגדלות מסתלקות השערות מאזנים, שזהו תקון הז', ואז התפלות מתקבלות מן התחתונים. וכן נתקנה הגלגלת בד' מוחין, חכמה, בינה, וחסד וגבורה דדעת. ועל שם ד' מוחין אלו נקראת \u0003ם'\u0004 דצלם, כי כל מוח כלול מעשר ספירות, והם \u0003ם'\u0004 בחינות, ויורה שבקו האמצעי, שהוא דעת, אינו מיחד ימין ושמאל להלביש החכמה שבשמאל בחסדים שבימין. שזה נעשה בכח הדין שבקו האמצעי, וע\"כ הדין נהפך לחסד, ושניהם בחינה אחת. וע\"כ הם \u0003ל':\u0004 ג' בחינות ע\"ס שהן חב\"ד. אבל ב \u0003ם'\u0004 דצלם, שה\"ס או\"א עלאין, אינם מקבלים חכמה לעולם, ואין צורך להכרעת קו האמצעי. ומשום זה החסד והדין שבקו אמצעי נבדלים זה מזה, כי הדין שבקו אמצעי אינו נהפך כאן להיות חסד, משום שאינו גורם היחוד דימין ושמאל. ונבחנים החסד והדין שבדעת לב' בחינות עשר ספירות נבדלות, וע\"כ יש ד' מוחין, והם \u0003ם'.\u0004 וזהו תקון הא'. ותקון הב' הם המוחין דישסו\"ת שבז\"א שה\"ס \u0003ל\u0004 דצלם שבראש ז\"א, שבהם הדעת מכריע בין ימין ושמאל שהם חכמה ובינה, בכח הדין שבו שהוא מסך דחירק, וע\"כ נהפך הדין להיות חסד, ואין כאן אלא ג' בחינות של עשר ספירות שהם \u0003ל'.\u0004 וזהו תקון הב'."],[1,"","תקון הג' הוא שערות שחורות כעורב, שהם נמשכים מן הדינים שבג' מוחין חב\"ד שבתקון הב'. וע\"כ הם סותמים האזנים שלא תבחנה מטוב לרע, ואין תפלות התחתונים מתקבלות. וזהו בעת קטנות, אבל בגדלות מתתקנות שערות אלו בסוד \u0003ם'\u0004 דצלם דנה\"י, ואז הם מסתלקות מעל האזנים והן נפתחות כמ\"ש להלן בתקון הז'. (באות כ\"ט) ויש על הגלגלתא דז\"א קו חלק, במקום שהשערות נחלקות לימין ושמאל, שהוא נקרא אורחא דפלגותא דשערי, ששם אין שערות ודינים כלל, אלא להיפך שהוא חסד נפלא, וע\"כ הוא לבן. וזסו\"ה, ואורח צדיקים כאור נגה הולך ואור עד נכון היום, שנאמר על אורחא דפלגותא דשערי שבגלגלתא דא\"א, ומאורח של א\"א, נמשך לארחא דפלגותא דשערי דז\"א, שעליו נאמר, כל ארחות ה' חסד ואמת. וסוד הדברים הוא, כי בשערות של ימין מתגלים על ידיהם חסדים, לעובדי ה'. ובשערות של שמאל מתגלים על ידיהם עונשים לרשעים שאינם עובדים את ה'. וכשמגיע זה לתחתונים הם מכירים את \u0003ההבדל,\u0004 שה\"ס אורחא דפלגותא דשערי, בין עובד ה' ללא עבדו. שע\"י הכרה זו, זוכים לדבקות השלם בהקב\"ה. ואז כל ארחות ה' חסד ואמת."],[2,"מצחא דלא נהיר","וכו': תקון הרביעי, הוא מצח שאינו מאיר, שנמשך ממנו דין ומריבה לעולם חוץ מבעת הגדלות, כאשר רצון דמצח דא\"א משגיח במצח דז\"א. תקון החמשי הוא, עינים בג' גוונים, שהם שחור אדום ירוק, ליראה מפניהם. כי כל גוונים אלו רומזים לדינים, כי אדום, הוא שמאל, וירוק, הוא קו האמצעי ושחור היא המלכות ובגדלות הן רוחצות בחלב, המאיר, שה\"ס החסד. הנמשך מעתיקא. שכתוב, עיניך תראנה ירושלים נוה שאנן, דהיינו בלי שום דין. וכתוב צדק ילין בה. הרי שיש בה דין הנקרא צדק, ומשיב, נוה שאנן, נאמר, בשעה שעינו של עתיק הסתום מאיר בסו\"ה רוחצות בחלב, כי עינך כתוב, בלי יוד דלשון רבים. כי בעתיקא אין שמאל, וב' עינים נחשבים לעין ימין."],[3,"חוטמא פרצופא דזעירא","וכו': תקון הששי הוא, חוטם הפרצוף שהוא קצר, להכרה. שבחוטם ניכר הפרצוף. כמ\"ש ז\"ל אין מעידים אלא עד שיהיה פרצוף פנים עם החוטם (יבמות ק\"פ.) ג' שלהבות שורפות בנקביו. שהן ג' בחינות דין, דין הנמשך מבינה, וממלכות, ומקו שמאל. תקון הז' הוא, מדרגה עקומה, לשמוע טוב ורע, דהיינו האזנים בעת הגדלות, שנסתלקו מהם השערות שסתמו אותם כנ\"ל (אות כ\"ז) שאז נפתחו לשמוע טוב ורע, להטיב לטובים ולהעניש הרעים ולקבל תפלות התחתונים. (ועי' ויקהל אות קל\"ח)."],[3,"","ונתבארו ז' תקוני גלגלתא דז\"א, אשר גלגלתא וד' סטרין שבה, ה\"ס \u0003ם'\u0004 דצלם וג' חללי גלגלתא, ה\"ס \u0003ל\u0004 דצלם. והשערות וב' אזנים ה\"ס נו\"ה הנסתרים ומצחא ה\"ס יסוד שבהם. וב' עינים ה\"ס נו\"ה הנגלים, וחוטמא היא יסוד ומלכות שבהם. והספרא דצניעותא מפרש כאן בעיקר בחינות דין שבהם בעת קטנות. והבחינות מל\"צ דצלם נאמר בעיקר לעת גדלות. כמ\"ש לעיל בז' תקוני גלגלתא דא\"א."],[4,"כתיב אני","וכו': כתוב, אני הויה הוא שמי. שאומר לשון נגלה, \u0003אני,\u0004 ולשון נסתר \u0003הוא,\u0004 במשיכה אחת, שהיה לו לומר אני הויה שמי, ואומר שאני והוא הם ב' שמות, שכתוב, אני אמית ואחיה. וכתוב, ואני אשא ואני אסבול. הרי שאני הוא שם, והיינו שם המלכות. וגם \u0003הו\"א\u0004 שם. שכתוב, הוא עשנו ולו אנחנו. וכן והוא באחד ומי ישיבנו. הרי שנקרא ג\"כ בשם \u0003הו\"א\u0004 כי \u0003הו\"א\u0004 נקרא מי שסתום ואינו נמצא. דהיינו חכמה סתימאה דא\"א, שנסתם ואינו נפתח עד גמר התקון, \u0003הוא\u0004 נקרא, מי שאינו מזדמן לעין, דהיינו שאינו מזדמן לקבלת החכמה, המכונה עין. דהיינו או\"א עלאין שהם חסדים מכוסים ואינם מקבלים חכמה לעולם, שעליהם נאמר, כי חפץ חסד הוא. \u0003הו\"א\u0004 נקרא, מי שלא נקרא בשם, דהיינו הבינה שהיא ישסו\"ת, שיצא בה קו השמאל, ומטרם שקו האמצעי, הכריע בין ימין ושמאל להלביש החכמה שבשמאל בחסדים שבימין אינה נקראת בשם, כי היא סתומה ואינה מאירה, (כנ\"ל בהקסה\"ז דף י\"ז ד\"ה קיימא ע\"ש)."],[5,"הוא, ה' כליל","וכו': ומפרש המשמעות של ג' אותיות \u0003הו\"א,\u0004 על פי מה שאמר לעיל שה\"ס ואו\"א וישסו\"ת נקראים כל אחד \u0003הוא,\u0004 ואומר, \u0003ה'\u0004 של הוא כולל \u0003ו',\u0004 וה \u0003ו'\u0004 כולל \u0003א'\u0004 של הוא, ואינו כולל \u0003ה'\u0004 של הוא, אלף הולכת ל \u0003י', י'\u0004 הולכת ל \u0003י'\u0004 הסתומה מכל סתימין, שאין מחוברות בו \u0003ו\"ד\u0004 של מילוי יוד. אוי כשה \u0003י'\u0004 אינה מאירה ל \u0003ו\"ד.\u0004"],[5,"","פירוש. \u0003ה'\u0004 ד \u0003הו\"א\u0004 היא בינה כשהיא בשמאל, טרם היחוד דקו האמצעי, כנ\"ל. \u0003ו'\u0004 ד \u0003הו\"א,\u0004 הוא ז\"א, שבעת שבינה מחזרת הבינה ותו\"מ שלה לבחינת קו שמאל, עולה עמהם גם ז\"א לבינה, ונעשה שם בצורת \u0003א'\u0004 ד \u0003הו\"א,\u0004 שהוא ציור אותיות \u0003י' ו' ד',\u0004 שה \u0003ו'\u0004 הוא ז\"א, קו האמצעי, ו \u0003י'\u0004 עליונה שעליו הוא ימין דבינה הכלול בז\"א, וה \u0003ד'\u0004 שמתחתיו הוא שמאל, דבינה הכלול בז\"א."],[5,"","וזה אמרו, \u0003ה'\u0004 כלול \u0003ו',\u0004 שבעת יציאת השמאל דבינה כבר הבינה כוללת בתוכה ה \u0003ו',\u0004 שהוא ז\"א, שעלה עם הבינה ותו\"מ דבינה ביחד, כנ\"ל. וה \u0003ו'\u0004 כליל \u0003א',\u0004 שהוא סוד ה \u0003ו'\u0004 שבאמצע ה \u0003א'\u0004 הכלול מב' קוין דבינה, שהם \u0003י\"ד\u0004 אבל, \u0003ולא כליל ה'\u0004 כי ה \u0003ו'\u0004 עוד לא הכריע בין ימין ושמאל של ה \u0003ה',\u0004 וע\"כ אינו כולל אותה, וע\"כ \u0003א' אזיל לי',\u0004 כלומר שההארה של ז\"א שהוא \u0003א'\u0004 אינה מאירה רק ב \u0003י'\u0004 עליונה שלה, שהיא ימין, כי השמאל שבה, שהוא \u0003ד'\u0004 עוד אינו מאיר, להיותו לפני ההכרעה של קו אמצעי, כנ\"ל. וע\"כ נקרא ישסו\"ת הוא, שהאורות נסתרים מן התחתונים ונבחן בזה שה \u0003א'\u0004 הולכת ל \u0003י',\u0004 שהוא או\"א עלאין, וגורמת בהם, שגם ה \u0003י\u0004 שהוא אבא תתפרד מן \u0003ו ד\u0004 שהיא אמא ואז גם אורותיהם נסתרים ונקראים \u0003הוא.\u0004 וה \u0003י'\u0004 דאו\"א \u0003אזיל לי' דסתים מכל סתימין,\u0004 וה \u0003י'\u0004 שהוא או\"א הולכת לחכמה סתימאה דא\"א, שהוא סתום מכל סתומים \u0003דלא מתחברן ביה ו\"ד\u0004 שגורמת שאינו משפיע לנוקבא הנקרא \u0003ו' ד'\u0004 דמילוי יוד, דהיינו הבינה שחזרה לראשו, וע\"כ קרא גם הוא \u0003הוא,\u0004 וע\"כ אבא שהוא \u0003י'\u0004 אינו מאיר לאמא, שהוא \u0003ו\"ד\u0004 דמילוי \u0003י',\u0004 וכיון שאמא שהיא \u0003ו\"ד\u0004 אינה מאירה, נמצא שישסו\"ת שהיא \u0003ה'\u0004 דהויה, ודאי שאינם מאירים, כי הם מקבלים מאמא עלאה שהיא \u0003ו\"ד.\u0004 וז\"ש ווי כד לא נהיר \u0003י'\u0004 ב \u0003ו\"ד,\u0004 שאז נעשה פרוד גם בין \u0003י'\u0004 ל \u0003ה'.\u0004 כמבואר."],[6,"כד אסתלק י'","וכו': כשנסתלקה ה \u0003י'\u0004 מן ו\"ד מחמת עונות העולם נתגלה ערוה של כולם, כי הו\"ד היא אמא עלאה שכל פרצופי אצילות ובי\"ע מקבלים ממנו, והיא נחשכה. על זה כתוב, ערות אביך לא תגלה, דהיינו אבא ואמא עלאין, שהם יוד, שנקראים שניהם בשם אבא. וכשנסתלקה היוד מן \u0003ה'\u0004 שאחר ש \u0003ו\"ד\u0004 נחשכו אין ה \u0003י'\u0004 יכולה להשפיע ל \u0003ה'\u0004 שהיא ישסו\"ת, כנ\"ל בדבור הסמוך, ע\"ז כתוב, וערות אמך לא תגלה אמך היא לא תגלה ערותה. כי ישסו\"ת נקראים שניהם בשם אמא. אמך היא ודאי כמו שכתוב כי אם לבינה תקרא הרי שיסו\"ת שהם בינה מכונים אם."],[7,"פרקא תליתאה. תשעה","וכו': פרק השלישי. תשעה תקונים יקרים נמסרו לזקן. כל מה שנתכסה ולא נתגלה נמצא עליון ויקר. והדיקנא הרי גנזו הכתוב, שלא נמצא שום כתוב שידבר מדיקנא. כמ\"ש עיני ה' אזני ה' וכן לחייו ערוגת הבושם. ואין זכר לדיקנא. והוא משום שהוא עליון ויקר."],[8,"תקונא קדמאה דדיקנא","וכו': תקון הראשון של הזקן, שערות על שערות יוצאות מכנגד פתח האזנים עד ראש הפה, כלומר עד שפה עלאה. תקון השני, נמצא מראש הזה של השפה עד ראש האחר של השפה. תקון השלישי, ארח הנמצא תחת ב' נקבי החוטם, והוא מלא שערות עד שאינו נראה. תקון הרביעי, הלחיים מתכסים בשערות מצד זה ומצד זה. תקון החמשי, בהם נראים ב' תפוחי הפנים האדומים כורד. תקון הששי, בחוט אחד תלויות שערות שחורות תקיפות עד החזה. תקון השביעי, השפתים נפנו משערות, והם אדומים כורד."],[9,"זעירין נחתין בגרונא","וכו': תקון השמיני, שערות קצרות יורדות על הגרון ומכסות העורף. תקון התשיעי, שערות גדולות וקטנות קשים כגידים יורדות בשוה. דהיינו שמתערבות אלו באלו והן שוות. באלו ט' תקונים נמצא גבור ותקיף מי שנמצא. דהיינו ז\"א."],[9,"","פירוש. ט' תקוני דיקנא דז\"א נמשכים מי\"ג תקוני דיקנא דא\"א שנתבארו היטב לעיל שח' תקונים נמשכים מחכמה סתימאה, וה' תקונים מגלגלתא, ואלו הנמשכים מח\"ס, הן ג\"פ נרנח\"י דנפש ודרוח ודנשמה. ע\"ש. וההפרש הוא, כי י\"ג תקונים הם בחי' ג\"ר ממש, אבל ט' תקונים הם בחי' ו\"ק דג\"ר."],[9,"","וע\"ז תבין שתקון ראשון, הוא שורש הדיקנא, כמו תיקון הא' די\"ג ת\"ד דא\"א. וכן תקון הב' היא בחינת עבור בלחי העליון, והוא ו\"ק דנפש. תקון ג' הוא ג\"ר דנפש. ובתקון ד' יש שינוי, כי תקון ד' די\"ג ת\"ד דא\"א, הוא שערות דשפה תתאה, ותקון ה' הוא אורחא שבשערות שפה תתאה, שהם ו\"ק דרוח וג\"ר דרוח. אבל כאן אין אורחא בשפה תתאה דז\"א, משום שגם ארחא דשפה עלאה אינו מאיר כל כך משום שמלא עם שערות. וע\"כ נתקנו כאן במקומם לו\"ק דרוח, \u0003עלעין אתחפיין מהאי גיסא ומהאי גיסא.\u0004 והג\"ר דרוח הוא תקון ה', בהו \u0003אתחזיין תפוחין סומקין כורדא,\u0004 וכיון שג\"ר דרוח הן בחי' אחורים, ע\"כ הם אדומים. ותקון הששי כאן, הוא כללות הדיקנא, שהו\"ק דרוח שבפנים נמשכים למקומם למטה, בלחי התחתון. ותקון השביעי, \u0003שפוון סומקין כורדא אתפנון.\u0004 שהם ג\"ר דרוח הנמשכים מב' תפוחין למטה. ותקון השמיני, \u0003זעירין נחתין בגרונא\u0004 נמשך מתקון ה \u0003ט'\u0004 וה \u0003י'\u0004 די\"ג ת\"ד דא\"א. ותקון הט' נמשך מתקון י\"א שביגת\"ד דא\"א."],[10,"כתיב מן המצר","וגו': כתוב, מן המצר קראתי יה, ט', אמר דוד עד כל גוים סבבוני כדי לסבב עצמו בהם ולהגן עליו. שהם כנגד ט' תקוני דיקנא דז\"א. א) מן המצר קראתי יה. ב) ענני במרחב יה. ג) ה' לי לא אירא. ד) ה' לי בעוזרי. ה) טוב לחסות בה'. ו) טוב לחסות בה' הב' ועם ג\"פ אדם שיש בהם, הרומזים לג' תקונים, הם תשע. ואלו ט' תקונים, הם בסוד הכתוב, ותוצא הארץ דשא, עשב, מזריע, זרע, למינהו, ועץ, עושה פרי, אשר זרעו בו, למינהו. תשעה תקוני דיקנא אלו נתעקרו משם שלם, דהיינו מי\"ג תי\"ד דא\"א, ובאו לז\"א, כנ\"ל. ואחר כך חזרו ונשתלו בשם שלם, שנאמר ויטע ה' אלקים, שהוא שם מלא דעתיק ודז\"א, (כמ\"ש באדרת נשא דף קל\"ח ע\"ב, ד\"י) תקוני דיקנא נמצאים י\"ג באותו שהוא עליון, דהיינו דא\"א, התחתון, שהוא ז\"א, נראים בט' תקוני דיקנא, וי\"ג וט' הם כ\"ב, שהם כ\"ב אותיות שנחקקו מחמתם."],[11,"על האי חלמא","וכו': על כן אם ראה בחלום, שאוחז בידו זקן של אדם חשוב, הוא שלם עם אדונו, שונאיו יכנעו תחתיו. כל שכן זקן העליון, דא\"א, המאיר לזקן התחתון, דז\"א. כי זקן העליון נקרא רב חסד, ובז\"א נקרא חסד סתם. וכשהוא צריך לאור מאיר לו זקן העליון, ונקרא גם הוא רב חסד."],[12,"ויאמר אלקים","וגו': ויאמר אלקים ישרצו המים שרץ נפש חיה. כלומר, ח\"י י\"ה, כי בחיה יש אותיות ח\"י י\"ה. \u0003חי\u0004 היינו היסוד של ז\"א. \u0003י\"ה\u0004 היינו או\"א. וישרצו המים פירוש שיתפשט אור של זה בזה, דהיינו שיתפשט אור י\"ה בח\"י שהוא יסוד דז\"א, ותצא נפש חיה שהיא הנוקבא, וכן נפשו של אדם הראשון. הכל שרץ בזמן אחד, מים טובים דקדושה, ומים הרעים דס\"א, וכיון שאמר \u0003ישרצו,\u0004 נכללו זה בזה, ויצא חיה עלאה, דהיינו הנוקבא, חיה תתאה, דהיינו נפשו של אדם הראשון. חיה טובה, שהיא הנוקבא, חיה רעה, שהיא לילית, כי נפש חיה הרומשת זו לילית (כמ\"ש לעיל ב\"א אות ת\"ח)."]],[]],[["דָּבָר אַחֵר יִשְׁרְצּוּ הַמַּיִם, תַּרְגּוּם יְרַחֲשׁוּן. כְּלוֹמַר, כַּד מְרַחֲשִׁין בְּשִׂפְוָותֵיהּ פִּתְגָּמֵי צְּלוֹתָא, בְּזָכּוּתָא, וּבִנְקִיוּת דַּעְתָּא, וּבְמַיָא הֲוָה רָחִישׁ נַפְשָׁא חַיָּתָא. וְכַד בָּעֵי בַּר נָשׁ לְסַדְּרָא צְּלוֹתֵיהּ לְמָארֵיהּ, וְשִׂפְוָותֵיהּ מְרַחֲשָׁן בְּהַאי גַּוונָא מִתַּתָּא לְעֵילָּא, לְסַלְּקָא יְקָרָא דְּמָארֵיהּ, לְאֲתָר דְּשַׁקְיוּ דַּעֲמִיקוּ דְּבֵירָא, נָגִיד וְנָפִיק. לְבָתַר יָנְגִיד לְאַמְשָׁכָא מִלְעֵילָּא לְתַתָּא, מֵהַהוּא שַׁקְיָא דְּנַחֲלָא, לְכָל דַּרְגָּא ודַרְגָּא, עַד דַּרְגָּא בַּתְרָאָה לְאַמְשָׁכָא נְדָבָה לְכֹלָּא מֵעֵילָּא לְתַתָּא. לְבָתַר בָּעֵי לְקַשְּׁרָא קִשְׁרָא בְּכֹלָּא, קִשְׁרָא דְּכַוָּנָה דִּמְהֵימְנוּתָא ויַעְבְּדוּן כָּל מִשְׁאַלוֹהִי, בֵּין שְׁאֶלְתָּא דְּצִּבּוּרָא, בֵּין שְׁאֶלְתָּא דְּיָחִידָא.","וּשְׁאֶלְתָּא דְּאִית לְבַר נָשׁ לְשַּׁאֲלָא מִמָּארֵיהּ, הֵן מְסוּדָרוֹת בט' גְּוָונֵי, אִית בְּאַלְפָא בֵּיתָא, וְאִית בְּאַדְכָּר מְכִילּוֹהִי דְּקוּדְשָׁא בְּרִיךְ הוּא, רַחוּם וְחַנּוּן וגוֹ'. אִית בִּשְׁמָהָן יַקִירָן דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּגוֹן אֶהְיֶה, יָהּ, יהו, אֵל, אֱלהִים, יְיָ' צְּבָאוֹת, שַׁדַּי, אֲדֹנָי. אִית בְּעֶשֶׂר סְפִירָא, כְּגוֹן: מַלְכוּת, יְסוֹד, הוֹד, נְצַּח, תִפְאֶרֶת, גְּבוּרָה, חֶסֶד, בִּינָה, חָכְמָה, כֶּתֶר. אִית בְּאַדְכָּר צַּדִּיקַיָּיא, כְּגוֹן הָאָבוֹת וְהַנְּבִיאִים וְהַמְּלָכִים. אִית בְּשִׁירֵי וּבְתוּשְׁבַּחְתֵּי, דְּאִית בְּהוֹן קַבָּלָה אֲמִיתִּית. וְעֵילָּא מִנְּהוֹן מַאן דְּיָדַע לְתַקֵּן תִּקּוּנִין לְמָארֵיהּ, כְּדְקָא יֵאוֹת. ואִית בִּידִיעָה סַלְּקָא מִתַּתָּא לְעֵילָּא, וְאִית מַאן דְּיָדַע לְהַמְשִׁיךְ שִׁפְעָא מֵעֵילָּא לְתַתָּא.","וּבְכָל ט' גְּוָונִי אִלֵּין, צְּרִיכָא כַּוָנָה גְּדוֹלָה, וְאִי לָא עָלֵיהּ קְרָא דִּכְתִּיב, (שמואל א ב׳:ל׳) וּבוֹזַי יִקָלּוּ. וּבְכַוָונַת אָמֵן, דְּהוּא כָּלִיל תְּרֵין שְׁמָהָן יְהוָֹ\"ה אֲדֹנָ\"י. וְהָאֶחָד גָּנִיז טוּבֵיהּ וּבִרְכוֹהִי, בְּאוֹצָּר הַנִּקְרָא הֵיכָל, וְהוּא רָמוּז בַּפָּסוּק (חבקוק ב׳:כ׳) וה' בְּהֵיכַל קָדְשׁוֹ הַס מִפָּנָיו וּלְדָּא רָמְזּוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, כָּל טוּב הָאָדָם בְּבֵיתוֹ, שֶׁנֶּאֱמַר (במדבר י״ב:ז׳) בְכָל בֵּיתִי נֶאֱמָן הוּא, וּמְתַּרְגְמִינָן בְכָל דְּעִמִּי.","ואִי מְכַוּון בְכָל חַד וְחַד מט' גְּוָונִי כְּדְקָא יֵאוֹת, דָּא הוּא בַּר נָשׁ דְּאוֹקִיר לִשְׁמָא דְּמָארֵיהּ לִשְׁמָא קַדִּישָׁא, וְעַל דָּא כְּתִיב כִּי מְכַבְּדַי אֲכַבֵּד וּבוֹזַי יֵקָלּוּ, אֲכַבֵּד בְּעָלְמָא דֵּין, לְקַיִּים וּלְמֶעְבַּד כָּל צָּרְכוֹי. וְיְחֶזּוּן כָּל עַמָּמֵי אַרְעָא, אֲרֵי שְׁמָא דְּה' אִתְקְרֵי עָלֵיהּ, וִידַחֲלוּן מִנִּיהּ. וּבְעָלְמָא דְּאָתֵי, יִזְכֵּי לְמֵיקָם בִּמְחִיצַּת חֲסִידִים, אַף עַל פִּי דְּלָא קָרֵי כָּל צּוֹרְכֵיהּ, כֵּיוָן דְּזָכָה לְאַשְׁגְּחָא יְדִיעַת מָארֵיהּ, וְאִיכְוָון בֵּיהּ כַּדְקָא יֵאוֹת."],[[0,"דבר אחר, ישרצו המים:","תרגומו ירחשון, כלומר כשמרחשין שפתיו, דהיינו כשמתנועעות שפתיו דברי תפלה בזכות ובנקיות הדעת. ובמים המנקים ומטהרים, רוחש, נפש חיה, כי כשאדם רוצה לסדר תפלתו לאדונו שפתותיו מרחשות באופן הזה ממטה למעלה, להעלות כבוד אדונו, למקום השקיו של באר העמוק, שהיא בינה, ואח\"כ יזיל להמשיך ממעלה למטה, מאותו שקיו של הנחל, שהיא בינה, לכל מדרגה ומדרגה, עד מדרגה אחרונה, שהיא מלכות, להמשיך נדבה לכל ממעלה למטה. ואח\"כ צריך לקשר קשר בכלא, דהיינו שייחד כל המדרגות בא\"ס ב\"ה, קשר דכוונה של האמונה, ויעשו כל משאלותיו, בין משאלות הצבור בין משאלות יחיד."],[1,"ושאלתא דאית לבר נש","וכו': והתפלה שיש לאדם לבקש מאדונו, היא מסודרת בט' אפנים. א) יש שהתפלה מסודרת בסדר אלף בית. ב) ויש שמסודרת בהזכרת מדות הקב\"ה, רחום וחנון וכו'. ג) ויש שמסודרת בשמות היקרים של הקב\"ה, דהיינו אהיה יה יהו אל אלקים הויה צבאות שדי אדני. ד) ויש' שמסודרת בעשר ספירות, שהם, מלכות יסוד הוד נצח ת\"ת גבורה חסד בינה חכמה כתר. ה) ויש בהזכרת הצדיקים, דהיינו האבות והנביאים והמלכים. ו) ויש בשירות ותשבחות, שיש בהם קבלה אמיתית. ז) ולמעלה מהם, מי שיודע לתקן תקונים לאדונו כראוי. ח) ויש בידיעה להעלות ממטה למעלה. ט) ויש מי שיודע להמשיך שפע ממעלה למטה."],[2,"ובכל ט' גווני","וכו': ובכל ט' אופני תפלה אלו, צריכים כונה גדולה. ואם לא, עליו המקרא שכתוב, ובוזי יקלו. ובכוונת אמן, צריך לכוון, שהוא כולל ב' שמות הויה אדני, שהם בגי' צ\"א וגם אמן בגי' צ\"א, ושם האחד, שהוא הויה, ז\"א, גונז טובו וברכותיו באוצר הנקרא היכל, שהוא אדני. מלכות. וזה מרומז בפסוק, והויה בהיכל קדשו הס מפניו. ולזה רמזו רז\"ל, כל טוב האדם בביתו, כי אדם בגי' מ\"ה, שהוא שם הויה דאלפין, וכל טובו בביתו, שהוא אדני, מלכות. שנאמר בכל ביתי נאמן הוא ומתרגם, בכל דעמי, דהיינו המלכות."],[3,"ואי מכוון בכל","וכו': ואם מכוון בכל אחד ואחד מט' אפני התפלה כראוי, זה הוא אדם המכבד שם אדונו את שמו הקדוש, ועל זה כתוב, כי מכבדי אכבד ובוזי יקלו, אכבדו בעולם הזה לקיים ולעשות כל צרכיו, ויראו כל עמי הארץ כי שם הויה נקרא עליו וייראו ממנו. ובעולם הבא יזכה לעמוד במחיצת חסידים, דהיינו במחלקת החסידים, אע\"פ שלא קרא בתורה כל צרכו, כיון שזכה להסתכל בידיעת אדונו וכיוון בו כראוי."]],[]],[["מַאי וּבוֹזַי יֵקָלּוּ. דָּא הוּא מַאן דְּלָא יָדַע לְאַחֲדָא שְׁמָא קַדִּישָׁא, וּלְקַשְּׁרָא קִשְׁרָא דִּמְהֵימְנוּתָא, וּלְאַמְשָׁכָא לְאֲתָר דְּאִצְּטְרִיךְ, וּלְאוֹקִיר שְׁמָא דְּמָארֵיהּ טָב לֵיהּ דְּלָא אִתְבְּרֵי. וְכָּל שֶׁכֵּן מַאן דְּלָא אִתְכַּוָּון בְּאָמֵן. וְעַל דָּא, כָּל מַאן דְּמַרְחִישׁ בְּשִׂפְוָותֵיהּ בִּנְקִיוּתָא דְּלִבָּא, בְּמַיָּא דִּמְנַקֵּי, מַאי כְּתִיב בַּהֲדֵיהּ, וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם, כְּלוֹמַר, בִּשְׁבִיל אָדָם דְּיָדַע לְאַחֲדָא צֶּלֶם וּדְמוּת כְּדְקָא יֵאוֹת, וירְדוּ בִדְגַּת הַיָּם. (עד כאן דבר אחר)","וַיֹּאמֶר אֱלהִים נַעֲשֶׂה אָדָם. הָאָדָם לָא כְּתִיב, אֶלָּא אָדָם סְתָם, לְאַפָּקָא אָדָם דִּלְעֵילָּא. דְּאִתְעָבִיד בִּשְׁמָא שְׁלִים. כַּד אִשְׁתְּלִים דָּא, אִשְׁתְּלִים דָּא. אִשְׁתְּלִים דְּכַר וְנוּקְבָּא לְאַשְׁלְמָא כֹּלָּא. יְדוָֹ\"ד סִטְרָא דִּדְּכַר. אֱלהִים סִטְרָא דְּנוּקְבָּא. אִתְפָּשַׁט דְּכוּרָא, וְאִתְתְּקַּן בְּתִקּוּנוֹי כְּאִמָּא, בְּפוּמֵיהּ דְּאָמָה. מַלְכִין דְּאִתְבְּטָלוּ, הָכָא אִתְקָיָּימוּ.","דִּינִין (קמ\"ב ע\"ב) דִּדְכוּרָא תַּקִּיפִין בְּרִישָׁא, בְּסוֹפָא נַיְיחִין. דְּנוּקְבָּא בְּאִיפְּכָא. וְי\"ה קוּנְטִירִין דְּקִיטוּרָא בְּעִטְפוֹי שְׁקִיעִין. י' זְעֵירָא בְּגַוָוהָא אִשְׁתְּכַח.","אִי אִתְבְּסָמוּ דִּינִין, בָּעָא עַתִּיקָא. אָתָא חִוְיָא עַל נוּקְבָּא, וְקִינָא דְּזוּהֲמָא אִתְתָּקַן בְּגַוָוהּ, לְמֶעְבַּד מָדוֹרָא בִּישָׁא. דִּכְתִּיב וַתַּהַר ותֵּלֶד אֶת קַיִן. קִינָּא דְּמָדּוֹרָא דְּרוּחִין בִּישִׁין וְעִלְעוּלִין וְקַטְפוּרִין.","אַתְקִין בֵּיהּ בְּהַאי אָדָם, כְּתָּרִים, בִּכְלַל וּפְרַט, אִתְכְּלָלוּ בִּפְרַט וּכְלָל, שׁוֹקִין וּדְרוֹעִין, יְמִינָא וּשְׂמָאלָא.","דָּא אִתְפְּלַג בְּסִטְרוֹי אִתְתַּקַּן דְּכַר וְנוּקְבָּא יה\"ו. י' דְּכַר. ה' נוּקְבָּא. ו' כְּתִיב זָכָר וּנְקֵבָה בְּרָאָם ויְבָרֶךְ אוֹתָם ויִּקְרָא שְׁמָם אָדָם. דִּיּוּקְנָא וּפַרְצוּפָא דְּאָדָם יָתִיב עַל כֻּרְסְיָּא, וּכְתִיב (יחזקאל א׳:כ״ו) ועַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה.","\u0003פִּרְקָא רְבִיעָאָה.\u0004 עַתִּיקָא, טָמִיר וסָתִים. זְעֵירָא דְּאַנְפִּין, אִתְגַּלְיָיא ולָא אִתְגַּלְיָיא. דְּאִתְגַּלְיָיא, בְּאַתְוָון כְּתִיב. דְּאְתְכַּסְיָיא, סָתִים בְּאַתְוָון, דְּלָא מִתְיַישְּׁבָן בְּאַתְרוֹי, בְּגִין דְּאִיהוּ לָא אִתְיְישָׁבוּ בֵּיהּ עִלָּאִין וְתַתָּאִין.","וַיֹּאמֶר אֱלהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ בְּהֵמָה וָרֶמֶשׂ וְגוֹ', הַיְינוּ דִּכְתִּיב, (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. חַד בִּכְלָלָא דְּאַחֲרָא מִשְׁתַּכְּחָא. בְּהֵמָה בִּכְלָלָא דְּאָדָם, (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַיְיָ' מִן הַבְּהֵמָה, מִשּׁוּם דְּאִתְכְּלַל בִּכְלָלָא דְּאָדָם.","כַּד נָחַת אָדָם דִּלְתַתָּא בְּדִיּוּקְנָא עִלָּאָה, אִשְׁתְּכָחוּ תְּרֵין (תזריע מ\"ח ע\"ב) רוּחִין מִתְּרִין סִטְרִין, דִּימִינָא וּשְׂמָאלָא כָּלִיל אָדָם. דִּימִינָא, נִשְׁמְתָא קַדִּישָׁא. דִּשְׂמָאלָא נֶפֶשׁ חַיָּה. חָב אָדָם אִתְפָּשָׁט שְׂמָאלָא, וְאִתְפָּשָׁטוּ אִינּוּן בְּלָא גּוּפָא.","כַּד מִתְדַּבְּקִין דָּא בְּדָא, אִתְיַּילְדָן כְּהַאי חַיָּה דְּאוֹלִידַת (רוחין) סַגִּיאִין בְּקִטְרָא חֲדָא. כ\"ב אַתְוָון סְתִימִין, כ\"ב אַתְוָון אִתְגַּלְּיָין, י' סָתִים, י' גַּלְיָיא. סָתִים וְגַלְיָיא, בְּמַתְקְלָא דְּטַפְסִין, אַתְּקָלוּ.","י' נָפְקִין מִנֵּיהּ דְּכַר וְנוּקְבָּא ו\"ד, בְּהַאי אֲתָר, ו' דְּכַר, ד' נוּקְבָּא. בְּגִין דָּא, ד\"וּ תְּרֵין. ד\"וּ דְּכַר וְנוּקְבָּא. ד\"וּ תְּרֵין קַפְלִין. תְּרֵין י' בִּלְחוֹדוֹי דְּכַר. ה' נוּקְבָּא. ה' ד' הֲוַת בְּקַדְמִיתָא, (ק\"פ ע\"ב) וּמִדְּאִתְעַבְּרַת בְּו' בְּגַוָּהּ, (אולידת) אַפִּיקַת ו', (הרי כי בה' אית ד\"ו וביה אית ה\"ה הרי יה\"ו) אִתְחָזֵי יוֹ\"ד בְּחֶזְוֵיהּ כְּלָלָא דיה\"ו. מִדְּאַפִּיקַת יוֹ\"ד דְּהוּא דְּכַר וְנוּקְבָּא, אִתְיַישְּׁבַת לְבָתַר, וּמְכַסְיָיא לְאִמָא.","(בראשית ו׳:ב׳) וַיִּרְאוּ בְּנִי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם, הַיְינוּ דִּכְתִּיב, (יהושע ב׳:א׳) שְׁנַיִם אֲנָשִׁים מְרַגְּלִים חֶרֶשׁ לֵאמֹר, מַאי בְּנוֹת הָאָדָם. דִּכְתִּיב, (מלכים א ג׳:ט״ז) אָז תָּבֹאנָה שְׁתַּיִם נָשִׁים זוֹנוֹת אֶל הַמֶּלֶךְ. בְּגִינֵיהוֹן כְּתִיב, כִּי רְאוּ כִּי חָכְמַת אֱלהִים בְּקִרְבּוֹ וְגוֹ'. אָז תָּבֹאנָה וְלָא בְּקַדְמִיתָא. בְּקִיסְטְרָא דְּקִיטוּרֵי דְּפִיגָאן, תְּרֵין מִתְחַבְּקָן הֲווֹ לְעֵילָּא, לְתַתָּא נָחְתוּ יַרְתּוּ עַפְרָא, אִבֵּדוּ חוּלָקָא טָבָא דְּהֲוָה בְּהוּ. עָטָרָא דְבוּמְלָא (ס\"א דחמלא') וְאִתְעַטָּר בְּקוּסְטָא דְּעִנְבָא.","(שמות י״ד:ט״ו) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. אֵלָי דַּיְיקָא. דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִּסָּעוּ. וְיִּסָּעוּ דַּיְיקָא.","בְּמַזָּלָא הֲוָה תָּלֵי, דְּבָעָא לְאוֹקִיר דִּקְנֵיהּ. (שמות ט״ו:כ״ו) וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה וְהַאֲזַנְתָּ לְמִצְוֹתָיו וְשָׁמַרְתָּ כָּל חֻקָּיו עַד כָּאן. כִּי אֲנִי יְיָ' רֹפְאֶיךָ, לְהַאי דַּוקָא.","\u0003פִּרְקָא חֲמִישָׁאָה.\u0004 (ישעיהו א׳:ד׳) הוֹי גּוֹי חוֹטֵא עַם כֶּבֶד עָוֹן זֶרַע מְרֵעִים בָּנִים וְגוֹ'. שִׁבְעָה דַּרְגִּין יוֹ\"ד ה\"ה ו\"ה ה\"י ו\"ו אַפִּיק ד' ה\"ה הו\"י, ה\"ה אַפִּיק ו\"ו ד\"ו לְבַר אַסְתִּיר אָדָם דְּכַר וְנוּקְבָּא דְּאִינּוּן ד\"ו דִּכְתִּיב בָּנִים מַשְׁחִיתִים.","בְּרֵאשִׁית בָּרָא. בְּרֵאשִׁית מַאֲמָר. בָּרָא חֲצִי מַאֲמָר. אָב וּבֵן. סָתִים וְגַלְיָא. עֵדֶן עִלָּאָה דְּסָתִים וְגָנִיז. עֵדֶן תַּתָּאָה, נָפִיק לִמְטָלְטְלֵי (ס\"א למטלנוי) וְאִתְגַּלְיָא יְהוָֹה. יָהּ. אֱלֹהִים. אֵת. אֲדֹנָי אֶהְיֶה. יְמִינָא וּשְׂמָאלָא כַּחֲדָא אִשְׁתָּתָפוּ, הַשָּׁמַיִם. ואֵת, דִּכְתִּיב, (דבה הימים א כט) וְהַתִּפְאֶרֶת וְהַנֵּצַח אִינּוּן כַּחֲדָא אִשְׁתָּתָפוּ. הָאָרֶץ, דִּכְתִּיב, (תהילים ח׳:ב׳) מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ. (ישעיהו ו׳:ג׳) מְלא כָל הָאָרֶץ כְּבוֹדוֹ.","יְהִי רָקִיעַ בְּתוֹךְ הַמַּיִם לְהַבְדִּיל בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקֳּדָשִׁים, עַתִּיקָא לִזְעֵירָא, אִתְפְּרַשׁ, וְאִתְדְּבַק. לָא אִתְפְּרַשׁ מַמָּשׁ פּוּמָא מְמַלֵּל רַבְרְבָן.","אַנְתִּיק וְאִתְעַטָּר בְּכִתְרִין זְעִירִין, בַּחֲמִשָּׁה זִינִין מַיִם, וּכְתִיב (במדבר י״ט:י״ז) וְנָתַן עָלָיו מַיִם חַיִּים. (ירמיהו י׳:י׳) הוּא אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם. (תהילים קט״ז:ט׳) אֶתְהַלֵּךְ לִפְנֵי יְיָ' בְּאַרְצוֹת הַחַיִּים. (שמואל א כ״ה:כ״ט) וְהָיְתָה נֶפֶשׁ אֲדֹנִי צְרוּרָה וְגוֹ'. וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן. י\"ה, יו\"ד ה\"א, אהי\"י בֵּין מַיִם לָמָּיִם. מַיִם שְׁלֵימִין, וּמַיִם דְּלָא שְׁלִימִין. רַחֲמִין שְׁלִימִין, רַחֲמִין דְּלָא שְׁלֵימִין.","(בראשית ו׳:ג׳) וַיֹּאמֶר יְיָ' לָא יָדוֹן רוּחִי בָאָדָם לְעוֹלָם בְּשַׁגַּם הוּא בָשָׂר. וַיֹּאמֶר יְיָ', כַּד אִתְיַישְׁבָא בִּזְעֵירָא. מִכָּאן (נ\"א דכד אמר בשם אמרו) (לומר) דָּבָר. דְּעַתִּיקָא סָתִים קָאָמַר לָא יָדוֹן רוּחִי בָאָדָם דִּלְעֵילָּא, מִשּׁוּם דִּבְהַהוּא רוּחָא דְּאִתְנָשְׁבָא מִתְּרֵין נוּקְבִין דְּפַרְדַּשְׂקָא, מָשִׁיךְ לְתַתָּאֵי.","וּבְגִין כָּךְ כְּתִיב (ימי עולם) וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה. יוֹ\"ד שְׁלִים וְלָא שְׁלִים. י' בִּלְחוֹדוֹי מֵאָה. תְּרֵין אַתְוָון תְּרֵין זִמְנִין, מֵאָה וְעֶשְׂרִים שָׁנָה. י' בִּלְחוֹדוֹי כַּד אִתְגַּלְיָא בִּזְעֵירָא, אִתְמְשָׁךְ בְּעֶשֶׂר אַלְפִין שְׁנִין. מִכָּאן כְּתִיב, (תהילים קל״ט:ה׳) וַתָּשֶׁת עָלַי כַּפֶּכָה."],[[0,"מאי ובוזי יקלו","וכו': מהו ובוזי יקלו, זה הוא מי שאינו יודע ליחד את השם הקדוש, ולקשר קשר האמונה, ולהמשיך למקום שצריך, ולכבד שם אדונו, טוב לא שלא נברא. וכל שכן, מי שאינו מכוון באמן, וע\"כ כל מי שמרחיש בשפתיו בנקיון הלב, במים המנקים, מה כתוב עליו, ויאמר אלקים נעשה אדם, כלומר, בשביל אדם היודע ליחד צלם ודמות, שהם ז\"א המכונה צלם והנוקבא המכונה דמות, כראוי, וירדו בדגת הים. (ע\"כ נוסח אחר)."],[1,"ויאמר אלקים נעשה אדם:","האדם לא כתוב שהיה משמעו על אדם הראשון בלבד, אלא אדם סתם, היינו להוציא ולהשלים גם אדם של מעלה, שהם זו\"ן הנקראים אדם, שנעשה עתה בשם שלם הויה אלקים, כי כאשר נשלם זה, נשלם זה, דהיינו כשנשלם אדם התחתון נשלם אדם העליון, שנשלם בדכר ונוקבא להשלים את הכל, הויה נקרא בחינת הזכר, שהוא ז\"א, אלקים נקרא בחינת הנקבה, שהיא מלכות. באפן שהשם הויה אלקים, הוא שם מלא. נתפשט הדכר, שהוא ז\"א, ונתקן בתקוניו כאמא, בפי האמה, דהיינו בעטרת יסוד, ששם מתגלים החסדים דאמא, להיותו קו האמצעי דנו\"ה. המלכים שנתבטלו דהיינו ז' מלכים דנקודים (כנ\"ל אות ג') נתקימו כאן, ע\"י יסוד דז\"א, שהוא קו אמצעי. (כנ\"ל אות י\"א)."],[2,"דינין דדכורא תקיפין","וכו': הזכר שה\"ס קו ימין שעקרו חסדים, ע\"כ הדינים של הזכר חזקים בראש, בג\"ר מפני שאין החכמה מתגלה שם. ונוחים בסוף, בנה\"י שלו, ששם מקום גילוי החסדים בחכמה. ושל הנוקבא הוא בהיפך, כי להיותה קו שמאל, בבחינת חכמה בלי חסדים, שהוא חשך ואינו מאיר, נמצא שבראשה, שאין גילוי חכמה, אין הדינין דשמאל קשים כל כך, אבל בנה\"י שלה ששם מקום גילוי החכמה שהוא קו שמאל, הם דינים חזקים. וי\"ה דינים קשים של עשן שקועים בחיקה. דהיינו בנה\"י של הנוקבא. שיש בהם ג\"פ ה' גבורות, ה' גבורות בנצח וה' גבורות בהוד, וה' גבורות ביסוד, שה\"ס י\"ה גבורות. \u0003י'\u0004 קטנה נמצאת בתוכה. שה\"ס חכמה תתאה, הנקראת \u0003י'\u0004 ולהיותה במלכות היא קטנה."],[2,"קונטירין","פירוש, דינים קשים, או קליפות קשות, מלשון קטרונים, שפירושו אגוזים שקליפתם קשה. \u0003קיטורא,\u0004 פירושו עשן, מלשון כקיטור הכבשן, (וירא י\"ט) \u0003בעטפוי,\u0004 פירושו בחיקו. כי תרגום בחיקך, בעטפך, (שמות ד' ו')."],[3,"אי אתבסמו דינין","וכו': רצה עתיקא לראות אם נתבסמו דינים דנוקבא, נתדבקו אדם ואשתו זה בזה, (כמ\"ש באדרת נשא קמב: ד\"י) ובא הנחש על חוה בפתוי של עץ הדעת (עי' ב\"א אות תנ\"ה) וקן של זוהמא נתתקן בתוכה, בנוקבא, ונעשה מדור הרע, שכתוב, ותהר ותלד את קין, שפירושו, קן ומדור של רוחות רעות וסערות ומזיקין. \u0003עלעולין,\u0004 פירושו סערות. כי על יקם סערה תרגום יקום עלעולא (תהלים ק\"ז) \u0003קטפורין\u0004 פירושו מזיקים המכים, מלשון, קטיף מן הדין גיסא (קה\"ר על הפסוק לב חכם) שפירושו הכאה."],[4,"אתקין ביה בהאי","וכו': התקין באדם הזה כתרים, בכלל ופרט. ונכללו בפרט וכלל, דהיינו השוקים והזרועות, שהם ימין ושמאל. דהיינו, כלל ופרט בזרועות, פרט וכלל בשוקים."],[4,"","פירוש. קו האמצעי ה\"ס כלל, כי כולל ב' הצדדים, ימין ושמאל, בתוכו, שהם חכמה וחסדים, והוא גוף האדם שהוא ת\"ת הכולל חסד וגבורה. וב' הזרועות הם פרט, וכן בשוקים היסוד הוא כלל, ושוקים פרט. כי בימין הוא חסדים לבדם ובשמאל הארת חכמה לבדה. וכלל ופרט, פירושו שהכלל שולט על הפרט, ופרט וכלל פירושו שהפרט שולט על הכלל. ובזרועות שולט הכלל שהוא קו האמצעי על הפרט, וע\"כ החכמה מכוסה שם, ובשוקיים שולט הפרט על הכלל וע\"כ החכמה מתגלית שם."],[5,"דא אתפלג בסטרוי","וכו': כשקו האמצעי מתחלק בצדדיו, דהיינו לצד ימין ולצד שמאל, מתתקן דכר ונוקבא בסוד \u0003יה\"ו\u0004 ש \u0003י'\u0004 שהוא צד ימין היא דכר. וה \u0003ה'\u0004 שהיא צד שמאל, היא נוקבא. ה \u0003ו'\u0004 בה כתוב, זכר ונקבה בראם ויברך אותם ויקרא שמם אדם. שהצורה והפרצוף של אדם, הוא יושב על הכסא, שהוא הנוקבא. שכתוב, ועל דמות הכסא דמות כמראה אדם עליו מלמעלה. נמצא שה \u0003ו'\u0004 כולל זכר ונקבה ביחד, בסוד אדם היושב על הכסא."],[6,"פרקא רביעאה, עתיקא","וכו': פרק רביעי. עתיקא, שהוא הכתר, מכוסה וסתום זעיר אנפין, מגולה ואינו מגולה, כלומר, שבו מתחיל ההתגלות וההתגלות הוא במלכות. המגולה, שהוא ז\"א, כתוב באותיות, דהיינו שמפורש באותיות השם, שנקרא \u0003הויה,\u0004 שפירושו היה הוה ויהיה, שהכל מתגלה בו. המכוסה, שהוא עתיקא, סתום באותיות שהוא מכונה \u0003אהיה,\u0004 שהוא לשון עתיד, שפירושו שאינו מתישב במקומו, אלא במקום אחר. משום שהוא, לא נתישבו בו עליונים ותחתונים, שאפילו העליונים אינם משיגים אותו."],[7,"ויאמר אלקים","וגו': ויאמר אלקים תוצא הארץ נפש חיה למינה בהמה ורמש וגו'. היינו שכתוב אדם ובהמה תושיע ה'. אחד בכלל האחר נמצא, דהיינו הבהמה בכלל האדם, כמ\"ש אדם כי יקריב מכם קרבן לה' מן הבהמה וגו'. שהוא מועיל לו, משום שהבהמה נכללה בסוד אדם. (וביאור דברים אלו הוא לעיל בראשית א' דף קי\"ד ד\"ה ביאור)."],[8,"כד נחת אדם","וכו': כשירד אדם שלמטה בצורה העליונה, דהיינו בצלם ודמות, נמצאו ב' רוחות משני צדדים שלו כי האדם כולל ימין ושמאל. של ימין, היא הנשמה הקדושה, של שמאל, היא נפש חיה. פירוש. האדם ה\"ס קו האמצעי המיחד ימין ושמאל שאז הארת הימין מתפשטת ממעלה למטה, והארת השמאל רק ממטה למעלה (כנ\"ל בראשית א' דף ס' ד\"ה מחלוקת) והממעלה למטה נבחן לג\"ר שהיא \u0003נשמהִ\u0004 וממטה למעלה נבחן כו\"ק שהוא \u0003נפש חיה.\u0004 ונקראת חיה, משום שבה הארת החכמה, הנקראת אור החיה. \u0003חב אדם אתפשטִ\u0004 וכו': כשחטא האדם, נתפשט השמאל, ממעלה למטה, שזה היה חטא עצה\"ד, שמשך הארת השמאל, שהוא חכמה, ממעלה למטה. (כנ\"ל ב\"ב אות של\"א) ואז ונתפשטו אלו שהם בלי גוף. דהיינו שנגלה כח המלכות דמדת הדין, בסוד לא זכי הוא רע, שממנה נמשכים רוחות בלא גוף, (כנ\"ל בהקסה\"ז דף קצ\"א ד\"ה וכי). ע\"ש."],[9,"כד מתדבקן דא בדא","וכו': מסיים כאן לפרש המאמר דלעיל, שאומר שז\"א נגלה ואינו נגלה. ומפרש, כשנתדבקו הימין והשמאל דבינה, זה בזה, נולדו, כחיה הזו שמולידה הרבה בבת אחת, כ\"ב אותיות סתומות, שהם כללות האורות דז\"א, שה\"ס ימין. וכ\"ב אותיות מתגלות, שהם כללות האורות דנוקבא דז\"א, שהם סוד, ב' יודין שבראש וסוף של \u0003יאהדונהי,\u0004 שהוא צירוף הויה אדנ\"י שהם זו\"ן, אשר \u0003י'\u0004 שבראש שהיא יוד דהויה שהוא ז\"א, היא סתומה, שאין הארת החכמה מתגלה בה וה \u0003י'\u0004 שבסוף שהיא של אדני, היא מתגלית, שהארת חכמה מתגלה בה. סתום וגלוי, שהם ימין ושמאל, נשקלו במאזנים המטפסים, כלומר שכפות המאזנים מטפסים ועולים מטפסים ויורדים. שה\"ס קו האמצעי המשוה ב' האורות ימין ושמאל שישקלו בשוה, ונתיחדו זב\"ז. פירוש. לפיכך אפשר לומר שהחכמה נגלית ע\"י ז\"א שהוא קו האמצעי, ואפשר לומר שלא נגלה בו, להיותו בחינת כ\"ב אותיות הסתומות. אמנם בו התחיל הגילוי בסוד קו האמצעי והגילוי עצמו הוא במלכות. שה\"ס כ\"ב אותיות הנגלות. וע\"כ אומר עליו, \u0003אתגליא ולא אתגליא.\u0004"],[10,"י' נפקין מניה","וכו': \u0003יו\"ד\u0004 יוצאים ממנה דכר ונוקבא, שהם ו\"ד דמילוי יוד. במקום זה, ה \u0003ו'\u0004 הוא זכר וה \u0003ד'\u0004 היא נוקבא, ולא ו\"ה כבשאר המקומות. משום זה ד\"ו פירושו שנים, כי ד\"ו הם דכר ונוקבא. ד\"ו, הם ב' כתרים שווים, דהיינו השעה שקומתם של דכר ונוקבא שוות זו לזו, שז\"א מלביש לקו ימין של הבינה, שהיא חסדים, והנוקבא לקו שמאל של הבינה, שהיא חכמה בלי חסדים, שאין החכמה שבה יכולה להאיר בלי חסדים, ואז היא דלה ועניה, וע\"כ היא אז בצורת \u0003ד'. י'\u0004 בפני עצמה היא דכר, \u0003ה'\u0004 היא נוקבא, \u0003ה'\u0004 היתה \u0003ד'\u0004 מתחילה, דהיינו ה \u0003ד'\u0004 שבמילוי יוד, כנ\"ל, ומשנתעברה ב \u0003ו'\u0004 בתוכה, נעשתה \u0003ה'\u0004 דהיינו \u0003ו'\u0004 בתוך ה \u0003ד'.\u0004 ואח\"כ הוציאה והולידה ה \u0003ו',\u0004 שה\"ס יה\"ו שבשם. ונראה היוד בתוארה שהיא כלל יה\"ו. שמקודם היתה ה \u0003י'\u0004 כלולה מ \u0003ו\"ד,\u0004 ואח\"כ הד' נתעברה עם ה \u0003ו'\u0004 ונעשית \u0003ה'\u0004 ואח\"כ הולידה ה \u0003ו'\u0004 לחוץ. ומשהוציאה היוד, שהיא דכר ונוקבא, את ה\"ו, שהם אמא וז\"א, נתישבה ה \u0003ו'\u0004 אח\"כ, דהיינו שקבלה מוחין, ומכסית לאמא שהיא \u0003ה'.\u0004 (כנ\"ל אות י\"ג). \u0003קפלין,\u0004 פירושו כתרים, מלשון בסיס מלמטה וקפליס מלמעלה, שפירושו, כותרת. (ויקרא רבה ס\"ה)."],[11,"ויראו בני האלהים","וכו': ויראו בני האלהים את בנות האדם, היינו שכתוב, שנים אנשים מרגלי חרש לאמר. מהו, בנות האדם, שכתוב אז תבאנה שתים נשים זונות אל המלך. בשבילם כתוב, כי ראו כי חכמת אלקים בקרבו וגו'. \u0003אז תבאנה,\u0004 ולא מקודם לכן. בשליטת הצורה של פגה, דהיינו לאכול פירות מטרם גמר בישולם, היו שנים מתחבקים למעלה, כשירדו למטה ירשו עפר. אבדו חלק הטוב שהיה בהם מעטרת הרחמים, ונתעטרו במדה ענבים."],[11,"","פירוש. כי בני האלהים, מפרש (בהקסה\"ז אות קנ\"ז ובבראשית א' אות קע\"ט) שהם עוזא ועזאל שנפלו מקדושתם, ששורשם הוא מבחינת אחוריים דאו\"א הפנימים שהאירו בראש ז\"א דנקודים. שמכח אחורים האלו נתפשטו ז\"ת דנקודים ממעלה למטה, ומתו. ואח\"כ קבלו תקון וחזרו ונפלו בחטאו של אדם הראשון, והיו לב' קליפות. ומקצתם נתקנו ע\"י יהושע, שהם, סוד ב' מרגלי חרש. \u0003מרגלים,\u0004 נקראים להיות שורשם מאחורים דאו\"א שהם נה\"י המכונים רגלים. \u0003חרש,\u0004 הוא התקון שהשיגו ע\"י יהושע, שפירושו המשכת החכמה ממטה למעלה, באופן שלא ישמע למטה, שזהו תקון קו אמצעי שקבלו אז. ואז נתקנה ג\"כ רחב הזונה. אבל טרם המבול כתוב עליהם, ויראו בני האלהים את בנות האדם כי טבת הנה ויקחו להם נשים מכל אשר בחרו, דהיינו בלי שום גבול, והמשיכו החכמה ממעלה למטה כדרך הקליפות. וכן בנות האדם, הן בחינת אחורים של הנוקבא, שנפלו למטה ע\"י חטא דעצה\"ד, שע\"כ נקראו על שמו של אדם, דהיינו על חטאו, ואחת מהן, דהיינו הימנית קבלה תקון, בימי יהושע כנ\"ל ולא לגמרי שה\"ס רחב הזונה. שתיהן קבלו תקון בימי שלמה, בסוד ב' נשים זונות. ששתיהן היו בבחינות שמאל, אחת היתה ימין דשמאל שכבר קבלה תקון בימי יהושע, והשניה שמאל דשמאל. ולפיכך נעשתה מחלוקת ביניהן. כי אחר שמת בן של זונה השמאלית, מחמת שהחכמה היתה בלי חסדים, אז רצתה לעשוק את בן הזונה הימנית שהיה בו חסדים גם כן, מחמת תקונה בימי יהושע, ואמרה לה, לא כי בנך המת ובני החי, כי אמרה שחכמה שלה הנמשכת ממעלה למטה כדרך הקליפות הוא אור החיים, כי החכמה היא אור החיים, והכחישה שחוסר החסדים יזיק לו וימיתנו ע\"כ אמר שלמה גזרו את הילד, כי ידע שאי אפשר שזונה השמאלית תרצה לקבל מצד החסדים של הילד הנמשך מקו אמצעי הממעט ג\"ר דחכמה, ולפיכך צריכים לגזור הילד לשנים, שצד החסדים תקח הימנית וצד החכמה השמאלית. וע\"כ תכף הודתה הזונה השמאלית, כי אין לה חפץ בחסדים שאינה חפצה להתמעט לו\"ק דחכמה, וגם לי וגם לך לא יהיה, גזרו. ואע\"פ שזונה הימנית אמרה, תקח לה וגו', לא רצתה לקבל. אז נברר לכל שהימנית המתוקנת היא אמו, והשמאלית אינה ראויה לעשות פירות עד שתכנע לקו אמצעי דקדושה כמו הימנית. ובזה קבלה תקונה ממנו, וע\"כ נאמר, כי ראו כי חכמת אלקים בקרבו, דהיינו שתקן הקליפות והוציא מהם הארת החכמה, וחברה לקדושה."],[11,"","וזה אמרו, \u0003ויראו בני האלהים את בנות האדם,\u0004 שהם עוזא ועזאל, שזנו עם בנות ה \u0003אדם\u0004 להמשיך החכמה ממעלה למטה, שע\"כ נקראו על שם אדם, דהיינו על חטאו, \u0003היינו דכתיב שנים אנשים מרגלים חרש לאמר,\u0004 שקבלו תקונם ע\"י יהושע בסוד \u0003חרש,\u0004 שפירושו להמשיך החכמה רק ממטה למעלה, ולא ישמע למטה. ושואל, \u0003מאי בנות האדם,\u0004 מה נעשה מהן, ומשיב, \u0003דכתיב אז תבאנה שתים נשים זונות אל המלך,\u0004 שנתברר תקונם בסו\"ה, גזרו את הילד כנ\"ל, בגיניהון כתיב, כי ראו \u0003כי חכמת אלקים בקרבו\u0004 וגו' שע\"י בירור הזה, הוציא החכמה מהקליפה וחברה לקדושה. \u0003אז תבאנה,\u0004 ולא מקודם לכן, כי לא היו ראוים לתקון מקודם לכן, לא בימי יהושע ולא לפני המבול."],[11,"","והוקשה לו, כיון שעוזא ועזאל היו מלאכים קדושים, למה טעו להתחבר עם בנות האדם. דהיינו להמשיך החכמה ממעלה למטה כדרך הקליפות. וע\"ז אומר, \u0003בקיסטרא דקיטורי דפיגאן,\u0004 בשליטת הצורה של פגה, שהיה אז שליטה לאכול פירות לפני גמר בישולו, דהיינו החטא דאדם הראשון, שאמרו ז\"ל שאכלו פגה, שפירושו שהיה לו להמתין עד גמר התקון, שאז לא היה נכשל בהמשכת החכמה ממעלה למטה, והנחש הטעה אותו בזה ודימה לו שאפשר להמשיך גמר התקון תיכף, ועד\"ז גם עוזא ועזאל טעו בשליטת כח של פגה הזה, וז\"ש, \u0003תרין מתחבקן הוו לעילא\u0004 שעוזא ועזאל היו מיוחדים זב\"ז למעלה, כי היו מלאכים קדושים, וע\"כ קוראם הכתוב בני האלהים, \u0003לתתא נחתו ירתו עפרא,\u0004 כיון שירדו למטה לעולם העשיה, והמשיכו החכמה של מעלה למטה, אז ירשו עפר, כמו הנחש שנאמר לו, ועפר תאכל כל ימי חייך, \u0003אבדו\u0004 וכו', \u0003דהוה בהו עטרא דחמלא,\u0004 שהיה בהם עטרת הרחמים, שהוא בחינת קו אמצעי, הכולל חכמה וחסדים יחדיו, \u0003ואתעטר בקוסטא דענבא,\u0004 ונתעטרו במדת ענבים, שהוא קו שמאל בלי ימין, שהוא בחינת עצה\"ד, שאמרו ז\"ל שענבים היה."],[11,"","קיסטרא פירושו שליטה, מלשון קסטרס, שפירושו שליט, כמ\"ש (בדברים רבה פ\"א). מהו נציבים ר' סימון אמר קסטרס. דהיינו שליט ומגן. קיטורי פירושו צורות, מלשון קטורין של אביו, (ילמדנו תולדות) \u0003דפיגאן,\u0004 מלשון פגה, שפירושו דבר מטרם גמר בישולו, כמ\"ש (סנהדרין כ' ע\"א) שאכלה פגה."],[12,"ויאמר ה' אל משה","וגו': ויאמר ה' אל משה מה תצעק אלי, \u0003אלי,\u0004 הוא בדיוק, דבר אל בני ישראל ויסעו, \u0003ויסעו,\u0004 הוא בדיוק. במזל היה הדבר תלוי, שרצה להוקיר את הדיקנא, והישר בעיניו תעשה והאזנת למצותיו ושמרת כל חקיו, עד כאן. כי אני ה' רפאיך, לזה דוקא."],[12,"","פירוש. כדי לבקוע הים להציל את ישראל ולהטביע המצרים, היו צריכים לגלות אור החכמה בסוד ע\"ב שמות, שה\"ס ג' קוין המרומזים בג' פסוקים ויסע ויבא ויט, (כנ\"ל בשלח אות קע\"ג) וז\"ש \u0003מה תצעק אלי,\u0004 אלי, הוא בדיוק, דהיינו לבחינת ז\"א, כי היו צריכים להמשיך הארת החכמה הגדולה שבע\"ב שמות, הנמשך מי\"ג תקוני דיקנא, וז\"ש \u0003דבר אל בני ישראל ויסעו, ויסעו,\u0004 הוא בדיוק. כי אין החכמה מתגלית ע\"י ג' הקוין, אלא בדרך נסיעה על תלת דוכתי, (כמ\"ש לעיל בשלח ל\"ט ד\"ה וג' ע\"ש)."],[13,"במזלא הוי תלי דבעא לאוקיר דיקניה,","כי אז נמשך הארת החכמה ממזל העליון שה\"ס תקון השמיני מי\"ג תקוני דיקנא המכונה מזל. וז\"ש \u0003הישר בעיניו תעשה,\u0004 היינו קו שמאל, שבו נמשך החכמה המכונה עיניו. \u0003והאזנת למצותיו,\u0004 היינו קו ימין, שבו נמשכים החסדים מבינה, המכונה אזנים, וע\"כ נאמר והאזנת. \u0003ושמרת כל חוקיו,\u0004 היינו קו האמצעי, שהוא שומר החוקים, שהימין תמשך ממעלה למטה, והשמאל רק ממטה למעלה, \u0003עד כאן,\u0004 כלומר עד כאן צריכים להמשיך וליחד את ג' הקוים זב\"ז. \u0003כי אני ה' רפאיך, להאי דייקא,\u0004 שהרפואה שלי נמשכת ביחוד הזה, של ג' הקוין, דוקא."],[14,"פרקא חמשאה. הוי גוי","וכו': פרק חמשי. כתוב, הוי גוי חוטא עם כבד עון זרע מרעים בנים משחיתים וגו'. שבע מדרגות הן, שזו יצאה מזו: \u0003יו\"ד ה' ו' ה' ה'.\u0004 ומפרש, \u0003י'\u0004 הוציאה \u0003ו\"ד\u0004 במילוי יו\"ד וה \u0003ד'\u0004 נתעברה עם הו' ונעשתה \u0003ה'.\u0004 שאז נעשית ה \u0003י' הו\"י\u0004 (כנ\"ל אות נ\"ג) והן ד' מדרגות \u0003י' ו' ד' ה',\u0004 ואח\"כ \u0003ה'\u0004 הולידה ה \u0003ו'\u0004 שהיא מדרגה החמשית, וה \u0003ו'\u0004 שהוא ז\"א הוציאה \u0003ה'\u0004 מבפנים באצילות שהיא הנוקבא והיא מדרגה \u0003ו'.\u0004 ו \u0003ד\"ו\u0004 שהם נשמות אדם וחוה, הוציאה לחוץ מאצילות שהם מדרגה \u0003ז'\u0004 והסתיר דכר ונוקבא דאדם, שהם \u0003ד' ו',\u0004 מחוץ לאצילות, כלומר, שהסתיר פניו מהם, שכתוב עליהם, בנים משחיתים, כי חטאו בעץ הדעת."],[15,"בראשית ברא","וכו': בראשית, מאמר, דהיינו מדרגה שלמה, \u0003ברא,\u0004 חצי מאמר, דהיינו חצי מדרגה, כי \u0003בראשית\u0004 ה\"ס חכמה סתימאה דא\"א, ו \u0003ברא,\u0004 ה\"ס חצי המדרגה שהיא בינה ותו\"מ שיצאה לחוץ. מחכמה סתימאה, למדרגה שמתחתיה ונזרע בה ג' זריעות דחולם שורק חירק, (כנ\"ל ב\"א דף י\"ח ד\"ה וזה) והם אב ובן, כלומר שמחמת היציאה נעשו, חכמה סתימאה ובינה לב' מדרגות היוצאות זו מזו בבחינת אב ובן. שחכמה סתימאה היא אב ובינה היא בן. סתים וגליא, חכמה סתימאה היא סתום, והבינה היא גלויה. חכמה סתימאה היא עדן העליון הסתום והגנוז, והבינה היא עדן התחתון היוצא לנסיעותיו, בג' מקומות בסוד חלם חירק שורק, ומתגלה \u0003הוי\"ה י\"ה,\u0004 דהיינו מאמר וחצי מאמר, מתגלים ע\"י הנסיעה \u0003אלקים את,\u0004 שכתוב אחר בראשית ברא, פירושו אדני אהיה. כי \u0003את\u0004 ה\"ס מלכות הנקראת אדני, ו \u0003אלקים\u0004 ה\"ס בינה אחר שחזרה לראש ונעשתה מדרגה שלמה נרנח\"י, בסוד ה' אותיות אלקים, שהיא נקראת אז אהיה. ימין ושמאל נשתתפו יחד. ה\"ס \u0003השמים\u0004 שהוא תפארת הכולל חסד וגבורה, שהם ימין ושמאל \u0003ואת\u0004 היא נה\"י, שכתוב והתפארת והנצח וגו'. שהם נשתתפו יחד. \u0003ששמים\u0004 הוא תפארת. \u0003ואת\u0004 היא והנצח וההוד. כי כל בשמים ובארץ, שהוא יסוד. ונה\"י אלו מכונים ז\"א הקטן שמחזה ולמטה. \u0003הארץ,\u0004 היא מלכות האחרונה, שכתוב, מה אדיר שמך בכל הארץ. מלא כל הארץ כבודו. אשר ארץ פירושו מלכות. ושיעור הכתוב הוא, \u0003בראשית\u0004 ה\"ס חכמה סתימאה. \u0003ברא\u0004 ה\"ס בינה שיצאה לחוץ מחכמה סתימאה, ונזרעה בג' זריעות חלם שורק חירק. \u0003אלקים,\u0004 ה\"ס בינה אחר שחזרה לחכמה ונשלמה בה' אורות נרנח\"י. \u0003את\u0004 ה\"ס הנוקבא הגדולה שמחזה ולמעלה דז\"א, \u0003השמים\u0004 ה\"ס ז\"א. \u0003ואת\u0004 ה\"ס נה\"י דז\"א הנק' ז\"א הקטן. \u0003והארץ\u0004 ה\"ס מלכות. וכעין זה, פירש הזהר את הכתוב בראשית ברא, לעיל (בראשית א' אות י' י\"א י\"ב ע\"ש בהסולם) והוא משונה ממה שפירש הספרא דצניעותא לעיל (באות ז')."],[16,"יהי רקיע בתוך המים:","הוא להבדיל בין הקדש, שהוא ז\"א, ובין קדש הקדשים, שהם א\"א ואו\"א. כי רקיע ה\"ס המסך דצמצום ב', העומד במקום החזה דא\"א שמשם ולמטה מתחיל ז\"א, ונמצא הרקיע מבדיל בין עתיק, שהוא א\"א, ובין זעיר אנפין. הוא נפרד מא\"א ע\"י הרקיע, ונתדבק, שהרי לא נפרד ממש בפה מדבר גדולות, שהוא הפה דא\"א ששם הדעת, שהוא הלשון, שה\"ס ז\"א שעלה לראש ומכריע שם בין חכמה לבינה ומיחדם יחד. (כנ\"ל משפטים אות תקכ\"ט וע\"ש בהסולם) הרי שאע\"פ שז\"א נפרד מא\"א על ידי המסך דחזה שלו שנקרא רקיע מ\"מ חזר ועלה ונתדבק בראש בסוד הדעת."],[17,"אנתיק ואתעטר בכתרין","וכו': נותק, ז\"א מן הג\"ר, ונתעטר בכתרים קטנים, דהיינו בו\"ק דג\"ר, בחמשה מינים מים חיים, דהיינו בספירות חג\"ת נ\"ה דאמא שה\"ס חמש מאות שנה, המכונים מים חיים או חיים, שכתוב ונתן עליו מים חיים, שהוא חסד. הוא אלקים חיים ומלך עולם, שהוא גבורה. אתהלך לפני ה' בארצות החיים, שהוא נצח. והיתה נפש אדני צרורה בצרור החיים, שהוא הוד, ועץ החיים בתוך הגן, שהוא תפארת. \u0003י\"ה\u0004 שהוא חכמה ובינה, \u0003יוד הא,\u0004 שהוא חכמה בינה דז\"א עצמו שה\"ס הויה במילוי אלפין. \u0003אהיה,\u0004 שה\"ס כתר, (כמ\"ש בזהר ויקרא יא.) הם ההפרש \u0003בין מים למים,\u0004 שמים העליונים שלמעלה מרקיע, שהם י\"ה ויו\"ד ה\"א ואהיה, הם שלמים, והתחתונים שלמטה מרקיע הם מים בלתי שלמים, למעלה מרקיע הם רחמים שלמים, למטה מרקיע הם רחמים בלתי שלמים."],[18,"ויאמר ה' לא ידון","וגו': ויאמר ה' לא ידון רוחי באדם לעולם בשגם הוא בשר. \u0003ויאמר ה',\u0004 היינו כשנתישב ונתלבש בז\"א, מכאן דבר בשם אמרו, כי עתיקא הסתום, שהוא א\"א אמר לא ידון רוחי באדם העליון, ז\"א, משום שברוח ההוא הנושב מב' נוקבין שבחוטם דא\"א מושך החיים לתחתונים, שה\"ס אור החכמה הנקרא חיים. ולפיכך גם ז\"א אינו ממשיך חיים לאדם התחתון לעולם. אבל בעל המאמר הוא א\"א המדבר כלפי אדם העליון שהוא ז\"א, ואחר שא\"א נתלבש בז\"א בשיעור קטן הזה, הוא מדבר זה כלפי אדם התחתון."],[19,"ובג\"כ כתיב","וכו': ומשום זה כתוב, והיו ימיו מאה ועשרים שנה, כי \u0003יוד,\u0004 שה\"ס חכמה וחיים וכן בב' נקבי דפרדשקא יש ג\"כ אותיות יוד, כי הכותל בין ב' נוקבין הוא \u0003ו',\u0004 נקב הימני היא \u0003י',\u0004 ונקב השמאלי היא \u0003ד',\u0004 היא שלמה ואינה שלמה, שמצד עצמה בלי המילוי \u0003ו\"ד\u0004 היא שלמה בע\"ס, ומצד המילוי \u0003ו\"ד\u0004 שהן בחינת הנוקבא של ה \u0003י'\u0004 היא אינה שלמה. לפיכך, \u0003י'\u0004 בפני עצמה היא מאה, דהיינו עשר ספירות שכל אחת כלולה מעשר והן מאה. ב' האותיות \u0003ו\"ד\u0004 שאינן שלמות, הן ב' פעמים עשר שביחד הן \u0003מאה ועשרים שנה י'\u0004 בפני עצמה כשמתגלית בזעיר אנפין, היא מתפשטת לעשרת אלפים שנה, כי ספירות החכמה כל אחת מתפשטת לאלף. מכאן, כתוב, ותשת עלי כפכה. דהיינו שנתמעט קומתו למאה אמה, (כמ\"ש חגיגה יב.) מחמת שקבל אור החיים מן היוד שהיא שלמה ואינה שלמה. מחמת שה \u0003ו\"ד\u0004 שאינן שלמות הן מחוברות אל ה \u0003יוד\u0004 כנ\"ל."]],[]],[["(בראשית ו׳:ד׳) הַנְּפִילִים הָיוּ בָאָרֶץ, הַיְינוּ דִּכְתִּיב וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. מֵאֲתָר דְּאִתְפְּרַשׁ גִּנְתָּא, אִקְרֵי הַנְּפִילִים, דִּכְתִּיב וּמִשָּׁם יִפָּרֵד. הָיוּ בָאָרֶץ בַּיָּמִים הָהֵם, וְלָא לְבָתַר זִמְנָא. עַד דְּאָתָא יְהוֹשֻׁעַ, וּבְנֵי הָאֱלֹהִים אִסְטָמָרוּ.","עַד דְּאָתָא שְׁלמֹה וּבְנוֹת הָאָדָם אִתְכְּלָלָא, הֲדָא הוּא דִכְתִיב, (קהלת ב) וְתַעֲנוּגוֹת. תַּעֲנֻגֹת קָארֵי (תענוגים לא קארי) בְּנֵי הָאָדָם (נ\"א דאתרמיזו) דְּאִתְרְמִיוּ מֵהַאי רוּחִין אַחֲרָנִין, דְּלָא אִתְכְּלָלוּ בְּחָכְמָה עִלָּאָה. דִּכְתִּיב, (מלכים א ה׳:כ״ו) וַיְיָ' נָתַן חָכְמָה לִשְׁלֹמֹה. וּכְתִיב (מלכים א ה׳:י״א) וַיֶּחְכַּם מִכָּל הָאָדָם. מִשּׁוּם דְּהָנֵי לָא אִתְכָּלָלוּ בְּאָדָם.","וַיְיָ' נָתַן חָכְמָה, ה' עִלָּאָה. וַיֶּחְכַּם, דְּמִינָהּ אִתְחַכָּם לְתַתָּא. הֵמָּה הַגִּבּוֹרִים אֲשֶׁר מֵעוֹלָם, עוֹלָם דִּלְעֵילָּא. אַנְשֵׁי הַשֵּׁם, דְּאִתְנָהֲגָן בִּשְׁמָא. מַאי שְׁמָא. שְׁמָא קַדִּישָׁא, דְּאִתְנָהֲגָן בֵּיהּ דְּלָא קַדִּישִׁין לְתַתָּא, וְלָא אִתְנָהֲגָן אֶלָּא בִּשְׁמָא. אַנְשֵׁי הַשֵּׁם סְתָם, וְלָא אַנְשֵׁי הוי\"ה. לָאו מִסְתִּים סְתִימָא, אֶלָּא גְּרִיעוּתָא, וְלָא גְּרִיעוּתָא אַנְשֵׁי הַשֵּׁם סְתָם, מִכְּלָלָא דְּאָדָם נַפְקוּ, כְּתִיב (תהילים מ״ט:י״ג) אָדָם בִּיקָר בַּל יָלִין, אָדָם בִּיקָר, בְּיָקִרוּ דְּמַלְכָּא, בַּל יָלִין, בְּלָא רוּחָא.","תְּלֵיסַר מַלְכֵּי קְרָבָא, בְּשִׁבְעָה. שִׁבְעָה. מַלְכִּין בְּאַרְעָא, אִתְחֲזִיאוּ נָצְחֵי קְרָבָא. תִּשְׁעָה דְּסַלְּקִין בְּדַרְגִּין, דְּרַהֲטִין בִּרְעוּתְהוֹן, וְלֵית דְּיִמְחֵי בִּידֵיהוֹן. חֲמִשָּׁה מַלְכִּין קַיְימִין בִּבְהִילוּ, לְקַמֵּי אַרְבַּע לָא יַכְלִין לְמֵיקָם.","אַרְבַּע מַלְכִּין נָפְקִין לְקַדְמוּת אַרְבַּע, בְּהוֹן תַּלְיָין כַּעֲנָבִין בְּאִתְכְּלָא צְרִירָן בְּהוּ שִׁבְעָה רְהִיטִין. סָהֲדִין סָהֲדוּתָא וְלָא קַיְימִין בְּדוּכְתַּיְיהוּ. אִילָנָא דְּמִבְסָם יָתִיב בְּגוֹ. בַּעֲנָפוֹי אֲחִידָן וּמְקַנְנָן צִפֹּרִין. תְּחוֹתוֹי תַּטְלֵל חֵיוָתָא דִּשְׁלִיטָא בְּהַהוּא אִילָנָא בִּתְרֵי כְּבִישִׁין, לְמֵהַךְ בְּשִׁבְעָה סַמְכִין סָחֲרָנֵיהּ, בְּאַרְבַּע חֵיוָון, מִתְגַּלְגְּלִין בְּאַרְבַּע סִטְרִין.","חִוְיָא דְּרָהִיט בש\"ע דִּלּוּגִין, דָּלִיג עַל טוּרִין, מְקַפֵּץ עַל גִּבְעָתָא, דִּכְתִּיב, (שיר השירים ב׳:ח׳) מְדַלֵּג עַל הֶהָרִים מְקַפֵּץ עַל הַגְּבָעוֹת. זְנָבֵיהּ בְּפוּמֵיהּ, בְּשִׁנוֹי, נָקִיב בִּתְרֵין גִּיסִין. כַּד נָטִיל גִּיסְטְרָא אִתְעָבִיד לִתְלַת רוּחִין.","כְּתִיב וַיִּתְהַלֵּךְ חֲנוֹךְ אֶת הָאֱלֹהִים. וּכְתִיב (משלי כ״ב:ו׳) חֲנוֹךְ לַנַּעַר עַל פִּי דַּרְכּוֹ. לַנַּעַר הַיָּדוּעַ. אֶת הָאֱלֹהִים, וְלָא אֶת יְיָ'. וְאֵינֶנּוּ, בְּשֵׁם זֶה, כִּי לָקַח אוֹתוֹ אֱלֹהִים לְהִקָרֵא בִּשְׁמוֹ.","תְּלַת בָּתֵּי דִּינִין, אַרְבַּע אִינּוּן. אַרְבַּע בָּתֵּי דִּינִין דִּלְעֵילָּא. אַרְבַּע לְתַתָּא. דִּכְתִּיב, (ויקרא י״ט:ל״ה) לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט בַּמִּדָּה בַּמִּשְׁקָל וּבַמְּשׂוּרָה. דִּינָא קַשְׁיָא. דִּינָא דְּלָא קַשְׁיָא, דִּינָא בְּשִׁקּוּלָא, דִּינָא דְּלָא בְּשִׁקּוּלָא. דִּינָא רַפְיָא. (דינא) דְּאֲפִילּוּ לָא הַאי וְלָא הַאי.","וַיְהִי כִּי הֵחֵל הָאָדָם לָרֹב עַל פְּנֵי הָאֲדָמָה. הֵחֵל הָאָדָם לָרֹב. הַיְינוּ דִּכְתִּיב בְּשַׁגַּם וְגוֹ', הָאָדָם דִּלְעֵילָּא. וּכְתִיב עַל פְּנֵי הָאֲדָמָה. (שמות לה) וּמֹשֶׁה לָא יָדַע כִּי קָרַן עוֹר פָּנָיו, הַיְינוּ דִּכְתִּיב, (בראשית ג׳:כ״א) כָּתְנוֹת עוֹר.","קָרַן, דִּכְתִּיב, (שמואל א ט״ז:י״ג) וַיִּקַּח שְׁמוּאֵל אֶת קֶרֶן הַשֶּׁמֶן. לֵית מְשִׁיחָא אֶלָּא בְּקֶרֶן, (תהילים פ״ט:כ״ה) וּבְשִׁמְךָ תָּרוּם קַרְנִנוּ. (תהילים קל״ב:י״ז) שָׁם אַצְמִיחַ קֶרֶן לְדָוִד. הַיְינוּ עֲשִׂירָאָה דְּמַלְכָּא. וְאַתְיָא מִן יוֹבְלָא דְּהִיא אִימָא, דִּכְתִּיב, (יהושע ו׳:ה׳) וְהָיָה בִּמְשׁוֹךְ בְּקֶרֶן הַיּוֹבֵל. קֶרֶן בְּיוֹבְלָא אִתְעַטָּר עֲשִׂירָאָה בְּאִימָּא. קֶרֶן, דְּנָטִיל קֶרֶן וְרוּחַ לְאָתָבָא רוּחֵיהּ לֵיהּ.","וְהַאי קֶרֶן דְּיוֹבְלָא הוּא. וְיוֹבֵל ה'. וה' נְשִׁיבָא דְּרוּחָא לְכֹלָּא. וְכֹלָּא תַּיְיבִין לְאַתְרַיְיהוּ, דִּכְתִּיב, (ירמיה א) אֲהָהּ יְיָ' אֱלֹהִים, כַּד אִתְחָזֵי ה' לה', יְיָ' אֱלהִים אִתְקְרֵי שֵׁם מָלֵּא וּכְתִיב (ישעיהו ב׳:י״א) וְנִשְׂגַּב יְיָ' לְבַדּוֹ בַּיּוֹם הַהוּא. (ס\"א כד אתחזר ה' לה' ואסתלק י' פורענותא אתי לעלמא ואי לאו בשביל אדם יהו\"ה לא אתקיים עלמא וכלא אתחרב ועל דא כתיב ונשגב וגו') עַל כֵּן סָתִים וְאִתְעַטַּר צְנִיעוּתָא דְּמַלְכָּא, דְּהַיְינוּ סִפְרָא דִּצְנִיעוּתָא. זַכָּאָה (נ\"א למאן דנפק וידע) לְמַאן דְּעָאל וְנָפַק וְיָדַע שְׁבִילוֹי וְאָרְחוֹי."],[[0,"הנפילים היו בארץ:","היינו שכתוב, ומשם יפרד והיה לארבעה ראשים, כי ממקום שנפרד הגן שהוא מלכות דאצילות, נקרא נפילים, דהיינו בכל ג' עולמות בי\"ע, שכל אלו שנפלו שמה ממדרגות של אצילות, המה \u0003נקראים נפילים\u0004 שכתוב, \u0003ומשם יפרד,\u0004 שמשם ולמטה יפרד מן אצילות, וע\"כ עוזא ועזאל ובנות האדם, שהיו ממדרגות אצילות ונפלו למטה ממלכות דאצילות, נקראים נפילים. היו בארץ בימים ההם, ולא לאח\"כ, עד שבא יהושע, ובני האלקים נצפנו, דהיינו ב' מרגלי חרש שנאמר עליהם ותצפנו."],[1,"עד דאתא שלמה","וכו': עד שבא שלמה, ובנות האדם נכללו בקדושה. כש\"א, \u0003ותענגות\u0004 בני אדם, תענגות קרא, לשון נקבה ולא תענוגים שהוא לשון זכר, משום שהם בנות האדם הנ\"ל, ב' נשים זונות, \u0003בני אדם,\u0004 כי נאמר ותענגות בני אדם, היינו בני האדם שנשלכו מרוחות אחרות שבאצילות, ולא נכללו בחכמה עלאה. שכתוב וה' נתן חכמה לשלמה. וכתוב ויחכם מכל האדם, הוא משום שתקן בני האדם הנ\"ל, שאלו לא נכללו באדם דקדושה."],[2,"והויה נתן חכמה:","היינו שנתן לו \u0003ה'\u0004 עליונה, שהיא בינה שחזרה להיות חכמה, ולא חכמה ממש, כי חכמה סתימאה נסתמה, ואינה מאירה. וכל החכמה המאירה היא רק מבינה שחזרה לחכמה. \u0003ויחכם,\u0004 כי ממנה, מן הבינה, נחכם למטה. \u0003המה הגבורים אשר\u0004 מעולם, היינו עולם העליון, עולם האצילות שמשם נפלו כנ\"ל. \u0003אנשי השם,\u0004 שמתנהגים בשם. מהו השם. הוא שם הקדוש, דהיינו מלכות הנקראת \u0003שם,\u0004 והתנהגו בו, שאינם קדושים, דהיינו הנפילים התנהגו בו להמשיך משם חכמה ממעלה \u0003למטה,\u0004 שהיא אינו קדוש, כי אסור לעשות כן. אבל ולא התנהגו אלא \u0003בשם,\u0004 שהיא מלכות. \u0003אנשי השם,\u0004 נאמר סתם, ולא נאמר אנשי הויה, שהוא ז\"א, ולא משום שסתום מסתים הכתוב, דהיינו שאינו רוצה לומר איזה שם, אלא הוא מיעוט ולא מיעוט. כלומר, שהיא מיעוט, מחמת שממעט משם הויה. ואינו מיעוט, מחמת שהוא המלכות, שנקראת כן, \u0003שם.\u0004 ולא היה יכול לכתוב בדרך אחר. \u0003אנשי השם\u0004 סתם, יצאו מכלל האדם, שכתוב אדם ביקר בל ילין. \u0003אדם ביקר\u0004 פירושו, ביקרו של המלך, שהיא מלכות הנקראת, שם, והיא יקרו של ז\"א. הרי שאדם היה מתנהג בשם, שהיא מלכות, \u0003בל ילין,\u0004 היינו בעת שהיה, בלי רוח."],[3,"תליסר מלכי קרבא","וכו': כאן חוזר על רוב העקרים שאמר בכל ה' פרקים ומעט הוספות, בדרך קצר מאד. ואומר, י\"ג מלכי מלחמה, היינו י\"ג תקוני דיקנא דא\"א (שבאות ט\"ו) בשבעה דהיינו שהי\"ג מקבלים מז' תקוני גלגלתא דא\"א (שבאות ו') שבעה מלכים, היינו ז' תקוני גלגלתא דז\"א (שבאות כ\"ו) כשהארתם מתפשטת בארץ, שהיא המלכות, הם נראו מנצחי מלחמה. שהארת החכמה שבז' תקוני גלגלתא שהיא מכנעת השונאים דהיינו הקליפות אינה מתגלה במקומם אלא במלכות (כנ\"ל אות ו') ובה נראה הנצחון על אויבי הקדושה. תשעה העולים במדרגות ורצים כרצונם, דהיינו ט' תקוני דיקנא דז\"א, שהם עולים ורצים במדרגות, דהיינו תחילה ו\"ק דנפש ואח\"כ ג\"ר דנפש ואח\"כ ו\"ק דרוח, ואח\"כ ג\"ר דרוח וכו' (כנ\"ל אות ל\"ה בהסולם) ואין מי שימחה בידם. חמשה מלכים עומדים בבהלה ולא יכלו לעמוד לפני ארבעה."],[3,"","פירוש. חמשה מלכים ה\"ס ה' אותיות אלקים. וד' מלכים הם ד' אותיות הוי\"ה. ונודע שבעת יציאת נקודת השורק באמא, עולים אתוון אל\"ה ומתחברים עם אתוון מ\"י שנשארו במדרגה, ונתחברו שוב ה' אותיות אלקים באמא. (כנ\"ל בראשית א' דף ט\"ו ד\"ה ההוא ע\"ש) והנה אז נעשה סתימה, שמחמת חסרון חסדים גם החכמה אינה מאירה, כמ\"ש שם, וז\"ש, \u0003חמשה מלכין קיימין בבהילו,\u0004 משום שאינם יכולים להאיר. ואז עולה ז\"א בסוד נקודת החירק וממעט השמאל שעי\"ז מיחד ימין ושמאל, שאז יוצאים ג' קוין באמא בסוד חכמה בינה ודעת, שה\"ס ד' אותיות הוי\"ה, כי ב' הקוין ימין ושמאל ה\"ס י\"ה, וז\"א שה\"ס קו אמצעי שיחד אותם ה\"ס ו\"ה, דהיינו חסדים וגבורות שבדעת. שהחסדים ה\"ס \u0003ו'\u0004 והגבורות ה\"ס \u0003ה',\u0004 וז\"ש \u0003לקמי ארבע לא יכלין למיקם,\u0004 שה' אותיות אלקים שבקו שמאל דבינה, לא יכלו לעמוד לפני ההכרעה שבקו האמצעי, שה\"ס ד' אותיות הויה, שמיעט את הקו שמאל מג\"ר דג\"ר, ויחד אותם בסוד ד' אותיות הויה, שה\"ס תקון חב\"ד. כמבואר."],[4,"ארבע מלכין","וכו': אחר שביאר שד' אותיות הויה נצחו ה' אותיות אלקים, כי נתקן תקון קוין בבינה בסוד חב\"ד, שהם ד' אותיות הויה. אומר, ארבע מלכים יוצאים ונולדים לקראת הארבעה מלכים. כלומר ד' מלכים שבז\"א שהם חגת\"ם, יוצאים ונאצלים מארבעה מלכים שבחב\"ד שבבינה. כי מתוך \u0003שתלת מחד נפקי הד בתלת קיימא,\u0004 (כנ\"ל ב\"א אות שס\"ג ע\"ש) \u0003בהון תליין כענבים באתכלא,\u0004 כי החגת\"ם שבז\"א הם תלוים בחב\"ד שבבינה כמו ענבים באשכול. מחמת שמהם יצאו, ומהם מתקיימים. \u0003נכללים בהם שבעה רצים,\u0004 שהם ז\"ס חג\"ת נהי\"מ שבמלכות הכוללת, אשר בעת שמתגלה בה החכמה הם רצים ונחפזים, בסו\"ה, והחיות רצוא ושוב (כנ\"ל אות י\"א ע\"ש), הם כלולים בד' מלכים חגת\"ם. \u0003סהדין סהדותא ולא קיימין בדוכתייהו,\u0004 מעידים עדות כשאינם נמצאים במקומם, כי בעת שהם מגלים הארת החכמה שנקראת עדות מוכרחים לרדת ממקומם. כי אין המלכות מקבלת חכמה אלא בשעה שהיא כלולה במלכות שלמעלה מחזה, שהיא בסוד רביעית לחג\"ת, וכלולה בהם. אבל שם אין החכמה מתגלה בה, מחמת שהיא מחוסרת חסדים, אלא אחר שיורדת משם למטה מחזה דז\"א, ונעשית בסוד שביעי, אז היא מעידה עדות, דהיינו שמתגלה בה החכמה. הרי שמעידה עדות רק שלא במקומה, ובמקומה אינה יכולה להעיד. \u0003אילנא דמבסם יתיב בגו,\u0004 האילן שמבשם, שהוא יסוד דז\"א, המשפיע חסדים למלכות והחכמה מתבשמת בחסדים, הוא יושב בהם, בשבעה ספירות המלכות הנ\"ל, \u0003בענפוי אחידן ומקננן צפרין,\u0004 בענפיו המתפשטים ממנו, שהם חסדים, נאחזים ומקננים צפרים, שהם מדרגות החכמה כנ\"ל המתלבשות בחסדים שלו. \u0003תחותוי תטלל חיותא דשליטא בההוא אילנא בתרי כבישין\u0004 תחת היסוד דז\"א, תחסה בצלו החיה, שהיא מלכות, השולטת באילן ההוא שיש בו ב' דרכים, שהוא עץ הדעת טוב ורע, שאם זכה הוא טוב לא זכה הוא רע (כנ\"ל בהקסה\"ז אות קכ\"ג). \u0003למחך בשבעה סמכין סחרניה, בד' חיון מתגלגלין בארבע סטרין,\u0004 ואם זכה, שולט הטוב, ואז הולך בז' עמודים שהם חג\"ת נהי\"מ של הנוקבא, שה\"ס הארת החסדים המסבבים את עץ הדעת, ושולטים עליו, וזוכה לד' חיות. אריה שור נשר אדם, שהם נהי\"מ, שה\"ס המרכבה התחתונה, המתגלגלים בד' רוחות, שה\"ס גילוי הארת החכמה, שנצח הוד הן דרום צפון ויסוד ומלכות הן מזרח ומערב. (כמבואר בארוכה לעיל בראשית א' פ\"ד ד\"ה פני אדם) והארת החכמה אינה מתגלה אלא בסוד הגלגול שלהם כנ\"ל (בתוספתא ויחי אות קכ\"ז, ע\"ש בהסולם. ועי' לעיל, בשלח ל\"ט ד\"ה וגו'.)"],[5,"חויא דרהית בש\"ע","וכו': נחש הרץ בש\"ע דלוגים. מדלג על ההרים מקפץ על הגבעות זנבו בפיו בשניו, ניקב בשני צדדים, כשנוסע נפסק ונחלק גופו לשלשה צדדים."],[5,"","פירוש. אחר שכבר ביאר סדרי הארת החכמה בכל הסדרים, מבאר עתה ומסיים הענין בבחינת השמאל בפני \u0003עצמו,\u0004 דהיינו רק מאור החכמה ביחסו עצמו, שמכונה נחש, (כנ\"ל אות ט') ואור החכמה מכונה שעשועים, בסוד שהקב\"ה משתעשע עם הצדיקים בגן עדן. (כנ\"ל בא אות צ\"ח ואות ק') וז\"ש \u0003חויא דרהיט בש\"ע דלוגין,\u0004 דהיינו קו השמאל המכונה נחש שהוא מגלה חכמה המכונה ש\"ע ושעשועים, בריצה, בסוד והחיות רצוא ושוב, ובדלוגים \u0003דכתיב מדלג על ההרים מקפץ על הגבעות.\u0004 הרים הם חג\"ת, ששם החסדים מכוסים, ואין מקום שם לגילוי חכמה, וע\"כ החכמה מדלגת עליהם שלא להאיר בהם, והיא מקפצת ומאירה על הגבעות שה\"ס נה\"י, שבהם החכמה מתגלית. \u0003זנביה בפומיה, בשנוי,\u0004 כי בחינת הדינים שלו שהיו בסיומו מתחילה נתקנו שיהיו בבחינת ראש, בפיו בשניו. (כנ\"ל אות לו ט') \u0003נקיב בתרין גיסין.\u0004 הוא מנוקב בשתי בחינות, אחת, היא מבחינת הדינין דמנעולא המתוקנים בג\"ר המדרגה, ששם שורש המתקלא. ואחת היא מבחינת הדינין דמסך דחירק שבקו האמצעי, ששם עמידת המתקלא, (כנזכר לעיל אות ה') ולולא ב' כוחות האלו הממעטים אותו, לא היה נכנע להתיחד עם קו הימין. כמ\"ש שם."],[5,"","ונודע, שאין הארת החכמה מתגלה בקו שמאל כשהוא לבדו, מחמת שהוא מחוסר חסדים, אלא בצירוף שלשת הקוין ביחד. שאם היה חסר קו אחד מהם, לא היתה החכמה מאירה, כי אם היה חסר קו הימין, לא היה השמאל מאיר מחמת חסרון חסדים, ואם היה חסר קו האמצעי, לא היה השמאל מתיחד עם הימין לקבל ממנו חסדים, כנ\"ל. וז\"ש \u0003גיסטרא אתעביד לתלת רוחין,\u0004 שהחויא שהוא קו השמאל, נפסק, ונחלק לשלש רוחות, דהיינו לשלשה קוין. כי אין החכמה שבו מאירה מגופו עצמו לבדו, דהיינו מקו שמאל לבדו, אלא ע\"י חיבור שלשת הקוין יחד, כנ\"ל, ונבחן שגופו נחלק בין שלשה קוין, שכל קו נושא חלק אחד מגילוי גופו, וכשמצטרפים יחד הוא מתגלה. \u0003גיסטרא,\u0004 הוא מלשון, לכל טפה וטפה וכו' גסטרא בפני עצמה, דהיינו מחלקה. (ויקרא רבה ט\"ו)."],[6,"כתיב ויתהלך","וגו': כתוב, ויתהלך חנוך את האלקים. וכתוב, \u0003חנוך\u0004 לנער על פי דרכו. היינו לנער הידוע, שהוא המלאך מטטרון. וז\"ש, \u0003חנוך,\u0004 נעשה, \u0003לנער,\u0004 ממטרון. \u0003את האלקים,\u0004 היינו המלכות, ולא את הויה, שהוא ז\"א, כי נעשה למשמש אל המלכות. \u0003ואיננו\u0004 פירושו שאיננו בשם זה, חנוך, \u0003כי לקח אותו אלקים,\u0004 להקרא בשמו. שנעשה מלאך האלקים."],[7,"תלת בתי דינין","וכו': \u0003ג' בתי הדינים,\u0004 שהם ג' הזריעות שבחולם שורק חירק (כמ\"ש לעיל בראשית א' ט\"ו ד\"ה ההיא ע\"ש), שהם ג' מיני דין שבג' קוין, \u0003הם ארבע.\u0004 כי קו האמצעי כולל בעצמו ב' מיני הדינים שבחולם ושבשורק, והם ד' בתי דינים, כי בחולם יש דינין דנוקבא שהיא המלכות שעלתה לבינה, ובשורק יש דינין דדכורא, שהוא סיתום החסדים, שתיהן יש בקו האמצעי הכוללם. \u0003ארבע בתי דינים למעלה,\u0004 באו\"א שבז\"א, שיש שם ד' מוחין חו\"ב חו\"ג. \u0003ארבע בתי דינים למטה,\u0004 בישסו\"ת שבז\"א, אע\"פ שיש שם רק ג' מוחין חו\"ב ודעת, עכ\"ז כולל הדעת ב' מיני הדינים שבחו\"ב כנ\"ל. \u0003שכתוב לא תעשו עול במשפט במדה במשקל במשורה\u0004 אשר משפט הוא קו ימין, מדה הוא קו שמאל משקל הוא קו האמצעי, במשורה היא מלכות. ומפרש, שיש \u0003דין קשה,\u0004 והוא דינין דשורק. ויש \u0003דין שאינו קשה\u0004 והיינו הדינים דחולם, ויש \u0003דין במשקל,\u0004 דהיינו בעת שנכללים בקו האמצעי ב' הדינים שקולים הם בחיבור אחד, וזהו בישסו\"ת דז\"א, שנחשבים רק כג' מוחין, חב\"ד. ויש \u0003דין שלא במשקל\u0004 השוה, שב' הדינים שבקו האמצעי אינם שקולים, וזה ניכר בפני עצמו וזה ניכר בפני עצמו. וזהו באו\"א שבז\"א, שע\"כ נחשבים ד' מוחין: חכמה ובינה חסד וגבורה. ויש \u0003דין הרפה,\u0004 שאין בו \u0003אפילו לא זה ולא זה,\u0004 לא דין קשה ולא שאינו קשה, והיינו קו שמאל דנוקבא, שאין בו דין קשה דשמאל דז\"א, (כמ\"ש בזהר אמור דף ק' ע\"א ד\"י, ד\"ה סדרא תנינא ע\"ש) ולא דין שאינו קשה מימין דז\"א, שהרי הוא שמאל ולא ימין."],[8,"ויהי כי החל","וגו': ויהי כי החל האדם לרב על פני האדמה. החל האדם לרב, היינו שכתוב, בשגם וגו', אשר \u0003בשגם\u0004 הוא אותיות \u0003משה ש' מ'\u0004 וב\"ג שהן \u0003ה'.\u0004 וע\"כ אומר הכתוב, \u0003האדם\u0004 שרומז על אדם העליון דהיינו משה, שהוא מרכבה לז\"א, וכתוב, על פני האדמה. אע\"פ שמדרגת משה היתה למעלה בז\"א שנקרא שמים, כי כתוב, ומשה לא היה ידע כי קרן עור פניו. היינו שכתוב, כתנות עור. שפירושו בחנות ממלכות."],[8,"","פירוש. \u0003עור\u0004 היא שם המלכות, \u0003קרן\u0004 הוא שם המלכות המלבשת את הבינה למעלה. ומשה לא ידע מזה שהמלכות שלו היא מלכות עליונה הדבוקה בבינה, וע\"כ כתוב בו, על פני האדמה, שפירושו מלכות סתם. כמ\"ש לפנינו."],[9,"קרן, דכתיב ויקח","וגו': ומ\"ש \u0003קרן\u0004 עור, הנה קרן, הוא כמו שכתוב, ויקח שמואל את קרן השמן. אין משיחת מלכים אלא בקרן, וכתוב, ובשמך תרום קרננו, וכן, שם אצמיח קרן לדוד. והיינו העשירית של המלך, שהיא מלכות שהיא ספירה עשירית דז\"א, ובאה מן יובלא שהוא אמא, שכתוב והיה במשוך קרן היובל. הקרן, שהוא מלכות נתעטר ביובל, דהיינו העשירית נתעטרה באמא, שהיא בינה, שמלבישה אותה ונעשית כמו בינה, ונקראת קרן, משום שהמלכות לוקחת מן הבינה שהיא יובל, קרן ורוח שבו, שתשוב אליה הרוח של הבינה, דהיינו המוחין שלה."],[10,"והאי קרן דיובלא הוא,","וקרן הזה הוא של יובל, ויובל, שהוא אמא, היינו \u0003ה'\u0004 ראשונה של הויה. ו \u0003ה'\u0004 זו נושבת רוח חיים לכל, וכולם חוזרים, למקומם. דהיינו כמ\"ש בשנת היובל הזאת תשובו איש אל אחוזתו. שכתוב אהה אדני אלקים, דהיינו הויה בנקוד אלקים, שהיא בינה, ואדני, הוא מלכות. כשנראה \u0003ה'\u0004 ראשונה ל \u0003ה'\u0004 תחתונה דהיינו בינה למלכות, דהיינו ששתיהן מלובשות זו בזו, נקרא בשם מלא, אדני אלקים. וכשתהיה הלבשה זו בקביעות, דהיינו לעתיד לבא, אז כתוב, ונשגב ה' לבדו ביום ההוא. עד כאן נסתם ונתעטר צניעותו של המלך, דהיינו ספר הצניעות. אשרי מי שנכנס בחכמה ויצא, ויודע שביליה ודרכיה."]],[]]]};
